/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20131008-4","meetingId":"h25-c-settlement","date":"2013年10月8日","dateIso":"2013-10-08","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を145件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまから決算特別委員会を開会いたします。 それでは、平成２４年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまから決算特別委員会を開会いたします。 それでは、平成２４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１５４ページ、１５５ページの自転車の交通安全について、自転車走行レーンとあわせてちょっとお伺いしたいと思います。自転車の交通安全のことでお伺いしたいんですけれども、近年いろいろ自転車交通安全ということでいろいろと言われていますけれども、改めてこの品川区内における、まず自動車と自転車の事故の件数、そして人と自転車の事故の件数の推移、大体どういう状況なのか教えてください。","respondent":"谷口交通安全担当課長","answer":"委員からのご質問の自転車の事故、人との事故の推移ですけれども、自転車の事故につきましては、昨年は３９６件発生しております。そのうち死者が２名ということですので、全体的な事故については１,１１１件発生しております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"減少はしているとはいっても、３５.６％という依然として大変多い数だと思います。それと、品川区は青くなっているところがありますけれども、単純に青くなっているところと、なっていなくて自転車のマークだけがついているところがあるんですけれども、ああいった規格というか、ああいう状況の違いというのはどういう意味があるのかということをお伺いさせていただきたいと思います。","respondent":"稲田道路課長","answer":"は区内の自転車走行レーンの整備状況ですが、平成２１年度に立会道路、路側帯に色をつけまして整備しました。平成２４年度には都市計画道路の整備、２０５号線と合わせまして、２０５号線の一部カラー化を実施しております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"色がついているところ、ないところとあるということなんですけれども、やっぱり青いところがあると安心して自転車は走れる。その自転車の走行のルールで、基本的には車道を走ると。特にそういう道路はたくさんあると思うので、やっぱりそういったところのわかりやすい表示の仕方というのを考えられないかなと思うんですけれども、そういったことについてお伺いさせていただきたいと思っています。","respondent":"稲田道路課長","answer":"そこは今後、警視庁とどのような形で表示というのができるのかどうかというのは検討課題ですが、現在のところは警視庁の見解はそのような見解です。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"だから、歩道のほうを広げるほうを考えていただきたいなと思います。公園や児童遊園にある健康遊具についてお伺いさせていただきたいんですけれども、大人向けのというか、高齢者向けの健康遊具ですけれども、現在品川区の、まずその前に品川区の公園の利用者の幼児と高齢者の比率というのは、大体幼児５歳以下と６５歳以上の比率というのは、そういうのというのは統計というのはあるでしょうか。","respondent":"多並公園課長","answer":"公園利用者の比率ですが、そのような統計は現在ございません。ただ、利用者の中では、公園の中で利用者の方々が、子どもが使うゾーン、また高齢者の方が憩うゾーンというのが、大きな公園については分かれながら、その中でご利用いただいている、そんな状況です。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"区内でも幾つかの公園で、健康遊具ということで高齢者向けの遊具、また整備されているかと思うんですけれども、今、品川区内では何カ所にあるのか。それと、どこら辺にあるのかということをお聞かせください。それからあと、近年、健康遊具、新しく新設された、新設というか、改良された、改修された公園で整備されたりとかということがあるのかということをお聞かせいただきたいと思います。","respondent":"多並公園課長","answer":"近年の設置の状況ですが、この決算の平成２４年度の中でも、北浜公園で、これにつきましては、高齢者福祉部門と連携を図りまして、ハード整備として区のほうが行い、ソフト施策としてそれを、いきいきうんどう教室など。","voiceIndex":12,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"地域の方からお話があって、その方は中国に旅行されたみたいだったんですけれども、西安市という中国の地方都市ですけれども、昔の長安ですけど、行かれたときに、そこの公園にそういう健康遊具がいっぱいあったという話で、自分の地域に帰ってきて、どこにあるのかがわからないという話で、私もその話でこの質問をさせていただいているんですけれども、ちょっと調べたんですけれども。","respondent":"多並公園課長","answer":"健康遊具につきましては、今後施設の改修時期に合わせまして、地域の皆様のご意見をお聞きしながら、設置してまいりたいと思います。広報につきましても、ホームページ等、わかりやすい広報ということで、今後改善してまいりたいと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"景観ですが、区内の花の状況については、事前に公園課の皆様に教えていただきまして、落葉樹の中の中高木の中で、いわゆる桜の木が一番多いというふうに伺っておりますが、その桜、公園以外でどういうところに植えられているのかということと、それから、種類ですね。","respondent":"多並公園課長","answer":"種類につきましても、桜の中でもソメイヨシノがやはり地元の方からもご要望が多いということで、そのようなことで植えさせていただいているものです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"改めて自分で調べたいと思います。それで、いろいろな種類、ソメイヨシノが一番多いということで今おっしゃっていただきましたが、かむろ坂、我が家の目の前なんですが、春の時期になるとすごいきれいなんですけれども、ホームページを見ますと、品川区の桜の名所の一覧ということで出ているんですが、品川区内にある桜地図みたいなものというのは作成したことってありますでしょうか。","respondent":"多並公園課長","answer":"桜の地図というものは実はございません。ただ、桜の時期になりますと、ホームページの中でお知らせさせていただいたり、そのようなところで区民の方には知っていただくような形をとってあります。","voiceIndex":22,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"そうした２０年という締めも含めて、私個人的にはこの品川区、本当に花のたくさんある、より一層本当にそういう区にしていきたいという思いがありまして、その中でなおかつこの桜をもっと増やしていきたいな、そういう思いからのお尋ねなんですけれども、区の新しいシンボルとして、区内にある駅ですね、駅周辺に桜の木を植えていったらどうかなと、こういうふうに思うんですが。","respondent":"藤田都市計画課長","answer":"桜についても、駅前のことも、先ほど申したとおり、さまざまな調整の中で検討をしていくべきかなと考えています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"次に行きたいと思います。時間の関係で一旦は要望にしたいと思いますけれども、地元の方から、小山台東公園、またあさひ公園、こうしたところにだれでもトイレをつけてほしい、こういうご要望がありますので、昨日他の委員からも質問がありましたので、時間があれば、後でまた聞きたいと思います。次に１６１ページ、公園整備事業なんですけれども、公園の遊具の整備の流れ、これについて教えてください。","respondent":"多並公園課長","answer":"遊具の整備の流れですが、公園を整備する際に設計を行います。","voiceIndex":26,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"ゾーニングというか、そういうゾーン分けをして安全を確保されながらということで、今年になってお聞きする中では、遊具のいろいろ集約というんでしょうか、あとまた防災の観点で、そういった広いスペースを確保するよという中で、集合遊具というんですか、名前はわかりませんけれども、そうした流れになるのかなというふうには聞いていますけれども、その辺も含めてなんですが、平塚公園、スクエア荏原。","respondent":"多並公園課長","answer":"新たな遊具の整備という点につきましては、また別の場所に設置いたしますと、いわゆるスクエア荏原のホールのほうを利用される方の動線と遊びで子どもたちが遊ぶ動線とが交差する部分も出てくるということで。","voiceIndex":28,"id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"次に行きます。１５４ページ、駅周辺等についてです。これ、かつて一般質問でも私、２年前ですかね、質問させていただいて、子どもの絵による違法駐輪の対策のシート、それを違法駐輪が多いところに張ってということを大阪の事例を通して提案をさせていただいて、そのときの部長の答弁ですと、区としても関心を持って調査や情報の収集を行っていると。","respondent":"谷口交通安全担当課長","answer":"委員ご提案いただきました路面のシートですが、品川区としましては、平成２０年以降、路面の放置駐車禁止ということでやっておりまして、大体８０枚ぐらいは路面にシートを張っております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"恐らく本庁というか、警視庁本庁とそれから現場の所轄というんでしょうか、いろんな考えが、それぞれの地域性というか、こういったことがあるのかなと、勝手な想像なんですが、江東区にも既に調査されているかどうかあれですけれども、そのやり方というんでしょうか、こういったところも含めて、ぜひ何らかの形で、非常に私は、小学生もそういった違法駐輪対策に貢献できた、社会に貢献できたという。","respondent":"谷口交通安全担当課長","answer":"ただ区域外につきましては、条例上なかなか撤去できないですので、ただ計画的に警告をして撤去しているという状況です。引き続きやっていきたいと考えています。","voiceIndex":32,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問","question":"じゃあ、そうしたいわゆるスクールゾーンというんですか、通学路を中心に先ほどのシートですね、検討いただければと思います。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"木村委員","kind":"質問","question":"１５７ページの下から７行目、排水施設建設事業、そして１５９ページの一番上にあります河川管理費からの質問をいたします。この豪雨に対して本区のお考えを再度お聞きしますけれども、１時間に５０ミリが限度と聞いておりますが、７０ミリや８０ミリ、１００ミリを超えるような雨量が日本のあちらこちらで降ったと聞きます。その３点をお答えください。","respondent":"奥田河川下水道課長","answer":"実際の浸水対策といたしましては、我が区では東京都と連携いたしまして、河川とか下水道の対策を実施しておりまして、特には昭和６１年度からというのは、一部事業を受託して、それでスピードアップして、ほかの区よりも優先的に実施しているというようなことがあります。","voiceIndex":36,"id":"exchange-015"},{"speaker":"木村委員","kind":"質問・要望","question":"そのときに、例えば七十数ミリの雨が降ったということでありましたけれども、そのときの状況はどうだったのか、また教えていただきたいと思います。下水道の工事がまだいまだ東京都全体で完成していないということも聞きました。いつを目途に完成予定なのか、それもお答えください。","respondent":"奥田河川下水道課長","answer":"時間当たり７０ミリを記録したということで、実は本年の７月２３日の集中豪雨のとき、区内で時間最大７４ミリを記録したんですけれども、このときというのは、実はこれまで都と連携して整備してきた下水道ですとか。","voiceIndex":38,"id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"本区は、目黒川、荏原調整池、そして目黒川の船入場ですか、調整池、二つの大きなあれがありますけれども、それ以外にも大小８カ所の調整池があるということですけれども、参考までに、今回の台風、先日ありましたけれども、貯留量はどれぐらいの貯留量があったのか、お聞かせをください。そして、すべての調節池の貯留量というんですか、それはどのぐらいの量を貯めることができるのか。","respondent":"奥田河川下水道課長","answer":"今の浜川の雨水幹線ですとか、あるいは勝島の雨水調整池のところで、それが完成すればということなんですけれども、そういった下水の整備ということで、今７０％を超える形になっているんですが、それが８０％近い形ということで、大幅に進捗するような形になると考えています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"確かに荏原の調整池ですか、これ、今お話ありました２０万立法メートルですよね。目黒川の船入場ですか、調整池、これは５万５,０００立法メートルですか、これ、こちらが勝手に計算しましたけれども、２５メートルプールで大体１６０杯分ぐらいになるんじゃないかということを計算しました。下水道整備が完成していないから何か東京都に対して申し入れがだめということなんでしょうか。","respondent":"奥田河川下水道課長","answer":"ということで、５０ミリを超える対策につきましても必要だということを認識してございまして、そういったのはやっていく必要があると聞いてあります。","voiceIndex":42,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひ区長、頑張っていただきたいと思いますけれども。東京都に対して本当に強い申し入れというものがやっぱり必要だと思います。ぜひともお願いをいたします。先ほどから何度も申し上げますけれども、本区として本当にぜひ東京都に対し、強い姿勢で要望していくと考えていますけれども、今、ほかの委員から話もありました、２０２０年には東京オリンピック・パラリンピックがまた開催されます。","respondent":"奥田河川下水道課長","answer":"ただ、今委員ご指摘ございましたように、そういった５０ミリを超えるような超過降雨というのも頻発しておりますので、今後とも引き続き都との連携を一層強化するということで積極的に働きかけるとともに、安全で安心な品川区の実績を目指しまして。","voiceIndex":44,"id":"exchange-019"},{"speaker":"藤原委員","kind":"確認","question":"１年半を思い出していただいて、そのときの思い、そして、１年半が過ぎてどういう成果が出ているのか、そして、あと、どのぐらいいてくれるか全くわかりませんが、その後の目標についてお伺いしたいのと、それとは別に、ほかの自治体でも交流というのはあると思うんですが、大体が階級でいうと警部補とか巡査部長の階級だと思うんですけれども。","respondent":"谷口交通安全担当課長、奥田河川下水道課長、中村建築課長、大串住宅担当課長","answer":"引き続き、まだいつまでいるかもわかりませんけれども、一生懸命頑張って、１件でも事故を減らしたいと考えているところです。本地区は、東京都で実施する事業となっているんですけれども、過去にもたびたび、委員からご指摘のように、浸水被害が発生しておりまして。その中で区が確認をしたものが１０２件ということで、全体の９.１％になります。あわせて、退去した場合に、今現在は原状回復工事というのを実施しております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、庁舎なんですけれども、駐輪場が何台分ぐらい確保されているのか。だけれども、２０年の契約期間が終わったんですから、何回も質問していますが、整々粛々と契約が終わった時点でお返ししていくということで、修繕費がどうのとか、契約にそれは入っていないんですから、２０年でお返ししますということを確実に着実に整々粛々とやっていただきたいと思うんですが、いかがでしょうか。","respondent":"谷口交通安全担当課長、平澤経理課長、堀越人事課長、中村建築課長、奥田河川下水道課長、大串住宅担当課長","answer":"昨年度は１万８,０００台ということで、指導啓発の効果が出ていると思っているところです。次に職員用ですが、現在外壁の改修工事を実施しているということで、ちょっと場所は移ってしまったんですけれども。庁舎に勤務している職員のうち、自転車利用で通勤手当が支給されている人数は７０名です。１級建築士の資格を持った者が今建築課内の確認申請の審査の係、それから狭隘道路を広げる細街路の係、あるいは。","voiceIndex":53,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"西大井の件ですけれども、西大井四丁目、五丁目の方が、本当にこの件に関しては心配しておりました。早速課長の答弁をいただいたので、このことを地元の方にちゃんとお知らせをしますので、確実な事業執行をよろしくお願いいたします。もう１点は、下水道じゃなくて、上水道、そもそも上水道の耐震化は必要じゃないんですかという質問なんですけれども、お願いします。","respondent":"鈴木防災課長、小林施設整備課長","answer":"ただし、上水道につきましては、東京都のほうの実施事業になりますので、区といたしましては、都と連携をしつつ、より区内の整備状況、耐震化が進むように働きかけをしていきたいと考えております。学校の耐震化の質問ですけれども、学校の１系統、便所の１系統を耐震化を行っております。場所については、避難所の体育館の近くだとか校庭の近くだとか、いろいろ学校によって若干違いますけれども、１系統を耐震化しています。","voiceIndex":60,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"シミュレーションのほうですけれども、東京都より資料が公開されました。伺いますけれども、風向きについてです。改定された地域防災計画では、冬１８時にどの方向から吹くとの風向きなのか。そしてこの延焼シミュレーションでは、同じく冬１８時にどの方向から吹くという風向きなのか、伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"東京都からの延焼シミュレーションの風向きのほうについては、風速のみしか、風速８メートルというふうには聞いているんですが、方向のほうについては現在聞いておりません。","voiceIndex":64,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"品川区の防災計画上は北北西と設定されています。４５度異なる風向きで、なぜこのシミュレーションが２９号線の防災に役立つ根拠と言えるのか、伺いたいと思います。結局防災計画どおりの北風が吹けば、２９号線で延焼が遮断するどころか、縦に伸びる２９号線に沿って火災は上から下に燃え広がってしまうのではないかと思いますけれども、いかがでしょうか。","respondent":"品川木密整備担当課長","answer":"地震の後の火災というのは、確かに風の向きのほうには大きくは延びていきますが、全体的に広がって火災が延びていくというような形になりますので、風向がどうだとか、そういうことで道路の延焼遮断効果がないというふうには区としては考えておりません。","voiceIndex":66,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"風向きだけではなくて、もっと横にも広がっていくんだという説明ですけれども、要するに、４５度も異なる風で、じゃあ、何で２９号線が防災の役に立つのか、改めて伺いたいのと、結局これでは上から下にも横にも広がってしまうと。２９号線で延焼が遮断するという説明は成り立たないと、事実が異なると思いますけれども、いかがでしょうか。","respondent":"品川木密整備担当課長","answer":"先ほど私が申し上げたのは、道路のないところでの火災の燃え方についてご説明をしました。当然道路のあるところでは火災は止まるということで考えております。","voiceIndex":68,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"２９号線のシミュレーションは、道路に向かって吹くと。つまり、４５度異なります。このシミュレーションで２９号線が防災計画の役に立つと言えないのは私は明らかだと思います。これ自体重大な問題です。区は、２カ所突破する２９号線でも防災対策に役に立つと思っているのか、伺います。風向きだけでなく、実際の震災とは異なるこのシミュレーションでどうして防災に役立つと言えるのか伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"ただ、その時代は、当然わらぶき屋根とか、そういうような時代です。現状を考えてみますと、木造住宅、耐火建築物も多くなっている時代です。火の粉が飛んだからといってそう簡単に延焼するようなものではございません。","voiceIndex":70,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"そのシミュレーションであっても、２カ所が突破されています。火の粉の話がありました。その結果が、以前にも紹介しましたけれども、２２メートル道路ですけれども、１５カ所で火災の延焼が突破されたと。２９号線もこの設定でシミュレーションを行えば、２カ所よりもさらにもっと増えるだろうと容易に想像できます。これでもなぜ防災に役立つと説明ができるのか、改めて伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"ですので、我々が何度も説明しているように、延焼遮断帯というのは、道路があって、沿道周辺が耐火建築物になる、こういうことによって延焼遮断帯の効果が出てくるです。","voiceIndex":72,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"続いて都市計画道路の用地買収についても伺いたいんですけれども、計画道路上の方々から補償はどの程度されるのかと不安の声がたくさん上がっています。ずばり都市計画道路をつくる際の用地買収補償について、これは公共事業ですので、基本的に同じルールで行われると伺っておりますけれども、土地の価格は話し合いで決まるのか、誰が土地の価格を決めるのか、そこを伺いたいと思います。","respondent":"河内用地担当課長","answer":"土地の価格の件についてのご質問です。こちら、都の事業ですので、あくまで一般的なものの考え方で答弁を行わせていただきたいと考えています。根拠になりますのが、公共用地の取得に伴う損失補償基準というものに沿って補償額が決定されるものです。","voiceIndex":74,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"ちょっとよくわからないんですけれども、要するに土地の価格は、住民と区、または住民と東京都、事業主によって変わってきますけれども、話し合いによって決まるのか、誰が決定するのか伺いたい。建物の価格は、建物の経年劣化分は補償額の対象に含まれるのか、伺いたいと思います。","respondent":"河内用地担当課長","answer":"土地の価格の決定です。こちらにつきましては、先ほど申しました補償基準に従いまして行われるものです。したがいまして、不動産鑑定士の方が鑑定した価格をもとに決定されるものと認識しております。","voiceIndex":76,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"建物の価格は、経年劣化分は補償額に含まれないと。要するに、仮に同じ土地の広さ、同じ土地の価格で引っ越し先が見つかっても、自分の持ち出しがなければ今と同じ家を建てることができないと、そういう仕組みになっているのでしょうか、伺いたい。やっぱりこういう計画そのものはやめるべきだと思いますけれども、いかがでしょうか。","respondent":"河内用地担当課長","answer":"つまり、減価償却につきましては控除するという考えに至っております。話し合いで決まるものでなく、一定のルールの中で、全国共通公平に決まっているものと認識しております。","voiceIndex":78,"id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"何点かお聞きします。６項住宅費２目区営住宅費、３目区民住宅費の中で。１６５ページです。この中で、区営住宅費、滞納使用料と納付促進委託３万円とあります。区民住宅費の中にも滞納使用料の納付促進委託８万８,０００円、これが借上型で、建設型は同じく３万円となっています。そして、区民住宅の中には、長期滞納者対応経費が５４万５,０８０円、１４２万５,１６０円でしょうか、書いてあります。","respondent":"大串住宅担当課長","answer":"その方につきましては、なかなか我々職員のほうでは対応が難しいということで、弁護士の方に、法律事務所のほうに委託をしているものです。こちらに上がっております３万円という金額ですが、これはその弁護士に委託で払っています事務費ということになります。","voiceIndex":81,"id":"exchange-031"},{"speaker":"松澤委員","kind":"質問","question":"滞納使用料納付促進委託、弁護士にお願いしているけれども、実効は上がっていないということですけれども、今年の予算書を見ると随分上がっていますよね、金額が。同じ滞納経費が出ているんですけれども、２０万円とか６０万円とか。２０万２,０００円、６４万円、２９万４,０００円。実効が上がっていないのに何でこうやってまた予算を大きくつけているのか、そこもちょっとお聞きしたいと思います。","respondent":"大串住宅担当課長","answer":"指定管理者を通じまして、滞納の少ない段階、１カ月ですとか２カ月、これぐらいの少ない段階での納付指導、納付促進、これを徹底して行っているといったところですが、それに基づきまして、現年度分の滞納額、それほど増えていないという状況ですけれども。","voiceIndex":83,"id":"exchange-032"},{"speaker":"松澤委員","kind":"質問・要望","question":"ところで、この区民住宅、区営住宅、何ていうんですかね、不納未済額というんでしょうか、期日までにお金が入らない。滞納して、これがまた裁判になりそうなんだというのでなくても、例えば月末ぎめが１週間ぐらい、二、三日ずれちゃったよというのも含まれていると思うんですが、金額多いですよね。これについてどのように考えているのか、ちょっとコメントをいただきたいと思います。","respondent":"大串住宅担当課長","answer":"先ほど言いましたように、１カ月、２カ月少ない段階での促進をしておりますし、また連帯保証人さんへの連絡といったことも２カ月目から行っているという状況です。なかなかそういった中でも滞納が増えているというのは、大きな課題と考えているところです。","voiceIndex":85,"id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"ですから、滞納が少ない。これ、指定管理者がいるんですから、やっぱりこれ、しっかりやらすべきじゃないんですか。滞納額が増えるようだったら指定管理者かえるということも考えるべきだと思うんですけれども、ちょっと甘いんじゃないかと思って、その辺しっかりとお聞きしたいと思います。","respondent":"大串住宅担当課長","answer":"そうしたことを防ぐためにも、少ない段階でということで指定管理者のほうについても強く指導して、今現在もそのような形で、１カ月、２カ月目、少ない段階から滞納者、滞納がなるべく膨らまないようにということで指導を強くしていますし、また、我々住宅担当のほうでも。","voiceIndex":87,"id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"２点目に参りたいと思います。１６４ページ、耐震改修工事助成。これは木造住宅密集地、木密地域で、何としても４メートルに広がるようにということで、建物を建てるときは避けてくださいよという形で、今ジグザグでもいいですよという形で進んでいると思うんですが、この事業内容を両方ともお聞きしたいと思います。","respondent":"品川木密整備担当課長、中村建築課長","answer":"改修工事につきましては、区内全域でやっております。ただ、建替え、それから除却につきましては、品川区内の俗に言われます木密地域ですと、３分の１ぐらいの地域、ここを対象としております。細街路拡幅整備事業ですけれども、こちら、委員言われましたとおり、道路を４メートルに拡幅すると。その目的ですけれども、まず災害時の安全性、これは当然のことながら、これを高めていく。","voiceIndex":89,"id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"ところが、その建物が、建て直すんじゃなくて、耐震改修しましょうという話、区に来た場合どうなるんですかね。２項道路、下がらなくちゃいけないものを耐震改修で、しかも個人の財産である個人住宅を品川区が違法な状態の中を助成して、それに援助して、下がる道路を下がらないようにしている、この政策がどうしても私は納得いかないので、その点について説明してください。","respondent":"品川木密整備担当課長","answer":"例えばやっぱりどうしても土地の関係等で大分建物がなくなってしまうとか、そういう場合については、少しでも下がっていただいて改修をしていただくというような形で指導をしながら改修のほうは進めている状況です。","voiceIndex":92,"id":"exchange-036"},{"speaker":"松澤委員","kind":"意見","question":"次に行きたいと思います。１６１ページ、三井文庫補修工事。これは大変にすばらしい公園ができた。私も何回か行っているんですけれども、三井文庫の改修、２,１３２万５,５００円。三井文庫は、当初取り壊すべきだ、いや、しっかり残すべきだよといういろんな意見の中で残すことになりました。その改修経費、残ったのはいいんですけれども、２,１３２万円。この内容について聞きたいと思います。","respondent":"多並公園課長","answer":"ただ、補修と申しましても、外壁の補修に加え、屋根の張りかえや内壁と床の補修等、いろいろな中身のですね、補修といっても、結構大きな補修も行いながら、構造自体はいじくらず、残すような形で行っているというのが今回の内容です。","voiceIndex":94,"id":"exchange-037"},{"speaker":"松澤委員","kind":"質問","question":"ただ、やはり今締めっ切りになっていますけれども、中は防災倉庫式になっているようにも聞いているんですけれども、これ、やはり年に何回か、これだけお金かけたというのと、また、大変に防災機能、当時の防災機能すばらしかったんだという一つのあかしでもあるので、公開日を設けなくてはいけないなと思っているんですけれども、それの公開なんかについてはどう考えているでしょうか。","respondent":"多並公園課長","answer":"三井文庫自体が耐震性という部分では保証できるものではないということがまず大きなところであるので、常設というわけにいきませんが、イベント等で、我々が管理できる中での公開という形ではできるかと考えていますので。","voiceIndex":96,"id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"擁壁の上に建っているいろんな建物について、建替えですとか、いろんなことをすることが必要になってくる場合があると思いますけれども、擁壁というのは、建築基準法とかの基準とか規制の中で、何年か経年したときには手を入れて直さなきゃいけないとか、つくり直さなきゃいけないとか、そういった規制、制限、何かしら手を入れないとそのままでは使い続けることができないというようなものがあるのかどうか。","respondent":"中村建築課長","answer":"ですので、具体的に何年という寿命はございませんけれども、建築の機会などを捉えて、擁壁の検査を、調査をしてもらって、そしてその強度を確認していただいて、そこで強度がなければつくりかえていただくというような方法です。","voiceIndex":99,"id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"そうなってくると、その１軒１軒がそういった擁壁の管理、一部だけを強度、補強するという、そういう一つの擁壁の上に何軒も建っているところの１軒が建て替える、そのときに補強の負担をしなきゃいけないみたいなことが起こると、なかなかそれというのは難しいんじゃないかというところがあるかと思うんですけれども、その辺について、まず区がどのようにご認識をしているか、お伺いしたいと思います。","respondent":"中村建築課長","answer":"すなわち、建物が、杭などを打ちまして、擁壁のさらに下のほうまで杭を打って、擁壁に土の圧力がかからないようにしていただくと、そんなようなことを現実的な対応として行っております。","voiceIndex":101,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"区有施設についてはもちろんそれはしっかりやられていると承知しておりますけれども、いわゆるまちの品川区内の擁壁の危険度、こういったものを現在品川区としてどの程度情報収集なり掌握をされているか、現状をお伺いしたいと思います。","respondent":"中村建築課長","answer":"建物に付属する擁壁につきましては、これは建替えの機会を捉え、順次安全性を確認していただくということで、また一般の擁壁、あるいは崖ですね、こういったものにつきましては、例えば擁壁などが崩れたときに、大体おおむね５棟以上に被害が及ぶような規模のものにつきましては。","voiceIndex":103,"id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"例えば擁壁の状況調査をしてのマップみたいなものをつくって、どこに品川区の擁壁の危険というものが存在しているのか、そういったことをぜひ検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"中村建築課長","answer":"今、複数の棟に被害が及ぶ擁壁などについて４３カ所と申し上げましたけれども、また、それ以外のものにつきましても、擁壁だとか、あるいは斜面の安全性なんですけれども、こちらは、ただ目視だけでそれが安全か、あるいは危険かというのを判断するのは非常に難しい話です。","voiceIndex":105,"id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"続きまして、１５５ページの路面維持管理費に関しまして、まずいわゆる公道に、ごみ屋敷に関連してちょっとお話をお伺いしたいんですけれども、公道に接しているごみ屋敷等があった場合に、ごみ等が道路にどんどん侵食をするというか、出てきてしまった場合は、これは区の今対応としては、これは撤去をするという、公道の場合ですね、区道とか都道とかも含めてですけれども。","respondent":"安井土木管理課長","answer":"公道、まあ、区道の場合ですけれども、基本的に道路法の４３条のほうの「何人も道路に関し」というところで、２号のところに、「みだりに道路に土石、竹木等の物件をたい積し。","voiceIndex":107,"id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"今命令を出すということでございましたけれども、それで撤去していただければいいんでしょうが、仮にごみ屋敷の場合はなかなかそういうことがうまく進まないことが多々あるかと思いますけれども、そういった場合には、過去の事例としてあればご紹介していただきたいし、仮にないにしても、そういうことがあった場合には、これは区としては、今の法にのっとって行政代執行のような形でこれは撤去できるものと。","respondent":"安井土木管理課長","answer":"こちらの命令に違反しまして、現状のままそのまま放置するということになりますと、道路管理者としては、法の第７１条１項の規定によりまして、監督権を発動して、必要に応じて代執行等の処分をしていかざるを得ない。","voiceIndex":109,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"で、位置指定道路の所有者に対しての著しい不利益がない限りは、日常の交通の利用に、通行を妨害してはならないと、こういったことも書かれているものもあるんですけれども、こういった通行を妨害してはならないんだという位置指定道路の考え方から、こういった先ほどの公道に類するごみ屋敷のごみの通行をとめているものを対処することができ得るのか、やっぱり無理なのか。","respondent":"中村建築課長","answer":"ただ、これは今現在道路がないところに新たに道路をつくるときに、これを指定するというものでございまして、既存の道路そのものには指定をすることはできませんので、位置指定道路そのものに基づく指導というのはなかなか難しいのかと思います。","voiceIndex":111,"id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"これは、相手に命令を下すことなく、行政側の判断で、そういったごみ等を撤去することができるということだそうなんですけれども、これはものの本をちょっと読んだときに書いてあったんですけれども、条例というものに根拠があればこういったことも可能であるというようなことも書いてあるんですけれども、この辺につきまして区としてのご見解を最後にちょっとお伺いしたいと思います。","respondent":"中村建築課長","answer":"この条例化ですけれども、私道、個人の所有地というところもございまして、そこで、また先ほど申し上げましたが、ごみが本人とっては財産であるというような、そういった法律上の問題もあろうかと思いますけれども、その辺は、条例の制定につきましては。","voiceIndex":113,"id":"exchange-046"},{"speaker":"高橋委員","kind":"意見","question":"１５４ページ、駅周辺等放置自転車対策事業、１５９ページ、都市計画費、これは次のページになりますが、やさしいまちづくり推進費について、それから、１６０ページの公園管理費についてお尋ねします。ページでいうと１６０ページに移ってしまうんですが、やさしいまちづくり推進費関連です。おたがいさま運動等の推進費、３９０万円余がありますが、この決算額の内容をお教えください。","respondent":"永尾高齢者福祉課長","answer":"やさしいまちづくり推進費ですけれども、おたがいさま運動を進めるための選定委員会等を行いまして、またシンポジウムを行った、そういう経費です。","voiceIndex":116,"id":"exchange-047"},{"speaker":"高橋委員","kind":"質問","question":"まちづくりのソフトの部分とハードの部分で、所管のほうが高齢者福祉課と都市計画課という形になったということですが、今お話あったシンポジウムが、じゃあ、どのような形で成果が生かされたのかということと、今、高齢者福祉課と都市計画課が連携していくというお話があったんですが、具体的な連携の場というのはどのようなところになっているんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"標語の策定につきましては、平成２４年の７月から８月にかけて応募いたしまして、小学生や中学生、高校生、また一般の方に対しても啓発も兼ねた意味での標語の募集を行いました。","voiceIndex":120,"id":"exchange-048"},{"speaker":"高橋委員","kind":"意見","question":"その競技周辺と、それから、そこへのアクセスを含めて、面的な整備、こちらを行っていく必要があると思うんですが、今ありましたやさしいまちづくり推進のそういった観点から、どのような区のお考えがあるか、お聞かせください。","respondent":"藤田都市計画課長","answer":"平成２５年、平成２６年につきましては、重点整備地区として大井町周辺バリアフリー基本構想、こういったものを策定していく考えです。こうした中にも、オリンピック・パラリンピックの開催についての視点も入れて検討していきたいと考えています。","voiceIndex":122,"id":"exchange-049"},{"speaker":"高橋委員","kind":"質問・要望","question":"国や都、各団体との連絡調整、そして今お話あった大井町駅周辺バリアフリー計画策定の中で、ぜひとも今お話にあった形で計画を作成していっていただきたいと思います。しかし、大田区、品川区の方々が使用して、放置、そして撤去が随分あると思うんですが、平成２４年度で撤去がどれぐらいだったのかと。その平成２４年の状況を受けてどのように対応をされていく状況なのかということも確認させてください。","respondent":"谷口交通安全担当課長","answer":"区内でも放置自転車の多い大井町と同じような位置づけで今取り組んでいるところでございまして、新しく自転車場の整備を含めて、また、警備員、指導員等の今検討を進めているところです。","voiceIndex":124,"id":"exchange-050"},{"speaker":"高橋委員","kind":"意見","question":"ぜひ利用者も多く、駐輪場も常に満車の状態ですので、ぜひお願いいたします。そして、１６０ページ、公園管理費ですけれども、鮫洲運動公園の少年野球場の件なんですが、今年は本当に暑くて、熱中症、あるいは熱中症寸前の利用者の方がたくさんいました。こちらのベンチには、勝島の少年野球場のように屋根がついていないですね。","respondent":"多並公園課長","answer":"その関係で、固定するような屋根は設置できないというところで、現在のところはそのように運用しています。","voiceIndex":126,"id":"exchange-051"},{"speaker":"高橋委員","kind":"意見","question":"このような今年のような猛暑で健康について害があると困りますので、ぜひ前向きに検討していただいて、よろしくお願いしたいと思います。以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"１５９ページ、治水対策、それから１６０ページの公園管理費、１６２ページの都市開発費からそれぞれお伺いをしたいと思います。これは鳴る基準というのは当然川の場所場所で決まっているわけですけれども、これはどうなんでしょう、制度上、貯留設備の整備の進捗に合わせて基準を変えることってできないんでしょうかね。それから、また近年の利用状況などを把握していれば教えていただきたいと思います。","respondent":"稲田道路課長、多並公園課長","answer":"１０分単位でも急激に上がってくるです。近年の雨の降り方も、大きく急激に降ってくるという状況ですので、現在のところは、今まで使ってきたこの値でやっていきたい、吹鳴もやっていきたいと考えております。区内の公園の中にシャワーがある施設の公園です。区内には６カ所に設置しています。天王洲、八潮北、品川中央、南ふ頭、東品川、しながわ区民公園という、有料運動施設がある公園について設置しています。","voiceIndex":131,"id":"exchange-053"},{"speaker":"あべ委員","kind":"質問・要望","question":"次のご答弁で、把握している限りで構いませんので、傾向などを教えていただければと思います。品川区におきましても、ランナーの方々が使いやすいようなシャワー施設、できればコインロッカーなどもあわせて整備することによって、区内の方々のランニングのしやすさ、そして、区外からも来ていただく、そういったことがより魅力ある品川をつくるために有効なのではないかと思うのですが、いかがでしょうか。","respondent":"多並公園課長","answer":"区民公園でもランナーの方が増えてきているところもありますので、ランナー向けのサービスをその中でできないかというのをちょうど今検討している最中です。","voiceIndex":134,"id":"exchange-054"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ積極的な検討をしていただきたいと思います。次に移ります。それから、事後精算をするもの、しないものの違いというのを教えていただきたいなと思って質問しております。これが１点。それから、北品川五丁目の再開発の中で、一般質問でも伺いましたけれども、地域交流施設、そろそろ設計も必要な時期になってきているかなと思うんですけれども、進捗を教えてください。","respondent":"溝口都市開発課長","answer":"委員ご指摘の部分も踏まえまして、今後どのような材質を使っていって、将来的に持続的にきれいなまちづくりが図れるかというのを検討していきたいと考えています。","voiceIndex":136,"id":"exchange-055"},{"speaker":"あべ委員","kind":"提案","question":"かつ、この業務は多分毎年委託先が一緒だと思うんですよね。今のお答えで、精査はされているということでしたので、今後もそこはきちんとやっていただきたいと思います。現段階でもまだ提案事業で、提案を待っているということなんですけれども、ぜひこれ、内容的にも地域交流施設という名前に恥じないだけのものをつくっていくという気持ちを、ぜひ区としても共有していただきたいと思います。","respondent":"溝口都市開発課長","answer":"地域交流施設につきましては、やはり都市計画提案で定まったものです。そういった中で、いかに地域の方々が集まれる、また集える、そういった施設になるようにこれからも組合側には指導していきたいと思いますし、区も一緒に考えていきたいと考えています。","voiceIndex":138,"id":"exchange-056"},{"speaker":"こんの委員","kind":"質問・要望","question":"本年３月の予算特別委員会におきまして我が会派のあくつ委員より、東品川公園の整備については、地域の方々のさまざまなご要望があるので、ぜひその声を取り入れていただきたいという、こういう要望をさせていただきました。そこで、この地元の方やお子さんのご要望を合わせた総合的な整備の内容ということは、今回の城南第二小の子どもたちのワークショップがそれに当たるというものなのでしょうか。","respondent":"安井土木管理課長、稲田道路課長、多並公園課長","answer":"その許可をおろしましてから、工事の着手、それで一旦仮復旧というような形で工事を行って、復旧の工事を行います。その３年先の状況を各企業者等にお知らせし、掘削調整会議というのを行いまして、効率的な道路改修工事をやっているです。東品川公園のお尋ねです。東品川公園は、子どもたちのアイデアを生かした公園の第３号公園となる公園です。","voiceIndex":141,"id":"exchange-057"},{"speaker":"こんの委員","kind":"質問","question":"そこで、午前中の他の委員からも挙がっておりましたけれども、自転車事故、減少はしているものの、依然としてやっぱり問題となっている自転車の安全対策、マナー、交通ルール、こうしたことが、区民の方がしっかり学ぶ場として講習会などが開催ができるような交通安全を学ぶ基幹公園と、こういう公園の整備をお願いしたいと思いますが、いかがでしょうか。","respondent":"安井土木管理課長、多並公園課長","answer":"現在仮復旧をしているところなんですけれども、あちらの場合は、なかなか車等が通らないところですので、比較的状態のほうの今のままですとそれほどなじむということはないかと思いますので。そのようなところで聞きながら、整備の段につきましても、連携を図りながら今ちょうど進めているところです。","voiceIndex":145,"id":"exchange-058"},{"speaker":"こんの委員","kind":"質問","question":"公園のほうは、そのようにお聞きいたしまして、大変うれしく思います。よろしくお願いします。通常は自転車の貸し出しが夏休み等に行われているということですけれども、こちらのほうもお願いしたいと思います。これは景観上あまりどうなのかなと思いますので、同じ素材でやはり復旧されるということがいいかなと思うんですけれども、いかがでしょうかというところですが、意見として終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-059"},{"speaker":"渡部委員","kind":"質問","question":"三つぐらい伺っていくんですが、まず公園のことなんですけれども、先日地上波で見て、品川区って借地公園というのはあるんですか、ないんですか。","respondent":"多並公園課長","answer":"公園、児童遊園という中には借地で借りているところあります、幾つかですね。神社のところを借りたりとか、あと、公共施設で申しますと、下水道、まあ、東京都が持っているところの上を借りて整備している、いろいろなさまざまなパターンの公園があります。","voiceIndex":150,"id":"exchange-060"},{"speaker":"渡部委員","kind":"質問","question":"ちょっとその辺の考え方、伺わせてください。","respondent":"多並公園課長","answer":"そのために、お借りしている公園については、あまり過度なものを設置しないだとか、そういうところの工夫が、改修等するときにでも考えながら整備してお返しできるような形、そんなような形で今も考えているところです。","voiceIndex":152,"id":"exchange-061"},{"speaker":"渡部委員","kind":"質問","question":"その場合どのようなやりとり等があったのかというのを教えていただいてよろしいでしょうか。","respondent":"多並公園課長","answer":"ちょっと特殊な例かもしれませんけれども、青空野球場という野球場がありまして、あれが東京都の港湾局の関係で事業で必要だということでお返ししたと。そのときにそういう事例が私の覚えているところではございました。","voiceIndex":154,"id":"exchange-062"},{"speaker":"渡部委員","kind":"意見","question":"民間の方との、青空はさんざんこういう場でも何年か前にやっていたのであれなんですけれども、例えば、じゃあ、何年も親しまれたところで、ほかに品川区内で、まあ、品川区内、広さからいうと、ちょっと歩けば公園があると言えばそのとおりなんですが、やはり地域に親しまれたところがなくなるよというときに、代替地を用意するなり、もしくは地権者の方からご相談をされて。","respondent":"松代防災まちづくり事業部長","answer":"現在では、そういったことも経験則も踏まえながら、長期間でできる限りお借りできるものというものをこちらも考えておりますけれども、いかんせん、それを１０年、２０年しっかりと担保するものはなかなかできないというのが現状です。","voiceIndex":156,"id":"exchange-063"},{"speaker":"渡部委員","kind":"質問・要望","question":"次の質問に移ります。１５５ページの整備工事にスクールゾーンカラー標示というところがあるので、スクールゾーンのことについてお伺いするんですが、昨年の文教委員会の中で、やはり品川区、第１、第３土曜日が始まったと。きょう、土木費の中で、いわゆる道路を管理する立場から、また、いわゆる交通安全の立場から、第１、第３土曜日のスクールゾーン化ですね。","respondent":"谷口交通安全担当課長","answer":"ただ、補助標識で第１、第３とか、そういう標識が、補助標識がつけられた場合、運転者にとっては大変わかりづらい状況になります。都内全域が第１、第３というふうになれば、また全体的に考える必要もあろうかと思うんですけれども、現在のままで行くものと考えているところです。","voiceIndex":158,"id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"そこだって、８月除くになっているわけではないですし、例えば長期休暇を除くというふうになっているわけではないじゃないですか。ただ、だから、品川区内は、第１、第３土曜日は、じゃあ、学校あるけれども、やはり都内全域を考えたら、第１、第３の土曜日というのは、そういう意味でスクールゾーンという仕組みがあるけれども、その中では守れないという、もう守れないで終わりになっちゃうんでしょうか。","respondent":"谷口交通安全担当課長","answer":"ただ、なかなか今の現状では難しいということをご理解いただければと思います。","voiceIndex":160,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"難しいんですね。やはりこれ、昨年の文教委員会でも質問したきっかけというのは、これ、地域の方からの問い合わせです。ふだん地域の方々が旗持ってさまざまな活動をしていただいている中で、うまというんですか、また名前忘れちゃいましたけれども、出していただいている。それは本末転倒の話だと思います。だって品川区、第１、第３土曜日学校あるんですもの、結局。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"ゼネコンは大喜びですけれども、国民、そして区民にとってどうかを問いたいと思います。質問です。品川区は歓迎はしていますけれども、なぜ今、リニア新幹線なのか、魅力やメリットがあるのかどうか、この点をお伺いします。そして、２点目は、品川区内どこを通るのか、非常口１カ所、どこなのか、品川区への影響と自治体としての区民への責任をどのように捉えているのか、お伺いいたします。","respondent":"藤田都市計画課長","answer":"ルートですけれども、地上になかなか出てこないので説明がしにくいんですけれども、先ほど非常口というお話がありましたけれども、北品川のほうの第一三共のあるあたりに非常口が１カ所できるという形になっているものです。","voiceIndex":164,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"区民にとってどのように歓迎されるものになっているのか、お伺いしたいと思います。もう１点なんですけれども、路線地図を見た人が、自分の家の近く、地下４０メートルを通るということを知って、びっくりしました、大きな地図を見て初めてわかりました、勝手に通らないでほしい、こう言っていますが、区民生活を考えれば、品川区にも説明をしていく責任があると思うんですね。","respondent":"野呂瀬環境課長、藤田都市計画課長","answer":"それで、ついでながらそのときに出たことは、大深度地下のところ、４０メートルのところを通りますので、設計図でいうとご自分の家の真下を通るような形になっているんですけれども、その辺の質問に対してＪＲ東海が答えていたのは。環境課長が今申したのが、アセスの関係の説明会だと思います。最近では平成２５年７月３０日に町田市のほうで説明会をやってあります。","voiceIndex":166,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、ぜひぜひ広く周知をして意見を聞いてほしいと思います。１点目、輸送の需要、そして時間短縮など、国民の要望がないといった点。２点目、運転手が乗車せず、安全確認への大きな不安と、大きな不安を置き去りにする建設であるといった点。５点目、よく聞いてください。計画の撤回を求めます。そして、都営住宅の改修、改築、進めていただくことを求めますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"あくまでも将来の品川駅に近接する地域のまちづくりをどのようにしていくのか、そういったものを示す方向のものでありますので、そのビジョンができたからといってすぐ都営住宅を動かすとか、動かさない、そういったものの計画ではありませんので、ご理解いただきたいと思います。","voiceIndex":169,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ地域の皆さんの声を受けとめたまちづくり、この南地域でもまちづくりを進めていただきたい、このことを重ねてお願いして次に参ります。放射２号線です。５日と６日の日に東京都から用地測量説明会のお知らせが郵送をされてきました。なぜこのように切りかえたのか、説明会を変えた理由をお伺いしたいのが１点です。もう１点は、個別説明会の内容についても教えてください。３点です。","respondent":"藤田都市計画課長","answer":"今回、郵送で、速報の数値として今私どもいただいている数としては、２００ということで数を聞いてあります。それから、個別の説明の中身ですけれども、基本的には用地測量を行いますという説明になるんだと考えています。","voiceIndex":171,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明会の内容ですが、用地測量を行う、その測量の仕方だけなんでしょうか。改めてそこをお伺いいたします。２００名の方に郵送されたということなんですけれども、大家のところには届いたけれども、借地権者の方に届いていないという声もいただいています。その辺をもうちょっとお聞かせをいただきたいと思います。ぜひ個別説明会をやめて、全体説明会に戻すべきであると思いますが、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"説明会の中ですけれども、もちろん用地測量の説明だけでなく、質疑が当然あるわけですから、その中で用地の補償についてもお話し合いをしていくようなことになるのかなと考えています。それから、借地権者にという部分ですけれども、まだまだ東京都のほうも調べ切れていません。","voiceIndex":173,"id":"exchange-071"},{"speaker":"山元委員","kind":"質問・要望","question":"この１２件の内訳、また内容、そしてどういう地域の方々が利用されたのか、教えていただきたいということと、また、この１２件に携わった業者登録というんですかね、されている方はどのぐらい、何人いらっしゃるのか、教えていただきたいと同時に、また、今回１２件、業者登録した方たちが携わったのかどうかも教えていただきたいと思います。","respondent":"品川木密整備担当課長","answer":"実績としましては、まだちょっと業者登録が遅かったのかもしれませんが、今までやっていた業者１社と、それから新たに８件登録していただいた業者の１社のみ、品川シェルターのほう対応していただきました。合計で結局２社の対応というふうになっております。","voiceIndex":176,"id":"exchange-072"},{"speaker":"山元委員","kind":"質問","question":"それで、実際このシェルター、逆にこの地域というか、いろいろ危険な地域って区内にはあると思うんですが、この地域というか、このシェルターを設置したほうがいいケースという言い方は変なんですが、ここはやったほうがいいなというような、品川区内にそういうケース、何件ぐらいあるんでしょうか。やっている、やっていないに関係なくですけど。","respondent":"品川木密整備担当課長","answer":"これがまず大前提です。ただ、どうしても予算の関係上できないという方もいらっしゃいますので、そういう方については、シェルターのほうで対応していただくというような形になります。","voiceIndex":178,"id":"exchange-073"},{"speaker":"山元委員","kind":"質問・要望","question":"そしてまた前回、実際例えば品川シェルターに関しては、私どもにまたお問い合わせあったんですけれども、ちょっとごつごつしているというイメージがあって、デザイン的にも考えていきたいという、そのようなご答弁があったかと思いますが、その後、デザインというんですかね、つくりというんですかね、どういうふうに変わったのか、それとも変わっていないのか、その辺も教えていただきたいと思います。","respondent":"品川木密整備担当課長","answer":"デザインのほうですが、私は過去に答弁で検討しますというような形も言ったかと思うんですが、なかなかどうやっていいのかというところも考えるところでございまして、現状として、あまりデザインの変更のほうが進んでいないというのが現状です。","voiceIndex":180,"id":"exchange-074"},{"speaker":"山元委員","kind":"質問・要望","question":"何せいつ起こるかわからない地震です。では、１６０ページの勝島の海レンタルボート運営委託についてお伺いしたいと思います。今回この事務事業評価ではＣの見直しで、７月、８月、土日祝日に実施と書いてありましたけれども、実際これ、何日ボート遊びができたのでしょうか。そして、前回、ボート運営に当たり、池に負荷があるとおっしゃっていましたが、その内容も教えていただきたいと思います。","respondent":"多並公園課長","answer":"平成２４年度の実績といたしましては、２２日間、土日祝日の運営ということで行いました。利用実績といたしましては、９０５組、２,４１８名の方のご利用です。","voiceIndex":182,"id":"exchange-075"},{"speaker":"山元委員","kind":"質問・要望","question":"今後見直しと言われていますけれども、ぜひとも水辺に触れることのできるボート遊びをできれば継続していただきたいと、そう思っています。ご意見いただきたいと思いますが、ディズニーランドのスモールワールドまでにはいかないにしても、あそこのボート遊びをしたいなという、そんな工夫をしていただきたいと思いますが、一言ご意見をいただきたいと思います。","respondent":"多並公園課長","answer":"利用者の区民の方が１割という実態も踏まえながら、今後は慎重な検討ということで進めていきたいと思ってあります。","voiceIndex":184,"id":"exchange-076"},{"speaker":"原委員","kind":"質問・要望","question":"何かどうも風の便りですと、担当の課長は学生時代医学畑というような話も伺っているものですから、意外と医学と建築ですね、これ、１０名ぐらい１級建築士がいらっしゃるということ、私は似て非なるというのではなくて、逆に意外と医学と建築というのは共通点があるのかなという感覚があるんですね、これが実に。後半ちょっと全般的な防災のことについて伺いたいと思います。各、よろしくお願いをいたします。","respondent":"安井土木管理課長、谷口交通安全担当課長、溝口都市開発課長、中村建築課長","answer":"私のほうからは屋外広告物の取り締まりについてご説明いたします。この関係で若干撤去活動を強化をした、指導啓発を強化したということがございまして、平成２４年度は１,２７８台。失礼いたしました。公有地管理事務について私のほうから追加でご説明します。さて、あと、違反建築の取り締まりですけれども、こちらは、現状では年間大体５００件近く、昨年。","voiceIndex":187,"id":"exchange-077"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっとこれはいろいろな考え方があろうかと思いますけれども、建築行政の、そうすると、何でそれを伺ったかというと、建築の実際の行政自体をトータルに考えていただいたときに、こういったことも必ず関連をしていると、今ご説明が非常によくわかったんですけれども、そういったことがあるものですから、トータル的な行政、建築行政としての考え方をもう一度お話をいただきたいということと、それから。","respondent":"中村建築課長、鈴木防災課長","answer":"建築行政の考え方ですけれども、まず建物は人を守るためのものであり、また地域社会の中で、多数の中での一つという考え方から、ルールを守って建てていただかなければいけないということがあります。区といたしましては、そのどちらの対策につきましても、区民の方の命、財産を守るために必要なものですので、さまざまな視点、さまざまな手法による防災対策、減災対策を組み合わせまして。","voiceIndex":193,"id":"exchange-078"},{"speaker":"原委員","kind":"質問","question":"ですから、平成２４年度決算の今委員会ですので、そういったところから、この報告自体がどういうような形でこの品川区に活用されているのかということですとか、それから、実際の問題としては、この報告書の中で、ホームページ全体読めばいいんですけれども、すごい膨大な量ですので、それの中で、当然にいろいろなこと、各先進国の関係もありますでしょうから。","respondent":"鈴木防災課長","answer":"標準化の部分についてですが、こちらはこの報告書の中の情報システム設計ガイドラインの中で、国際標準化ということで、地図情報、地理情報等についての標準化を図ることで、それぞれ自治体や関係機関が連携できるような仕組みを構築するという一つの考え方ですので。","voiceIndex":196,"id":"exchange-079"},{"speaker":"原委員","kind":"意見","question":"そうしましたらば、実際にこれ、このプロジェクトの最終結果報告というのは、東大の地震研と独立行政法人防災科学技術研究所、京大の防災研究所等によっていろいろ出されていると思いますけれども、その中で最終的にアウトカムについてお聞かせをいただければと思いますので、どんな形でも結構なので、まずそれについてどういうふうにお考えかを。","respondent":"鈴木防災課長","answer":"主なものを挙げますと、病院スタッフのための地震対策であるとか、それから、被災者の生活再建のための基本システムの開発、それから、それを地方自治体へ導入する支援というようなところで、できるだけ自治体での取り組みが進められて。","voiceIndex":198,"id":"exchange-080"},{"speaker":"原委員","kind":"意見","question":"再度もう１点。品川区に生かしていくという、これは本当に区民にとって非常に大事なことですので。そういう状況下にありますので、このアウトカムにもあるように、地方自治体への導入と、ここのところについてもう１回お考えをいただければと思いますので、よろしくお願いをいたします。","respondent":"鈴木防災課長","answer":"アウトカムの中で自治体への導入支援が明確にうたわれているのは、先ほど申し上げました支援者生活再建システムの再建のための基本システムの開発の部分ですが、それ以外にも先ほど申し上げましたように具体的な例示がされておりますので。","voiceIndex":200,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"私からは１６１ページの平塚公園、これは自転車に関してです。次に１６２ページの都市再生総合整備事業、１６３ページの密集住宅市街地整備促進事業についてお聞きします。あそこは有料になっているんですよね。そのためなんでしょうか、公園にたくさん自転車が放置されています。これはやはり有料だから無理なのかなという部分もあるんですけれども、ここの対処がどうしたらいいのかなというところです。","respondent":"安藤文化スポーツ振興課長、溝口都市開発課長、品川木密整備担当課長","answer":"私からはスクエア荏原の駐輪場についてお答えを申し上げます。整理をしまして、駐輪場と駐車場と一体的に文化スポーツ振興課が所管となります。そういった中で、少人数でありますが、いろいろ本来であればまちづくり全体のコーディネートですとか。目的に関しましては、防災まちづくり、どういうふうにつくっていったらいいかというようなことを目的に、最終的なところとしては、地区計画等。","voiceIndex":203,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"平塚公園です。どうも建設的ではない。しかしながら、どうもかみ合わないんですよね。そうすると、今まさに補助２９号線、２８号線、放射２号線、やっておりますけれども、もっと建設的な意見、それから、実際に防災をするという意味でのハード的な整備をどうしたらいいかという地域の住民たちの啓発になるのではないかと思いますが、何か適用ができないかなという、その件に対するご見解をお聞きいたします。","respondent":"安藤文化スポーツ振興課長、溝口都市開発課長、品川木密整備担当課長","answer":"電子マネーについては利用ができません。委員ご指摘のように、再開発事業を進めていく上にはさまざまな専門的なコンサルタント、または民間事業者と、そういったものを誘導していくことによって。まさに委員おっしゃるとおりで、今後不燃化特区を進めていく中で、まちづくり協議会等。","voiceIndex":207,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"専門的な知識の育成を非常にやっておりますよということなんですが、これも本当に進めていただきたいと思うと同時に、行政側の強みってあると思います。それから、今進めている補助２９号線、２８号線、放射２号線、これはやはり住民と一緒にまちづくりをつくっていくんだということでいい仕組みをつくっていただきたいと希望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-084"},{"speaker":"渡辺委員","kind":"質問","question":"成果報告書１６１ページ、しながわ区民公園北側ゾーンの関係、１５４ページ、土木総務費全般と１５９ページ、水辺空間の整備促進で伺います。初めにしながわ区民公園ですが、この年度でまず北側ゾーンの整備調査費ということで一つが完了し、そしてまた今年度に引き続き中央ゾーンという流れがあるかと思います。その中で主な変更点等ありましたらお知らせください。","respondent":"多並公園課長","answer":"大きな点で、地域防災計画という点で踏まえまして、大きなところとしましては、そのちょうど検討しているときと地域防災計画が同時並行で進んでいったところと、あと、都や国などから新たないろいろな制度が出てきたということも踏まえながら。","voiceIndex":213,"id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問・要望","question":"前にも伺ったんですが、当然広大なところを三つのブロックに分けられている中で、関連性、あるいは全体のビジョン、これは本当に何十年ぶりかの大規模な改修という中で、全体のビジョンだとかデザインのところはどのように関連していくのか。私たちが聞いている区民要望でも、やはり稼働率の問題、あるいはテニスコートで言えば、芝等の消耗であったり、コートの数のご要望はよく耳にするところであります。","respondent":"多並公園課長","answer":"その点も踏まえまして、また、ただあと、事業費の平準化というのもありますので、そこら辺で中央ゾーンを行った後、どこで北側ゾーンを行うかというのを今後、実施時期も検討してまいりたいと考えているところです。","voiceIndex":215,"id":"exchange-086"},{"speaker":"渡辺委員","kind":"質問・要望","question":"先般の委員会でも話出ていましたように、例えばバッティングセンターのようなものも、野球場と隣接している中で、夜、やはりいい意味で時間が決まっている公園であるので、そういう地域的な治安といいますか、そういうようなものもある意味いい意味で管理できるので、人の出入りがあってもいい区切り目があるような形があるので、もうちょっと大きな発想、企画を取り合わせて、この区民公園。","respondent":"松代防災まちづくり事業部長","answer":"そういったものは、今もそれが続いておりますので、そういったものの公園をつくる際の条件面をしっかりと踏まえながら、今の公園のあり方というものを考えていきたいと、このように考えているところです。","voiceIndex":217,"id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"水辺空間、同じく今お話ありました。やはりこの周辺自体が大変チャンスがある水辺空間の整備促進ということで伺いたいと思います。船着場という点が１点。このあたりの船着場という視点で、現在の進捗状況を伺いたいのが１点。これは単に一つの施策じゃないと思っています。コーディネーターであったり、チャレンジするという点もあるかと思いますが、その点、水辺の整備促進の点からいかがでしょうか。","respondent":"奥田河川下水道課長","answer":"第１点目の船着場等の活用についてなんですけれども、例えば区のほうでも、東品川一丁目３番先の天王洲運河の水辺広場前に桟橋を建設いたしまして、本年４月から供用開始しています。","voiceIndex":219,"id":"exchange-088"},{"speaker":"若林委員","kind":"質問・要望","question":"平成２５年の３月から５月の間にいわゆる水辺広場でケータリング事業、モデル的な事業のスタートなんでしょうかね、ケータリング事業を行いましたので、どのような模様だったか、また、今後の展開の見通しなんかもお聞きしておきたいと思います。小学校の対応は対応として、民放で流れた目黒川氾濫というこの事実があったのかどうか、区の認識をお伺いしておきたいと思います。以上３点。","respondent":"奥田河川下水道課長","answer":"目黒川の利活用の状況ということで、実は委員からご指摘がございました利活用協議会についてなんですけれども、目黒川の河川空間において民間事業者と連携しながら水辺空間のにぎわいを創出して周辺地域の活性化を図るということを目的にいたしまして。","voiceIndex":224,"id":"exchange-089"},{"speaker":"若林委員","kind":"質問・要望","question":"見直すつもりはないということなんですが、今のダブルスタンダード、これは、じゃあ、防災行政無線で二つ流すということになっちゃいますよね。これは絶対緊急に見直す必要があると思いますので、重ねてご要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１６２ページの都市開発費についてお伺いをします。品川区では、大崎、大井町、目黒、品川、武蔵小山とか、区内で超高層の再開発が際限なく巨額の税金がつぎ込まれて進められておりますけれども、現在区内の超高層ビルが何棟になったのかをお聞かせいただきたいと思います。計画されているものも、決定されたものと、まだ決定はされていないけれども、計画中だというところもわかったら教えてください。","respondent":"溝口都市開発課長","answer":"それと、大井町、大井一丁目南地区という形で、大井町の駅のところについても、再開発事業の中で、１００メートルを超える建築物を計画しているものです。","voiceIndex":228,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、７８プラス３棟ということで、ここには西品川一丁目とかは入っているんでしょうか。そのことを一つ後でお願いします。例えばですけれども、百反坂の大崎西口中地区の再開発のところでは、地権者、借地権者、建物権利者、借家権者、それぞれ何人中何人がその地域から外に出たのか。その理由もあわせてお聞かせいただきたいと思います。","respondent":"溝口都市開発課長","answer":"権利返還というのは、それぞれ権利者、自分たちが持っている権利をどのように今後していくのか、そういった中で決まっていくものだと考えていますので、決して一方的に追い出したとか、そういったものではなく、権利者の意向を酌んで。","voiceIndex":230,"id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう状況の中で開発組合の設立をさせるための同意を求められて、判こを押さざるを得ないという、こういう状況になっているということが改めて地域の方々のお話を伺って思ったわけなんですけれども、私はこういう全く見通しがつかないままに組合設立の同意の判こを押す仕組みというのは問題であるし、この仕組みそのものを変えていくことが必要だと思うんですけれども、その点についてはいかがでしょうか。","respondent":"溝口都市開発課長","answer":"再開発事業の事業を実施するまでの流れですが、都市計画決定を踏まえて、その後、権利者の方たちが集まって組合を設立していく。組合設立後には、そういった中で基準等、また組合の中で決めていく中で、どのような形で権利返還をしていくのか決めていく。","voiceIndex":232,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"しかし、そこに住み続けるという選択肢は、組合が設立されて、事業が認可をされていけば、もう許されないわけじゃないですか。私はこれは変えることができるんじゃないかと思うんですよね。そこら辺のところの開発の権利返還のやり方と、それから、その仕組みを判こを押す前に示すという、そういう方向ができると思うんですけれども、その点についてはいかがでしょうか。","respondent":"溝口都市開発課長","answer":"再開発事業につきましては、これまでも同じようなやり方をしてきて進めておりますので、従前どおり淡々と再開発事業を進めていきたいと考えております。","voiceIndex":234,"id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういう中で、マンションに入ったけれども、実際は管理費が高くて、本当にこんなはずじゃなかったと。それから、外に出た方も、こんなはずじゃなかったと。そういうふうな状況というのもあるわけです。私はそういう中で、やっぱりきちんと見通しを持った中で進めていくと、そういう仕組みにこそ変えるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":236,"id":"exchange-095"},{"speaker":"井上委員","kind":"提案","question":"私からは１６０ページのやさしいまちづくり推進費と１５５ページの道路維持費、１６５ページ、住宅費についてお伺いをしたいと思います。音声信号機のある横断歩道にエスコートゾーンの設置が品川区では進んでおりません。議事録を確認する限り、２００７年から何度となく提案がされています。やはりこういった計画がないと進まないのでしょうか。品川区で進まない理由をお伺いいたします。","respondent":"藤田都市計画課長","answer":"品川区の中にはまだその重点整備地区としている地域がございません。現在大井町駅周辺について、今年度、来年度でその計画を立て、その中で整備を進めていきたいと考えているところです。","voiceIndex":241,"id":"exchange-096"},{"speaker":"井上委員","kind":"質問・要望","question":"大井町駅周辺にそういった形ででき上がってくるんだろうということで期待をさせていただきたいと思うんですけれども、エスコートゾーンは音響信号のある横断歩道に付設するのが望ましいということですが、区内には音響信号が何カ所ありますでしょうか。","respondent":"谷口交通安全担当課長","answer":"区内信号３５０カ所ございまして、そのうちの４９カ所が音響式信号になっております。","voiceIndex":243,"id":"exchange-097"},{"speaker":"井上委員","kind":"質問","question":"そのうちの何カ所が日中常時稼働している信号になるのでしょうか。","respondent":"谷口交通安全担当課長","answer":"常時稼働しているのが、昼間帯４カ所あります。押しボタン式が４５カ所という状況です。","voiceIndex":245,"id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"音響信号があっても音が鳴らないのであれば普通の信号と同じということで、今回交通安全担当課の協力で、どこの信号が音響信号、押しボタン式の音響信号なのかを調べていただき、視覚障害者の団体の方にお知らせをすることができました。簡単ではありませんけれども、こういった必要とする方たちへのピンポイントで知らせる工夫を求めますけれども、区のご見解をお願いいたします。","respondent":"谷口交通安全担当課長","answer":"区としましても、今お話し申し上げました４９カ所につきまして、徐々に広報をして、周知を図っていきたいと考えております。","voiceIndex":247,"id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひいろいろな工夫ができると思いますので、どうぞよろしくお願いをいたします。音響信号の音量の改善、あるいは、音を拡散させるのではなく、ビーム化するなど、当事者意見を聞いて改善することによって、日中稼働音響信号を増やすことができるのではないかと期待をするわけですが、ここでぜひ警視庁との調整を積極的に進めていただきたいと要望しますが、ご意見お願いいたします。","respondent":"谷口交通安全担当課長","answer":"当然視聴覚障害者の方に必要な部分ということで警視庁も考えておりまして、音響式信号の設置については積極的に進めているところですが、いろいろ所々問題がありますので、それを踏まえながら、警視庁のほうにも要望を伝えてまいりたいと思います。","voiceIndex":249,"id":"exchange-100"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひご協力をいただきたいと思います。次は、人感センサーつき街路灯、公園灯についてお伺いをいたします。２０１２年のプレス発表で、新規事業として、人感センサーつき街路灯、公園灯試験設置の事業がありました。プレス発表では３６０万円ほどの予算がついておりますけれども、決算額と事業の実績、そして検証の結果をお伺いいたします。","respondent":"稲田道路課長","answer":"照明灯明るさ検証なんですが、街路灯と公園灯がございまして、ここの部分では街路灯部分の決算額が載ったです。公園灯部分につきましては、公園維持管理のほうから出ておりまして、トータルしますと、トータルの発注契約額決定額が３９２万７,０００円です。","voiceIndex":251,"id":"exchange-101"},{"speaker":"井上委員","kind":"質問・要望","question":"なので、野外では多分難しいだろうなと考えています。なので、これは方向転換をしていただいて、公の施設でトイレなどの照明に人感センサーを取りつけたりしていただいたほうがいいのかなというふうに、事業としては着眼点は非常に評価をしますけれども、実際に時期尚早もあり、なおかつ今データがとれていないということなので、そちらのほうに力を入れていただきたいなと思うんですが、いかがでしょうか。","respondent":"稲田道路課長","answer":"節電という意味から、私ども着眼してやってきております。使用する場所、それから今後、機種の向上、価格の安定というところ等あります。今後もこの動向を注視しながら考えていきたいと思っています。","voiceIndex":255,"id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"決してむだになっていることではないと思いますので、よろしくお願いをしたいと思います。ちなみに、公の施設でのトイレの人感センサーつきの対応が今どのようになっているのか、そういった対応をこれから進めていこうという計画などをお持ちなのか、お伺いをしたいと思います。","respondent":"稲田道路課長","answer":"ちょっとトイレというところでは聞いてはないんですけれども、あと、１区、回答はなかったんですが、そのほか、すべて聞きましたら、街路灯関係、特になんですけれども、人感センサー等の考えはまず持っていないという状況でした。","voiceIndex":257,"id":"exchange-103"},{"speaker":"井上委員","kind":"質問","question":"続きまして、住宅費なんですけれども、住宅相談センターが２０１１年に八潮に開設されていますけれども、２０１２年度の決算がどこに入っているのか、ちょっとわからないので、金額とその使途をお伺いします。","respondent":"大串住宅担当課長","answer":"そちらにつきましては、住情報ネットワークサービス整備事業というものです。１６５ページ、今年度の成果報告書ですと１６５ページの上から１０行目に入っているものです。","voiceIndex":259,"id":"exchange-104"},{"speaker":"井上委員","kind":"意見","question":"以前に、２００８年に品川区に住情報センターの構想があったかと思うんですけれども、そのときに荏原地域の木造密集住宅のコーポラティブハウス化や住宅要確保援護者への住宅供給を行う仕組みなどをつくっていきたいというふうなことがあったかと思うんですけれども、今回の場合は、八潮住みかえ支援事業ということになっているので、多分八潮に特化した事業なのかなと思うんですが。","respondent":"大串住宅担当課長","answer":"こういった形で今現在は進めているといったところです。","voiceIndex":261,"id":"exchange-105"},{"speaker":"井上委員","kind":"意見","question":"事業者のほうにはパンフを支給したということなんだけれども、ほかに八潮に住んでいない方たちはなかなかエリア的にも難しいという部分があって、そういう意味では、なかなか活用ができないんじゃないかなと思うんですけれども、そういったところは、もっと広く展開をしていくのかというようなことでお願いします。","respondent":"大串住宅担当課長","answer":"失礼いたしました。オーナー向け、あるいは不動産屋向けに出したパンフレットは品川区全域で配布をしています。こちらのネットワークの相談センターが八潮にあるということで、八潮の方を中心に住み替え関係の相談には当たっているといったところです。","voiceIndex":263,"id":"exchange-106"},{"speaker":"浅野委員","kind":"質問","question":"最初に街路灯の件ですけれども、大震災発生が夜間の場合、大停電が起こる危険性があるということで、この対策を始めた自治体もあるようでありまして、町田市では「消えないまちだ君」というＬＥＤの街路灯に柱の中にバッテリーユニットを組み込んで、８時間から２４時間点灯することができるというようなものを開発したようでありますし、また、徳島県のあるまちでは、ＬＥＤの防犯灯。","respondent":"稲田道路課長、多並公園課長","answer":"こういう街路灯につきましてはさまざまな機種、それから対応するものが出てきておりまして、情報をとりながら、また確実なものというところも突きとめながら、それともう一つ。それもサンシャインシティともよく話しながら、ＰＲをかけるという意味でＹｏｕＴｕｂｅを始めたところもあって、ここについても非常にＰＲ効果が高かったということで考えているところです。","voiceIndex":266,"id":"exchange-107"},{"speaker":"浅野委員","kind":"提案","question":"簡単に言いますと、ＳＮＳを使ったらどうかなというのが提案なんですけれども、Ｆａｃｅｂｏｏｋ、こちらのほうがやはり、交流サイトになりますけれども、引きつける部分があるのではないかなと思います。もし評価がよいのであれば、サンシャインシティですから、しながわ水族館用のアプリも、例えばライブ映像も含めて提供してはどうかと思いますが、いかがでしょうか。","respondent":"多並公園課長","answer":"これについても、今始めたところですので、今後検証を進めながら進めていきたいと。Ｆａｃｅｂｏｏｋにつきましても、委員のご提案ということで、今後サンシャインとよく検討してまいりたいと思います。最後に、スマホ用のアプリです。","voiceIndex":269,"id":"exchange-108"},{"speaker":"浅野委員","kind":"質問・要望","question":"これは同居か、近居か、その場合にポイントというんでしょうかね、出るということですけれども、同居に至った件数というんでしょうか、これが何件ぐらいその中であったかなということを教えていただきたいのと、核家族化が随分進んできて、３世代の同居は少なくなったとは思いますけれども、さまざま、介護とか保育の観点からすると、３世代あったほうがいいなという方もおられるかと思います。","respondent":"大串住宅担当課長","answer":"親元近居についてのご質問です。昨年３５件、親元同居、近居ということで支援を行いました。そのうち、同居が１４件、近居が２１件、こういった内訳になっております。二つ目のご質問です。","voiceIndex":271,"id":"exchange-109"},{"speaker":"浅野委員","kind":"意見","question":"私の家も３世代同居でありまして、いつもごちゃごちゃしているんですけれども、今後３世代同居というのは私もぜひとも推進をしていってもらいたいなと思います。３世代だから、じゃあ、ポイントをさらにつけるかというようなことも考えてはいきたいなと思うんですけれども、これは区のほうの今後の検討にお任せしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":273,"id":"exchange-110"},{"speaker":"須藤委員","kind":"質問","question":"成果報告書の１５７ページ、立会川雨水放流管建設関連整備、これはどういう内容で、どの部分、場所で、どんな効果があるのか、教えてください。","respondent":"奥田河川下水道課長","answer":"シールドマシーンの工事と、あとそういった取水なんかも含めまして、おおむね平成３０年度ぐらいまでの予定をしておりまして、東京都が優先的に進める事業というふうに聞いてあります。","voiceIndex":275,"id":"exchange-111"},{"speaker":"須藤委員","kind":"質問","question":"第二立会川幹線と関連していると考えて、また別だよと考えるんですか。","respondent":"奥田河川下水道課長","answer":"あわせて立会川の雨水放流管、こちらの事業もやっておりまして、こちらの二つが東京都のほうで浸水対策に大きく寄与する事業となっています。","voiceIndex":277,"id":"exchange-112"},{"speaker":"須藤委員","kind":"質問","question":"私も集めてみました。その中で品川区が一番４.５ｋｍと長い距離ですよという話がありました。それで我々も、ぜひ品川に活性化をするようにというので、今言ったまちづくりのあれをつくってきたというような経緯があるわけで、そうすると、今ずっと話が来ているときに、そういう関連が、話が出てくるときには、品川区はどういうふうに絡んでいるのかというのをお聞きしたいので、お答え願いたいと思います。","respondent":"藤田都市計画課長","answer":"区のほうとのかかわりですけれども、特に品川駅が発着になるのではないかというような話がございましたので、そういう面ではそちらのいろんなにぎわいをぜひ品川区のほうにも持ってこれないかということで、品川駅の南地域。","voiceIndex":279,"id":"exchange-113"},{"speaker":"須藤委員","kind":"質問","question":"品川区が今話したように、一番長くて、４.６ｋｍという、品川を出て、北品川を通って、広町の下を通って、西品川を通って、豊町を通って、それから戸越を通って、東中延、それから旗の台というふうなずっと経路を通っていきますよということなので、そうすると、いろんな面で品川区が非常に大きく関与をしてくるだろうと思うので、このリニアの新幹線を、先ほどの発言は、賛成しないで。","respondent":"溝口都市開発課長","answer":"そういったものを生かしたまちづくりを進めていくことによって、リニアの効果が品川区内にも波及するようにまちづくりを進めていきたいと考えていますし。","voiceIndex":281,"id":"exchange-114"},{"speaker":"須藤委員","kind":"質問","question":"品川区は北品川四丁目に非常口をつくりますよ。びっくりしたのは、文化財に関してどうするんだというところまで、本当にしっかり調べてやってきているというので、さすがだなと思いながら読ませてもらったんだけれども、いずれにしても、それだけしっかりやってきているところなので、品川区としてもしっかりタッグを組むという感じをつくってもらいたいなと思うんですが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"そういった観点でＪＲ東海と事あるごとにまちづくりについては連携しながら進めていきたいと考えております。","voiceIndex":283,"id":"exchange-115"},{"speaker":"須藤委員","kind":"質問","question":"９月２８日の説明会は、品川区民じゃない、区外の方も来て、お話を聞いたり、質問されていたんですが、今度２０日に、先ほど反対をする人はみんなで行きましょうよみたいな話になってくると、その説明会自体が、行ったときにいろんな文書をくれたんです。いろんな環境があると思うんだけれども、そのあたりについてはいかがでしょうか。","respondent":"藤田都市計画課長","answer":"こうした国を挙げた施策ですので、そういった中で、しっかりと連携を図りながら、事業を進めるための説明会等についても協力をしていくべきと考えています。いずれにしても、連携しながら進めていくことが大切だと考えています。","voiceIndex":285,"id":"exchange-116"},{"speaker":"須藤委員","kind":"質問","question":"ぜひいい形で、これも、説明会、順繰りにしっかりやっていますＪＲの方々、また関連、調査をした方々、大勢が来て、しっかりと質問に対して丁寧に答えていますので、それだけ真摯な形をとっているなと思って感心して終わってきているんですけれども、これはそこまでにします。それから、１６３ページの荏原町の駅前地区の防災街区整備事業。","respondent":"品川木密整備担当課長","answer":"これから建物の除却に向けて、今現在準備をしている状況です。工事車両等、商店街等に入る場合がありますので、その辺は、十分商店街のほうと話し合いをしながら、配慮しながら進めていく予定でおります。","voiceIndex":287,"id":"exchange-117"},{"speaker":"須藤委員","kind":"質問","question":"いわゆる工事の進み方というのは、まあまあ、書いているよというような、そのあたりを簡単に教えてもらいたいのと、それから、かなり粉塵が上がってくるんだろうと思うので、そのあたりについても、商店街の中で飲食業をやっているお店も周りにいっぱいあるので、そういったことのご迷惑にならないようにとか、いろんな配慮が必要だろうと思うんだけれども、そのあたりについてはいかがでしょう。","respondent":"品川木密整備担当課長","answer":"現在組合のほうと建設会社のほうが、やっと契約のほうこれからしていこうというような状況ですので、ちょっと細かいところはまだまだこれからの話になっていきますので、そういった面は十分配慮しながら進めていきたいと考えております。","voiceIndex":289,"id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"１６５ページの区営・建設型区民住宅長寿命化計画策定費に関係して伺いたいと思います。決算額が８７７万５,０００円、かなり高額な費用がかかっていると私は印象を持ちました。それで、これ、耐震化、建替え等々、幾つかに分類されて、それぞれの建物が長寿命化計画されておりますけれども、改めてどういうふうに計画をつくられたのか、その内容について、棟数も含めて教えていただきたいと思います。","respondent":"大串住宅担当課長","answer":"残り４棟につきましては、こちらの国土交通省の指針で建替えが可能になるというところが出ておりますので、これを踏まえた上で、今後、築年数、耐用年数、それから、他の状況等々を勘案しながら、計画を考えていきたい、このように考えているところです。","voiceIndex":294,"id":"exchange-119"},{"speaker":"南委員","kind":"質問・要望","question":"今、課長の説明で、４棟の計画については国交省の指針を踏まえてということなんですけれども、１０年間の間で計画をつくっていくというふうにちょっと私は思っているんですけれども、とりわけせっかく建替えをされるわけですから、地域の住民の皆さんの要求も受けとめて計画をしていきたいということは５月の建設委員会で課長がご答弁されているので。","respondent":"大串住宅担当課長","answer":"その中で建替え等々の判定が出た住宅については、今後の活用策等々含めて検討していきたいと考えていますし、先ほど例に出させていただきました西中延区営住宅、こちらは、ご案内のように高齢者施設との合築ということで建替え、また、住宅そのもののバリアフリー化。","voiceIndex":296,"id":"exchange-120"},{"speaker":"南委員","kind":"確認","question":"それと、それぞれこれから建替えのところは、地域の要求を踏まえてというお話は先ほども繰り返したんですけれども、この住宅の戸数を増やすというここの点とあわせて、やっぱり今区民の、広く区民の切実な要求である例えば特養とか、例えば保育園とか、例えば障害者の通所、あるいは生活施設ですね、生活寮、そういうところの切実な要求をやっぱり受けとめていくべきだというふうに。","respondent":"大串住宅担当課長","answer":"まさに委員おっしゃるとおりでございまして、西中延の区営住宅につきましては、地域ニーズの高かった高齢者施設、これを合築して、西中延区営住宅単体の建替えというだけではなく、地域ニーズに対応した形での建替え、こういったものを実現しております。","voiceIndex":298,"id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"私は１５４ページ、道路橋梁費と１６４ページ、建築物耐震化支援費についてお伺いしたいと思います。道路のほうでお聞きしたいと思います。区内では道路上または歩道上に、本当に無数の電柱、それから車の信号機などの、多くの支柱や標識がたくさんあります。これらの耐久性、強度、期間もそうなんですが、どのくらいあるんでしょうか、まず教えてください。","respondent":"稲田道路課長","answer":"警察の標識では、警察のほうで管理していくというところで、その管理者ごとが把握しております。我々の区の標識におきましては、大型標識等、今年度も点検するんですけれども、点検をしながら、寿命等は考えているです。","voiceIndex":302,"id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"ご存じのとおり、今防災計画を見直して、首都直下型大地震が起きるという話ですよね。そうすると、実際これらの耐久性どれだけあるんだということを私は考えなきゃいけないんじゃないかと。首都直下地震で大地震が起きて、マグニチュード７から８クラスのでかい大地震が起きた場合に、安全なんですかと。区内には至るところにあります。その辺についてどのようにお考えなんでしょうか。","respondent":"稲田道路課長","answer":"この道路の施設、電柱、そういうのも含めまして、道路ストックというふうに今は言っているんですけれども、国交省のほうから通達が来ておりまして、各管理者は道路ストックの総点検という名目で来ているんですけれども、それを実施しなさいと。","voiceIndex":304,"id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"道路と道路に渡っている線もあるんですね。で、大きな標識、看板があります、何方面と。そうしたら、これ、本当に喫緊の話で、もし何か起きたら、いや、わかりません、いや、今動こうとしていますと言うんだったら、人々はどうすればいいか。家にとどまっているか、学校に避難していろということでしょうか。そうしたら、これがもしねじ曲がったりして倒れたらどうするんですか、落っこちたら。","respondent":"稲田道路課長","answer":"我々土木屋は、道路施設、土木施設、これらを、崩落事故がありましたけれども、非常に痛烈に感じておりまして、この国からの道路ストックの総点検、早急に実施するということで、全力を挙げて今取り組んでいるところでございまして。","voiceIndex":306,"id":"exchange-124"},{"speaker":"須貝委員","kind":"質問・要望","question":"今頑張っていらっしゃると。ただ、無数ですよね。本当に無数あるということで、果たしてどうなのか。防災課についても、こういうことをどう考えているのかというふうに、後でお答えいただきたいんですが、ここで、特定緊急輸送道路ってありますね。これについて、区内には幾つかあると思うんですが、ちょっとこれについて簡単に説明と、どのぐらい、どういうものがあるのか、教えてください。","respondent":"品川木密整備担当課長","answer":"道路としましては、主に第一京浜、第二京浜、中原街道とか、それから首都高速道路とか、主要な道路になります。こういった道路が、阪神の震災のときでもそうですが、倒れて、道路が閉塞しないように耐震化のほうを進めていくというような事業です。","voiceIndex":308,"id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"そういうことですよね。そうしたら、今診断は確かに今回も５５棟やって、少しずつやっていますよね、改善していますけれども、実際その前に、そういう大震災が起きたらどうしようもないということじゃないですか。そうすると、周りの建物、沿道の建物、今一生懸命費用をかけて、予算をつけて何とか変えようとしているのが、その前にやることがあるんじゃないかと思うんですが、それは違うんですか。","respondent":"品川木密整備担当課長","answer":"なかなか進まない事業ではありますが、こつこつと密集事業地区等で防災まちづくりというのは進めているような状況ではあります。","voiceIndex":310,"id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"それは確かにわかります。生活道路もそうですよね。それ、だって、地下１０メートル、２０メートル、基礎を下まで杭を打ってやっているわけじゃないですよね。拡幅が先なのか、人が通れるように、多くの人が助かるようにする道を確保するということが私は最優先な気がするんですが、これ、ちょっとお答え願いたいのと、防災のほうとしてどういうふうに考えられているのか、お２人にお聞きしたいと思います。","respondent":"品川木密整備担当課長、鈴木防災課長、安井土木管理課長","answer":"こういった活動をしながら防災対策のほうを進めているような状況ではあります。防災対策といいますのは、何か一つの事業、対策を講じることで防災すべてに対応できるものではございませんので、片方では建物の耐震化や不燃化を進めつつ。それなりの耐震性を有しておりますけれども、さらに電柱の強化を図るために交換巻き付け。","voiceIndex":312,"id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"折れていないと、今、電話線か、電話のほうがありますけれども、実際、じゃあ、折れていなくて垂れ下がったらどうなんですか。だけど、こっちのほうだったら、まあ、東電さんも今お金ないからどうかわからないけれども、実際人がまず逃げられるということを最優先に、大都市においてはそれを防災計画の主眼とするのが私は大切なことだと思うんですが、その辺についてご見解をお聞かせください。","respondent":"鈴木防災課長","answer":"ただし、先ほども申し上げましたように、防災の備え、対策は、何か一つですべて安全で、区民の方の命、財産が守れるという魔法のようなものはございませんので、避難路の確保もしっかりと重点的にやりながら、それに関する例えば耐震化、不燃化。","voiceIndex":316,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後、要望だけ言っておきます。できるだけ多くの人が救われるような、やっぱりそういう政策を私は考えていただきたいと思います。それだけは望んで、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":318,"id":"exchange-129"},{"speaker":"いながわ委員","kind":"質問","question":"１５４ページ、放置自転車について、１５６ページ、雨水流出抑制事業の透水性舗装について、同じく１５６ページ、これ、都市計画道路に関する関連ということでお伺いします。１５９ページ、河川について、１６４ページの建物除却工事助成についてお伺いします。最初入り口のところはそれにならってやれば多分建築ができると思うんですが、その後の検証というんですかね、をやられているのか。","respondent":"谷口交通安全担当課長、藤田都市計画課長","answer":"その場合、施設を新築する場合の自転車駐車場の設置ということで附置義務が定められておりまして、事細かに委員ご案内のとおり示されておりまして、例えば施設の用途としましては、百貨店、スーパーマーケット。こちらのほうの調査の関係ですが、基本的には事業が完了したときには報告をいただいておるというところで、その後の詳細な調査については行っておりませんが。","voiceIndex":320,"id":"exchange-130"},{"speaker":"いながわ委員","kind":"意見","question":"工事が完了して、その後終了検査というか、それを見に行くのは当たり前のことであって、その後、オーバーフローしてしまった場合の指導をされるのか。行政用語で指導と言うと、指導、助言、勧告とかいろいろありますけれども、そこまでいかなくても、これはオーバーですよというのを、何かそういうアクションを起こしているかどうかというのを私聞きたかったので、その分、短めにお願いします。","respondent":"谷口交通安全担当課長、藤田都市計画課長","answer":"今ご質問の個々の個別に対応しているところでございまして、終わってから、今委員ご指摘のように、現場調査を行っておりませんけれども、個々に陳情等が参りましたら、個別に対応しています。事業者のほうから、自転車足りないんだけど、何とかしたいんだけど、基本的に緑はこれだけ確保しなさい、駐車場はこれだけ確保しなさいという話の中で、なかなかすべてを満足するわけにいかないということで。","voiceIndex":323,"id":"exchange-131"},{"speaker":"いながわ委員","kind":"質問","question":"雨水に関してですが、透水性舗装というんですか、これが区内の歩道なのか、車道なのか、よく平米数で出しますけれども、km数でどれぐらいあるのかということ。恐らく機能回復というのは、目が詰まったのを何かできれいにする部分だと思うんですけれども、この周期というんですかね、どういった周期で掃除をしていくのか、教えてください。短めに。","respondent":"稲田道路課長","answer":"両側あれば、往復の距離数なんですけれども、５２kmです。この決算で出ています透水性舗装機能回復委託なんですが、これは年間３,０００平米を実施しております。ジェットで、水で目詰まりを回復していくというものです。","voiceIndex":326,"id":"exchange-132"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これ、右折レーンに車がとまっているとぎりぎりなんですよね。今後いろんなまちづくりを考えたときに、やっぱり安全性を考えて、これは完成してからのまたアクションになるかもしれないんですけれども、車両の通行区分というんですかね、車両の規制というんですかね、例えば路線バス、観光バスはオーケーですよみたいな、そういった規制も必要になってくるのではないかなと考えています。","respondent":"谷口交通安全担当課長、藤田都市計画課長","answer":"この中で、大型自動車の通行どめということで、住宅街であったり、商業地域等の地域、またその周辺で、各対象車両の交通事故、または騒音・振動等の交通公害を発生するおそれがある道路であったりだとか、あと。物流の基本的な考え方ですけれども、東京のこの辺については国道３５７号線、こちらの道路から各高速道路につないで、そこから基本的に地方に持っていくというのが基本になります。","voiceIndex":328,"id":"exchange-133"},{"speaker":"いながわ委員","kind":"質問・要望","question":"河川についてお伺いします。河川についてといっても、暗渠になっている立会川のことについてお伺いをいたします。幼いときの記憶だからちょっと違うかもしれないんですけれども、実際に立会川、暗渠になっていますけれども、当時の技術も含めて、耐震性が本当に大丈夫かどうかというのを１点お伺いをいたします。","respondent":"奥田河川下水道課長","answer":"東京都のほうで、そういった老朽化対応、それから、耐震性ということは非常に優先度高い認識を持っておりまして、実は今年度から調査を開始いたしまして、順次幹線のそういった老朽化事業とか耐震化事業、そういったのを行っていくと聞いてあります。","voiceIndex":331,"id":"exchange-134"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひそれは早急にやっていただきたいと思います。当時の技術と今の技術、全く違うと思いますので、そういうのを見たという方がいらっしゃったので、それを非常に心配されておりましたので、質問いたしました。二葉四丁目の第二京浜からちょっと入った１００円ショップのローソンがあります。これが技術的なものなのか、それともどうにかなるものなのか、それをお聞かせください。","respondent":"稲田道路課長","answer":"立会川のインターロッキングですが、道路の下部のボックス部分、コンクリートボックス部分、それから、土部分というところで、委員おっしゃる段差等ができております。それは長年の間でどうしようもなく発生するものでございまして、修繕等を日々やっております。","voiceIndex":333,"id":"exchange-135"},{"speaker":"たけうち委員","kind":"質問","question":"私は１５９ページの都市計画総務費、それから、１６３ページの密集住宅市街地整備促進事業について伺います。初めに都市計画総務費で、予算では職員給与費が４７名だったんですが、決算では５０名と３名増えていますけれども、これについてお聞かせください。そこが基本的にはいわゆる防災広場とかになるんじゃないかと思うんですけれども、これがどうなっていくか教えてください。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"その後につきましては、地域の方々とワークショップ等開きまして、防災広場というような形で整備をしていきたいと考えております。すいません。都市計画総務費の職員給与費についてはちょっと確認をさせてください。","voiceIndex":336,"id":"exchange-136"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。こういう空き地があるわけですね。そうすると、今これ、木密不燃化１０年プロジェクトの本格実施地区に応募、豊町四丁目とか五丁目、六丁目、二葉三丁目、四丁目とかって、応募されて、これが通ると、その辺の空き地になっているところがそういう２９号線の立ち退く方の代替の建物になるのか、区としてはどう考えているのかというのを教えていただきたい。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"現在、密集市街地整備事業を進めている二葉町、それから豊町地区なんですけれども、土地の提供をしていただいた方がいらっしゃいまして、例えば豊町五丁目高砂湯の跡地、大体５００平米ぐらいあるんですが、そういった土地ですとか。地域公共交通会議の設置に向けた今準備の状況ですけれども、この費用の中には、基礎調査をまず行いたいと。地域交通に関する基礎調査、それから、会議の運営の経費を見込んでいるものです。","voiceIndex":339,"id":"exchange-137"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。何かありましたらお答えいただきたいと思います。それからもう一つ、今本格実施に向けての流れの中で、二葉四丁目のＪＴの、ちょうど隣接しているところの密集しているところに個別訪問されて、いろいろあの辺の共同化だとか、そういったことについて今お話をされていると思うんですけれども、それに絡んで、ＪＴ、南のほうのところの地域を活用するということはないんですか。","respondent":"片田都市環境事業部長、品川木密整備担当課長、堀越人事課長","answer":"補足しますと、先ほど担当課長のほうが答弁しました区が取得した土地については、今後活用含めて検討していくというところもありますので、限定的な形で。周辺のやはり、この土地を中心としまして周辺のまちづくりのほうができないかというような形で、周辺のほう、ヒアリングをしていまして。その後、耐震化等の技術職の増員ですとか、そういった人員の一定の配置等がございまして、実績といたしまして５０人というような形で差が出ているものです。","voiceIndex":342,"id":"exchange-138"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。その密集住宅関係と２９号のいろんな沿線絡みのことは、非常に地域の方もいろんなところから情報が、またそれも違う情報が来たりして錯綜していることもありますし、我々もよくそういうところで聞かないとわからないこともあるので、しっかり、大変だと思うんですけれども、いろいろ大事な事業ですので、とにかく丁寧にやっていただきたいと思いますけど、その決意だけ教えてください。","respondent":"品川木密整備担当課長","answer":"これから木密１０年プロジェクトを中心にしまして、それから防災まちづくりに向けて、整備のほうを行っていきたいと考えております。周辺の住民の皆さんに関しては、間違った情報が行かないようにきちっとした形で周知をして、この事業を進めていきたいと考えております。","voiceIndex":346,"id":"exchange-139"},{"speaker":"本多委員","kind":"質問","question":"１６２ページの市街地整備事業費について質問します。品川区内それぞれの地区で進められておりますけれども、樹木の選定について、それぞれの地区で外溝工事を含めて樹木が選ばれていくと思うんですが、その樹木を選んでいく方法について教えてください。区のかかわりですとか、それぞれの地区で決めているのか、その辺の決め方について教えてください。","respondent":"溝口都市開発課長","answer":"どういった公園ですとか、そういったものも含めて緑化というのをどうやって取り組んでいくのか、そういったのをガイドライン等を定めてやっておりますので、そういったものに基づいて進めてきているものです。ほかの地区については、単独、地区ごとに基本的には定めている。","voiceIndex":349,"id":"exchange-140"},{"speaker":"本多委員","kind":"質問","question":"大崎駅西口南地区の樹木の決めた内容について、わかる範囲で教えてください。","respondent":"溝口都市開発課長","answer":"大崎駅西口南地区につきましては、１６３号線に植われている樹種があって、すいません、ちょっと樹種が出てこないんですけれども、街路樹に沿って同じような、クスノキです、クスノキが植わっております。","voiceIndex":351,"id":"exchange-141"},{"speaker":"本多委員","kind":"質問・要望","question":"この多摩産材利用開発事業により、助成制度もあるんですけれども、こういった場合、こういう助成制度が対象になるのか、ならないのか、また活用しているのか、その辺を教えていただきたいのと、あと、区の街路樹との整合性ですね。","respondent":"溝口都市開発課長","answer":"多摩産材の関係の補助金ですが、そういったものは使ったという事例は私どもは聞いておりません。","voiceIndex":353,"id":"exchange-142"},{"speaker":"本多委員","kind":"質問・要望","question":"わかりました。何かもったいないなという気がします。本来道路の左右一体のものを選ぶのがいいと思うんですが、南側と北側で、非常に北側のほうが本当に枯れちゃっていたんですね、今までが、従来が。それをよく考えて原状復帰をしていただきたいと思うんですが、樹木を選ぶ選び方は、その辺についてはいかがでしょう。","respondent":"溝口都市開発課長","answer":"百反通り沿いにつきましては、開発側につきましては、北側といいますか、百反通りの上側と少し樹種を変えた形で植えてきているところもあります。地域のご要望等も踏まえて、樹木については検討していきたいと考えています。","voiceIndex":355,"id":"exchange-143"},{"speaker":"本多委員","kind":"質問・要望","question":"品川区役所から大崎駅に向かう途中ですね、本当百反の一番下の部分ですけれども、渋滞をしているので迂回できないかと前に質問したことがあるんですが、なかなか難しそうで、今も迂回はしていないんですけれども、これから師走に向けて必ず渋滞がひどくなるというのが予測できておりまして、教習所の跡地を、あそこを入れて、１６３号線に並行した区道を使えば、百反通りに抜けれるので。","respondent":"溝口都市開発課長","answer":"そういった努力を重ねて、なるべく工事渋滞が起こらないように取り組んでいるものです。委員ご指摘の迂回路という形になりますが、なかなか工事費等含めて、莫大な費用がかかることも懸念されますので、引き続きそれについては検討させていただきたいと考えています。","voiceIndex":357,"id":"exchange-144"},{"speaker":"本多委員","kind":"意見","question":"現状での答弁理解できますが、できる限り、費用もそんなにかからないと思うんです。今、もう既に警備員を配置しているので、本当２人、３人増やすだけでできると思うので、ガソリンスタンドの迂回のところは全然効果がないと思いますので、検討してください。以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":359,"id":"exchange-145"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":116094,"voices":360}},{"id":"h25-20131009-4","meetingId":"h25-c-settlement","date":"2013年10月9日","dateIso":"2013-10-09","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時０８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開会いたします。 それでは、平成２４年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開会いたします。 それでは、平成２４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１６８ページ、クラブ・部活動指導費、１７１ページ、文化財保護事業、それから１７６ページの学校保健費の中の歯磨き指導法研究委託についてお伺いします。１６８ページのクラブ・部活動指導費なんですけれども、１,１３６万円余ということで、近年少しずつ増えておりますけども、改めて主な使われ方をお聞かせください。","respondent":"和氣学務課長","answer":"もう一つは、先生方が時間外に指導するときの報償費が一部入ってありますが、基本的には、多くは外部指導員で、さまざまなクラブでなかなか先生方だけでは指導しきれないところに、得意な方、指導力のある方をお呼びして。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"そのためには先ほどおっしゃったような専門的な外部指導員というのをもっと手厚く、今１コマ４,０００円ということでしたけれども、手厚くしていくべきじゃないかなと思うんです。そういったわけで、今よりも積極的に外部指導員を登用していただいて、予算もそれなりにつけていただきたいなと思うんですけれども、そのあたりのお考えをお聞かせください。","respondent":"和氣学務課長","answer":"こういう形でやっておりますのと、あと教員も実は生徒指導を含めて部活指導をやっていきたいということで、教員の中にも積極的に自分の生徒指導につなげていきたい、自分の指導力の向上につなげていきたいということでやっていることもありますので。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"１７１ページの文化財保護事業についてお伺いします。それから、この下のところに、埋蔵文化財調査費６件とありますが、これはどういったことを調査されているのでしょうか。区内で埋蔵文化財というのは、どういったところにあるのかお聞かせください。","respondent":"齋藤庶務課長","answer":"区指定の文化財ですけれども、１４０件あります。有形文化財が６２件、無形民俗文化財が３件、史跡２４件、天然記念物が２０件です。区の補助ですけれども、奨励金といたしまして、建造物、天然記念物は５万円、物件は１万５,０００円、無形民俗文化財は５万円です。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"特に無形文化財について、区指定の無形文化財なんですけれども、江戸里神楽とか大井囃子とかあるかと思うんですけれども、ちょっと区指定が少ないのかなと思うところがあります。文化財保護審議会で専門家が判断されることなのかもしれないですけども、どういった歴史があるとか、そういった条件とか、どういった条件で指定を受けられるのか、お聞かせください。","respondent":"齋藤庶務課長","answer":"昭和６０年に民俗芸能として、大井囃子が指定をされております。基本的な要件といたしましては歴史性、あるいはその伝統芸能がずっとそのまま伝わっている、伝承性ですとか、あとはオリジナルなもの、希少性といった三つの点で見ます。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"そういった歴史とかが重要だという部分はあると思うんでけれども、区内にもいろいろ伝統芸能ということで考えると数多くある、ほかにもあるんじゃないかなと思います。こういったことに対する区としての積極的な支援というのがなかなかないような感じですが、区としてどういった支援、こういったことに対する伝統芸能というか、地域のこういう芸能に対する支援というのは考えられるでしょうか。","respondent":"齋藤庶務課長","answer":"大井権現太鼓をはじめ、まちおこしですとか区の事業には多く参加していただいております。そういった面で何らかの補助支援ができないかというのは、区長部局ともちょっと相談できればなと考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"本当に先日本多委員からもありましたけども、伝統の味と技というのを商業的な事業でやられていますけれども、このような伝統文化を一堂に会して、例えば品川の伝統文化芸能展というのを教育という部分と伝統文化芸能の保持という観点から、それこそ歴史館とかを使ってでもできるんじゃないかなと思うんですけども、そういった伝統文化、これは伝統芸能とか伝統の文化財のことでお伺いしますけれども。","respondent":"齋藤庶務課長","answer":"教育委員会といたしましては、やはり文化財という視点での奨励、保護ということになります。現にある文化財を守るです。今委員にいただいたご提案につきましては、何らかの形で取り組みができるか、文化スポーツ振興課ともいろいろ話ができればというふうに考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"続きまして、１７６ページの学校保健費の歯磨き指導法研究委託についてお伺いします。この２校についての現状、どのように行っているのかということと、改めてその効果、どういった効果が出たかということ。昼食後に歯を磨くということを私はあまりしたことがないんですけども、そういったことで、どういった効果が出ているのかということをお聞かせください。","respondent":"和氣学務課長","answer":"そうすることによって、歯を磨く習慣をつけていただこうということを考えておりまして、これは保護者にも児童にもアンケートをとるんですが、大変好評でして、保護者の方も歯を磨く習慣ができたということで大変喜んでおられます。","voiceIndex":16,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"今のお話だと、同時にやられているということで、楽しそうな事業だなと思うんですけども、ただ、この同時にというのは、どんなやり方でやられているのかというのをちょっとお伺いしたくて、学校の水道というのは限られた数しかないかと思うんですけども、水道の蛇口をどのように使われているのかということと、足りないようだった場合は。","respondent":"和氣学務課長","answer":"特に学校はそれだけ時間をとられますので、教育課程の中で大分時間をとられてしまう、休憩時間とかも含めて組まなきゃいけないということもありますので、十分学校と相談して徐々に広げているところです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"ぜひともこれから、歯科医師会の人が足りないという話もありましたけども、ほかの学校にも広く広げていっていただいて、昼食後の歯磨きというのが習慣になるようにしていただきたいと思います。続きまして、ちょっとまだ時間があるので、１６９ページの市民科のことでお伺いをさせていただきたいと思います。","respondent":"渋谷指導課長","answer":"しながわ職場歩き、実際学校での学びと実社会とを結びつける、大変重要な機会だというふうにとらえております。働くということを教室で学ぶとともに、働いている方からその意義等をお聞きするということで、子どもたちにとっても大変効果のある事業だと考えております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問・要望","question":"会社側にとってもＣＳＲという社会貢献として大変受け入れてくださる企業が増えているということで、教育委員会と総務課とでいろいろお話をされて進めていただいている事業だと思うんですけども、どうしてもなかなか事務的な部分での負担が多いということで、先ほど言いましたけども、おととしは３校でありましたけど、去年も３校、今年は１校ということになってしまいましたけども、そういったところで。","respondent":"渋谷指導課長","answer":"授業時数との関係もありますが、校長会等に、またこういった取り組みについては広く周知をさせていただいて、取り入れるところは積極的に取り入れていただくように働きかけてまいりたいと思います。","voiceIndex":22,"id":"exchange-010"},{"speaker":"沢田委員","kind":"質問・要望","question":"事業としてそうやって取り入れていただく、子どもたちにとっても職場体験は、また講師が外部からいらしていただく事業とはまた別の違った形での職場というものを見られるという意味では、本当にそういう意味ではすごく重要な事業ですし、またそれから、この品川区だからこそできるという、この品川区にある中小企業、大企業もありますけど、そういった企業への協力という部分では、やはり総務課の力も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は１６９ページの市民科・各教科充実経費、これは衛生費での通告に従いまして、「７８円の命」ということでぜひお読みいただいて、ご感想をということでお願いしたので、その感想と、あと品川区でも同じような取り組みをされているというふうに伺ったので、その辺の状況を教えていただきたいと思います。","respondent":"齋藤庶務課長、渋谷指導課長","answer":"動物愛護に関連して、品川区では動物愛護作文コンクールというのを３２年間続けております。５年生、６年生を対象としておりまして、９月３０日に表彰式がございました。こういったことを通して、命の大切さを引き続き品川の小学校はしっかりと教えていきたいというふうに考えているところです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"まもるっちにつきましては、今２４件というふうにありましたけれども、その中で、私もまもるっちが始まってから８年ぐらいになるかと思いますが、ずっと協力員というんですかね、これになっているんですけれども、一度も今までそういう、近くにいた方にはそういう連絡が来て、駆けつけるというのがまもるっちかなと思うんですが、そういう形で協力者のほうに、そういう緊急のケースにご通知をして。","respondent":"上垣外生活安全担当課長","answer":"２４件中、協力員等が駆けつけた事案はございません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問","question":"ＰＴＡを中心に多分１万人を超える方が協力員になっていて、過去には協力者の通信ですとか、またそういう集いをやっていただいて、子どもたちを地域で守ろうということで取り組みが進んでいると思うんですけれども、実際にそういう方たちが駆けつけるということがないということなので、その辺は、ただ今まで過去にあったのかどうか。","respondent":"上垣外生活安全担当課長","answer":"ただ、実際にこの緊急事案としてあった案件につきましては、まもるっちセンターのオペレーターの的確な判断によりまして、最寄りのコンビニ等に児童を誘導する、つまり、保護者、保護する方がいるところに素早く誘導しているがために。","voiceIndex":33,"id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ただ、実際に、やっぱり１万人を超える方がそういうふうになっている中で、そのまま野ざらしといったら言葉が悪いんですけども、そういう意識を醸成していくというか、意識を高めていくとか、継続させていくというか、そういうことについてはどう考えているか。昨日も、三鷹の高校生の事件がありましたけども、そういった形で、希望者に対してお配りするという考えはどうでしょうか。","respondent":"上垣外生活安全担当課長","answer":"１点目の協力者が駆けつける体制ということにつきましては、もちろんそういう事案があって、周囲に保護することが期待できない、すぐ保護していただくことが期待できないという状況では当然駆けつけていただく必要がありますので、この点は十分気をつけております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"たけうち委員","kind":"質問・要望","question":"結構私どものほう、会派のほうにも中学生の希望者でいいのでという声は非常に多いです。もう一つの角度からいえば、今中学生は携帯を持っていますけども、携帯を持つことで、いわゆる別の意味での犯罪に巻き込まれるケースを防ぎたいという中で、まもるっちがあればという考えも一方であるわけなんですけども、そういうことも含めてぜひ今後検討していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問","question":"１７３ページの非構造部材耐震対策について、それとちょっとどこに入るかわからないんですが、通学路の安全対策についてということで質問をしたいと思います。１６８ページの教育会助成ということで、これも全般なんですが、以前お伺いした教育会というのは、先生の研修の場であるということをお伺いしておりますが、改めてどういった組織で、どうなのかということをお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"教育会は、先生方、教員の自主的な研究組織です。各教科あるいは領域ごとに、品川区の場合は小学校、中学校の教員が全て集まって、校長先生あるいは副校長を委員長として、品川の教育課題に沿った研究を進めているということで、ほぼ毎月１回ずつ研究会を実施しています。","voiceIndex":39,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ちらっと聞いたのが、まだ１回行ったということなんですが、実際どういう状況かということをお知らせいただきたいことと、音楽教員の教育会、日本民謡協会が出しております民謡指導マニュアルという、これも当時の指導課長から高い評価をいただいて、内容も充実しているということで、今後活用していきたいというお話をいただいておりますが。","respondent":"渋谷指導課長","answer":"マニュアルにつきましては、２年前の教育会か何かでたしかご紹介をいただいたもので、各学校、音楽の先生たちについては周知をしているところであるというふうに認識しています。","voiceIndex":41,"id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど教育会、把握をされていないということなんですが、行った方がたしか荏原第五中学校だったと思うんですけれども、教員の集まりへ行ってきたよなんていう話をちらっと聞いたので、その整合性というんですかね、どういう形で行われたかというのをお伺いしたかったんですが、これはよしとして、あと、この指導マニュアル、周知というか、２年前ということなんですが、ぜひせっかく内容が充実しているので。","respondent":"渋谷指導課長","answer":"おっしゃるとおり、研修は教員にとって自己の資質を高める上で非常に重要な機会です。特に押しつけの研修ではなくて、みずから資質向上を目指して研修に取り組むということについては、積極的な支援をしてまいりたいと思います。","voiceIndex":43,"id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１７１ページ、文化財保護全般なんですが、この文化財、先ほど沢田委員の質問の中で、ご答弁で、区指定が１５０件とたしか、僕の聞き間違いか、もし間違えていたら訂正していただきたいんですが、奨励金を出しているのが１０５件とここには書いてあるんですが、残りの４５件というのは、要するに奨励に値しない、要は先ほど言った太鼓とか、そういうのが該当しているのか。","respondent":"齋藤庶務課長","answer":"対象件数は１４０件です。残り３５件は歴史館で寄託をしておりまして、預かっております。行政のほうで管理をしておりますので、奨励金の対象にはなっておりません。","voiceIndex":45,"id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問","question":"文化財の推移というんですかね。ここは埋蔵試掘、試掘は試し掘りですから、本掘りというんですかね、ちょっと専門用語はわからないんですが、それに至ったのが実際あるのかどうなのか。それとも教育委員会のほうで、自分たちが地図を広げて文献などをあさって、ここにあるのではないかというのでそこを掘りに行っているのかどうなのかというのをちょっとお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"文化財指定の推移ですが、近年は１件程度でございまして、具体的に申し上げますと、いろんな物件の紹介がありますので、調査をして指定するということで、これからも文化財保護委員の方の目で見ていただいて、文化財的価値があるかどうかを判断していただきますので。","voiceIndex":47,"id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど来出ておりますさまざまな文化財があって、文化財とか伝統文化、そういうものというのは、古来からずっと伝わってきたものも一つの文化であって、文献を見て、近年それがスタートする文化財もありますので、先ほど来、そういうのも含めてしっかりとバックアップしてくださいという質問がありまして、何とか考えていくという話だったんですが、新たに生み出された。","respondent":"齋藤庶務課長","answer":"教育委員会といたしまして、文化財です。文化的な価値があるかということを見ながら、希少性、歴史性を見ながら、それが現代風にアレンジされたものでも、これから守らなければいけないものであれば、バックアップしていきたいと考えています。","voiceIndex":49,"id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１７１ページ、図書館経費についてということですが、まず、品川区全体が出ていればあれなんですが、とりあえず本丸である品川図書館の利用世代というんですかね、小中学生なのか、高校生なのか、大学生、社会人なのか、その利用世代というのがもしわかれば教えてください。そういう部分についてどうお考えなのか、お聞かせください。","respondent":"中元品川図書館長","answer":"２点目の品川区が記述されている資料の収集ですが、図書館のほうでも品川区立図書館の資料収集要綱というものを決めてございまして、その中で地域資料について別立てできちんと決めをしておりまして、その中で品川区に関する資料は図書、新聞、雑誌、行政資料、パンフレット、図。","voiceIndex":51,"id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問","question":"それをまた図書館のほうに持っていくというのもまた違うと思いますので、歴史館の資料室との連携というんですかね、なかなか歴史館は奥の深いものがいっぱいありますので、安易にホームページに公開するというのはできないかもしれませんけど、少なくとも図書館に行けば、そういったものが、こういうのがありますよという閲覧ができる、そういった仕組みも必要じゃないかなと考えていますが、いかがでしょう。","respondent":"中元品川図書館長","answer":"レファレンス等がございました際には、私どもの職員が品川歴史館のほうにお電話をしてご相談したりということで連携をしています。貸し出しにつきましては、歴史館の資料は貸し出し禁止という扱いですので、図書館に持ってきてということは現状ではちょっと考えてございません。","voiceIndex":53,"id":"exchange-024"},{"speaker":"いながわ委員","kind":"質問・要望","question":"次、ソフト面なんですが、パソコンの環境についてなんですが、品川図書館のホームページを開きまして、書物、蔵書の検索をして、ブラウザで「戻る」をやると、文字化けをしてしまうというんですかね、あと、ちょっとホームページの字がかぶっていたりというのもあるんですが、その辺をどうお考えなのかお知らせください。","respondent":"中元品川図書館長","answer":"こちらは、インターネットの仕組み上、対応に限界が技術的にありますので、今後図書館ホームページ内の利用方法のソフト部分での説明を充実させてまいりたいと思ってあります。","voiceIndex":55,"id":"exchange-025"},{"speaker":"いながわ委員","kind":"質問・要望","question":"次、非構造部材の対策についてですが、地震による落下物や転倒物から子どもたちを守るためにということで、文部科学省のほうから事例集とかも出ておりますが、今回ここに書いてあるように、小学校、中学校とやっておりますが、今後の日程というんですかね、全部の学校でやらなければいけないと思うんですが、どういった日程でやられるのか簡単にお聞かせください。","respondent":"齋藤庶務課長","answer":"４月に建築基準法が施行されます。直し方ですけれども、まだどういうふうに直せばいいかが文部科学省から示されておりませんので、来年の秋以降、示されましたら直ちに、非構造部材の取り組みをいたしまして、安心で安全な学校づくりを進めてまいります。","voiceIndex":57,"id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問・要望","question":"子どもたちが学んでいる学び舎ですので、なるべく早くやって、これからもどんどん指針が変わっていって、その都度またやっていかなければいけなくなってくるかもしれませんが、本当に計画的にお願いしたいと思います。これに関して、どういう取り組みをされているのか、ちょっと時間がないのでお答えいただきたいなと思いますが、お願いします。","respondent":"中村建築課長","answer":"現在は、カラーコーンを立てて注意を喚起していますけれども、また居住人に対しても継続して、今改善の働きかけを行っているところです。","voiceIndex":59,"id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひ部の間で問題意識を持っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-028"},{"speaker":"吉田委員","kind":"確認","question":"私は成果報告書の１７６ページ、児童・生徒健康管理費、続きまして、１７５ページ、給食運営費の中の生ごみ処理費、戻りますが、時間がありましたら、１７４ページ、学校図書館運営費についてお伺いいたします。児童・生徒健康管理費なんですけれど、学校の健康診断についてお伺いいたします。そしてもう１点、学校側から気づくという事例はあるのでしょうか。３点お伺いします。","respondent":"和氣学務課長","answer":"相談という形で対応しておりますので、全員一律に相談を、聞き取りをするということではなくて、健康相談の中で気になる方についてはご相談いただきたいという形で周知をし、健康相談の延長でその後の対応もしています。","voiceIndex":63,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、学校で検査が中止されたという経緯は何でなのかなということをちょっとお伺いしたいのと、また今希望者に対してやっていらっしゃることに関して、仮性同色素とパネルＤ－１５、アノマロスコープでしたか、この３個の種類があって、この検査、どれをやっていらっしゃるのかなということ、その２点、お願いいたします。","respondent":"和氣学務課長","answer":"それは専門家がちゃんとしっかりと検査をする必要があるということと、色覚についてはかなり多様でございまして、軽々に判断することはできないということで、基本的に、最終的には専門医に行っていただく、そういう形で私どもは指導しています。","voiceIndex":69,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"ご答弁ありがとうあります。今後、やはり早期発見という意味で、お子さんを預かっている以上、何らかの対処を、個人的なこともあるんですけれど、いろいろ対処の仕方があると思うので、早期発見という意味でのお考え、またはこういう色覚特性のお子さんに対して、教師の皆さんの配慮が、先ほどちょっとお伺いしましたけど、具体的にどのようになさっているのか、２点お願いします。","respondent":"和氣学務課長、渋谷指導課長","answer":"あくまでも、これは申し出ということで、こちらからそうじゃないかというふうに言うこと自体も、かなり傷つけてしまう可能性もありますので、申し出をなるべくしていただけるように周知をしています。進路指導等々で、実際高校入試で色覚に何かということでの記載をするようなものはございませんが、場合によって、電気系統に進むときに、例えば配線で見にくかったりだとか、そういったことがあったりするケースもありますので。","voiceIndex":71,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"手厚いそういう指導をしていただくと、とても助かると思います。時間もないので次に行きまして、給食運営費の生ごみ処理費なんですけれども、これは委託ということで、毎年このくらいの処理費がかかっているんですけれども、食育の面でどのようにお考えか。そしてまたリサイクルをしていたようですけれども、その辺をちょっとお伺いしたいと思います。","respondent":"和氣学務課長","answer":"それで、かつてコンポストというものを各学校に設置して、多古町等と交流をしながらリサイクルをしていたわけですが、コンポスト自体が老朽化をして、大変に修理費等で大きな金額がかかるということと、それからコンポストの管理自体が大変負担になってございまして。","voiceIndex":74,"id":"exchange-032"},{"speaker":"吉田委員","kind":"提案","question":"わかりました。手がかかるものだったということがわかったんですけど、ちょっとここで私一つ提案なんですけれど、新しいもので、ご存じかもしれないんですけど、生ごみ処理消滅機というのがあるんですよね。そして、においもほとんどなく、換気機能が整備されている。この辺のちょっと導入をお考えではないでしょうか、いかがでしょうかということをお願いします。","respondent":"和氣学務課長","answer":"今のリサイクルしたのは、配合飼料という形でちゃんと生きておりますので、全くなくなってむだにしているわけではないので、基本的にはこれを続けていきたいというふうに考えているところです。","voiceIndex":76,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"コストもかかるものですし、今までの、従来のものも使っていくというのもわかるんですけれども、これもちょっと研究していただきたいなと思います。これは学校の給食の生ごみです。食育でもあり、地球環境の意識の教育にもなると思うので、一石二鳥になると思うので、ぜひご検討をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは成果報告書１６８ページ、プラン２１推進事業にかかわって、プラン２１第４ステージの取り組みと学校選択制小中一貫教育について伺いたいと思います。この調査検討の結果を伺いたいと思います。そしてもう１点、プレスにあります児童・生徒による一貫教育についてのアンケート調査というのは、その後どうなったのかご説明をいただきたいと思います。","respondent":"渋谷指導課長","answer":"今ご説明しました第一日野小学校と小山台小学校については、今年度末に発表の予定、それ以外のところについては、来年度３年間の研究で発表する。そのときに一応一定の成果なりを公表していくと、そんな考えでいるところです。","voiceIndex":80,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"しかし、いじめを苦にした自殺の件を通じて、アンケートそのものにもううんざりだと、本音であればあるほど、先生はもちろん、親友であればあるほど話したくない、そんな子どもたちの本音もよく伺います。先生や学校との間に信頼関係がなければ、子どもの本音も聞けません。機械的にならないよう、教育的な配慮も含めて、こうした調査の実施については今後どう考えていくのか伺いたいと思います。","respondent":"渋谷指導課長","answer":"アンケートのとり方につきましては、どういうような目的で、どういう中身にするか等々につきましては、校長会等現場の先生方の意見も大いに聞きながら、実質意味のあるものにしていきたいというふうに考えているところです。","voiceIndex":82,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"９月末に示された保護者アンケートですけれども、読ませていただきました。「小中一貫教育はよい取り組みだと思う」で、「思う」の合計が４割、「４・３・２のまとまりで考えることは有効であると思う」では、「思う」の合計で３割半ほどです。具体的な教育改革については、保護者の実感が薄いあらわれなのかなと私は思うんですけれども、この傾向の原因について、区の見解を伺いたいと思います。","respondent":"渋谷指導課長","answer":"逆に、教育委員会としては、小中一貫教育として取り組んでいる市民科であり、また小学校英語、その具体のものについては大変高い評価をいただいておりますので、学校につきましては、この保護者アンケートを校長会で説明をいたしまして。","voiceIndex":84,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"４・３・２の生徒に子どもを合わせるのではなくて、子どもの成長に合わせて、ふさわしい節目として、ぜひ小中一貫校でも従来のような小学６年生の卒業式を復活させていただきたいと思いますけれども、この点を伺いたいと思います。合同運動会もそうです。小学校、中学校を別々に実施するなど、子どもの成長、発達に合わせた運動会に変えたほうがよいのではないかと思うんですけれども、いかがでしょうか。","respondent":"渋谷指導課長","answer":"１年生から９年生まで、まとめて全体の運動会を実施している一貫校もあります。６年生、それから７年生、８年生、９年生というふうに分けて運動会を実施しているところもあります。６年生の卒業式、確かに有効だというお考えもあります。","voiceIndex":86,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"新しい学校だからと、その仕組みを子どもに合わせるのではなくて、やっぱり子どもの成長や発達に合わせていくべきことが教育ではないのかなと私は思います。一度立ちどまって子どもたちの声、アンケートもそうですけど、保護者の声に耳を傾け、見直し、検証すべきではないかと思いますけども、ご意見を伺いたいと思います。新たな仕組みなど、対策についても今後の方向を伺いたいと思います。","respondent":"渋谷指導課長、和氣学務課長、齋藤庶務課長","answer":"４・３・２という一つの大きなまた新たな考え方の中で、今の目の前の子どもたちのさまざまな課題に対応できるのではないか。それに対して保護者はやっぱりきちっと反応して、やはり継続してほしいという声を強く出していますので、その傾向は変わらないというふうに考えてあります。私どもとしては、あくまで長期基本計画素案ですので、これからまた字句の修正もあるかもしれませんけれども、例えばＰＴＡのところに町会加入促進で、活動。","voiceIndex":88,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"６・３制に無理やり押し込んできたという認識そのものが、私はどうなのかなと思います。選択制のほうですけれども、地元との関係の話もありましたが、選択制によって地元との関係が薄れたのであれば、やはり原因である学校選択制そのものを私はやめていくべきだと改めて思いますので、ぜひ検討していただきたいと最後に要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-040"},{"speaker":"渡部委員","kind":"質問","question":"吉田委員から先ほど質問ありました。僕も色覚異常を伺おうと思っていたんですが、色覚異常で、やはり１０年、その検査を学校でやらなくなって１０年経った。これは先天的なものですよね。中止になった理由の一つに人権の問題等もあるというふうに伺っております。保護者に認識を持ってもらうというのがいいのかななんていうのが、ちょっと僕の中の答えだったんですが、いかがでしょうか。","respondent":"亀井品川保健センター所長","answer":"ただ、あまりこちら側から積極的に、親御さん全員に色覚のこういう問題があるのでどうですかというようなアプローチはやっぱり少し難しいかなと思いますが、相談があればそれには的確に乗っています。","voiceIndex":94,"id":"exchange-041"},{"speaker":"渡部委員","kind":"質問・要望","question":"積極的にやるものではないというのは当然そうなんですが、でも２０人に１人というのは多いですよね。ページで言うと、無理やり１７４ページの通学の安全確認ですけど、きのう交通安全担当課長にもお伺いしました、スクールゾーンなんですけれど。なかなかハードルが高いのは文教委員会の中でも伺いましたけど、改めて伺います。教育委員会として、第１・第３土曜日のスクールゾーン、必要性を感じていますか。","respondent":"齋藤庶務課長","answer":"７時半から８時半まではスクールゾーンだけど、ただし書きを品川区においては、第１・第３・第５土曜日を除くというふうにはオール都としてはできないと、こういうふうに言われております。","voiceIndex":96,"id":"exchange-042"},{"speaker":"渡部委員","kind":"質問・要望","question":"地域の方からしてみると、１年半、第１・第３土曜日にやっていて、前から何かいろいろ、うまを出したりとかやっている中で、何も変わっていないねという声があります。所管移動されて、何か問題とかなかったですか。なかったですかというのが一つと、やはり今後、といいますか、今もそうなんだけど、児童センターといわゆるすまいるスクールの連携というのは、どうなっていますかという２点、お願いします。","respondent":"伊崎子育て支援課長","answer":"児童センターとの連携ですが、今申し上げましたように、この半年はとにかく円滑な移管ということに心がけておりました。ですので、内部ではいろいろと検討はしておりますけれども、まだ具体的な対策、対応をとるというところまでは至っていないというのが現状です。","voiceIndex":98,"id":"exchange-043"},{"speaker":"渡部委員","kind":"質問・要望","question":"どんな町会の方々とお話をしても。であれば、ある程度結びつきというのを決めて、職員配置下には５名から６名の区の職員の方がいらっしゃいますので、やはり地域で地域の子どもを見るという仕組みにするのであれば、そういうグルーピングをしかけていただいて、全体的な活動を何かされてもいいのではないかと考えていますし、そのほうが職員の方も１人配置じゃないですか、学校って。","respondent":"伊崎子育て支援課長","answer":"ですので、全くつながりがないということではないんですけれども、どのような形をとれば、この移管の目的である青少年健全育成事業の一体的・効率的な運営というところの目的が果たせるかということは、今検討していますので、もう少々お待ちいただければと思います。","voiceIndex":100,"id":"exchange-044"},{"speaker":"渡部委員","kind":"質問","question":"もうちょっと待ちますので、ぜひまた発展して、品川の子どもたちが元気に楽しめるようなすまいるスクールであり、児童センターであってほしいと思いますのと同時に、今申しましたように、やはり学校とすまいるスクールとの連携というのは太いパイプで結ばれているこの仕組みづくりだけはしっかりやっておいてくださいということで、この質問も終わります。教育委員会、感想を聞かせてください。","respondent":"和氣学務課長","answer":"それも踏まえまして、しっかりと保護者にメッセージを伝えたいということで、工夫をさせていただいたものです。本当にありがとうあります。","voiceIndex":102,"id":"exchange-045"},{"speaker":"渡部委員","kind":"質問","question":"３割以上の方が使われるこの選択制です。いかにわかりやすい仕組みにするかということが僕は大事だと常々思っていました。本当にわかりやすいです。３月にまたどういう結果が出ているか伺います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"１６７ページ、教育指導費でありますけれども、一昨日、聾者と健常者が共生する地域社会の実現を目指し、手話を使いやすい環境へ政策を計画的に進めるために、手話を言語と位置づけ、普及を図る全国初の手話言語条例、昨日ですかね、８日の鳥取県議会で成立されました。学校での手話教育などの関連補正予算２,２００万円も可決されたということで、報道されておりました。","respondent":"渋谷指導課長","answer":"聴覚障害について学ぶ授業というご質問ですが、品川区の場合は、市民科の授業の中でそういった他者理解というような領域の中で、例えば手話の講習会であったりだとか、点訳の講習会だったりだとか、そういった取り組みに何校かの学校が参加しているというような状況があります。","voiceIndex":106,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"他者理解、他の者と書くんですか。手話講習会にも参加されているということで、それも拡充をぜひしていただきたいと思います。それで、ちょっと突然になるかどうかあれなんですが、「聲の形」という作品があります。声、難しい聲と書きます。「聲の形」という作品がありますけれども、これはご存じかどうか認識を教えてください。","respondent":"渋谷指導課長","answer":"大変申しわけありません、認識していないところです。","voiceIndex":108,"id":"exchange-048"},{"speaker":"つる委員","kind":"提案","question":"認識がございませんというご答弁でありましたので、まずそれを研究していただかないとなかなか難しいと思うんですが、こうした全日本ろうあ連盟がしっかりと監修をしている作品でありますので、この「聲の形」という漫画を通じて、インクルーシブ教育の件もありますけれども、学校の障害について学ぶ授業に生かしていただけたらいいんじゃないかなと、こういった提案をさせていただきたいと思うんです。","respondent":"渋谷指導課長","answer":"そういった障害についての取り扱いにつきましても、市民科等の授業の中で、どのような形で生かしていけるのかということについても、また教育会等々とも連携しながら考えていきたいというふうに思っております。","voiceIndex":110,"id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"そこで、環境の充実という観点で、昨年の一般質問で、電子図書館の提案をさせていただいて、最近の報道でも少しずつ増えてきたよという報道が出ておりますし、また角川書店とか、紀伊国屋書店、講談社が協力をして、公共図書館向けの貸し出し専用の電子書籍、これを発売する予定で準備を進めているそうでありますけれども、こうした動きを含めて、改めて提案をしたいと思いますが。","respondent":"中元品川図書館長","answer":"電子書籍の扱いですが、昨年の定例会におきましてもご回答しておりますが、障害者サービスの観点から一定の導入効果は私どもも認識しています。ただ、行政として、区として導入するに当たって、継続性、安定したサービスの提供、費用面の課題について継続して研究しています。","voiceIndex":112,"id":"exchange-050"},{"speaker":"つる委員","kind":"提案","question":"あわせて、図書館に関してですが、先ほどのマララさんの言葉も含めてなんですが、子どもたちにとって、今現在たしか昨年度か、予算とかだったでしょうか、私がご質問させていただいたんですが、品川区は非常に読書環境というか、子どもたちが本に親しむというのは非常にランクが高いというふうなたしかご答弁をいただいたと思いますけれども、その上で、より積極的に読書に親しんでいただきたい。","respondent":"渋谷指導課長","answer":"学校の図書館運営については、小学校も中学校も図書委員会を中心にして自主的な活動を促しています。そんな図書委員会等の活動に今委員ご提案のようなものが取り入れられるのかどうか、情報提供させていただきたいというふうに思っております。","voiceIndex":114,"id":"exchange-051"},{"speaker":"つる委員","kind":"提案","question":"ご存じかと思います。その人の言葉の中に、変化の激しい時代にこそ、絶えず新しい試みを、新しい開拓を、そのように訴えておられましたので、ぜひ新しい挑戦、新しい開拓、さまざま今後も提案しますので、ご検討をお願いしたいと思います。教育費、ちょっと具体的な場所がわからなかったので教育費ということでお尋ねしますが、要は一般質問でも触れさせていただきました食物アレルギーに関してのお尋ねです。","respondent":"和氣学務課長","answer":"基本的には養護教諭がしっかりと保管をして、保健室のほうで保管しています。","voiceIndex":116,"id":"exchange-052"},{"speaker":"つる委員","kind":"質問","question":"養護の先生が保健室で管理、これはいろんな個人情報とかがあると思うんですが、金庫とか、そういった形で管理をされているのか、それとも緊急時にそれをどういうふうに使うのか、この辺も含めて教えてください。","respondent":"和氣学務課長","answer":"基本的にはちゃんとキャビネットがありますので、個人情報になりますのでしっかり管理をしていますが、緊急時等について、特にアナフィラキシーショック等の関係がある場合については、保護者の同意を得て、例えば緊急連絡先ですとか対処方法をしっかりと何枚かつくって。","voiceIndex":118,"id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"センシティブ情報というんでしょうか、そういうのがいっぱい書かれているので、全部が全部お聞きできないとは思うんですけども、今ご答弁いただいたように、ある程度必要な情報を書き出して教室に張ったりとか、先生がお持ちで管理をされている、そういう形での対応だというふうに認識をしました。は生活管理指導表にも書きますけれども、かかりつけ医の先生の名前。","respondent":"和氣学務課長","answer":"私ども、今新しいマニュアルを検討していますが、そうした生活安心カードも含めまして、例えば子どもに何を持たせているかとか、一目でわかるようにどうするかとか、さまざまなところでいろんな工夫をされてありますので、それを総合的に考えて。","voiceIndex":120,"id":"exchange-054"},{"speaker":"つる委員","kind":"質問・要望","question":"今ご答弁で、生活安心カードと言いましたが、子ども安心カードが渋川市で取り入れている名前だと思うんですが、名称はともあれ、さまざまな形で子どものそうした緊急時の対応、これが迅速に学校現場でも消防等々の連携の中で行えるようにしっかりとした体制をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"１６７ページの義務教育施設整備基金積立金、１７０ページの特別支援教育費、ちょっと場所はわからないんですが、多分教育指導費の中に入るんだと思いますが、運動会についてお聞きします。それで、金額の根拠、それから財源はどこから来るのでしょうか。運動会です。これはおかしいと思います。おかしいです。これはここの学校だけなのか、ほかの学校がどうなっているのかというのをお聞きしたいと思います。","respondent":"渋谷指導課長、本城企画財政課長","answer":"卒業生だったり、他校生が来ることによって、やっぱり生活指導上の問題を危惧するという声が、やっぱり荒れた。義務教育の基金の積み立ての件ですが、今後予想される改築需要を見込みまして、可能分を今回積み立てたものですが、財源といたしましては。特別支援早期発見と、また一貫したご支援、確かにおっしゃるとおりで、今特に義務教育を担っている私たちの部分では、就学相談の際に。","voiceIndex":124,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"これはしっかりと取り組んでいただきたいというふうに思っておりますので、これは要望で終わります。運動会です。ほとんどの親が来るんですよ。やっぱりそれはするべきだと思います。先ほど１点お答えになっていただけないのが、ほかの学校はどうなんですか、ここだけの学校なんですか。小学生で、運動会で一緒にお弁当を食べていない学校はここだけですかということをもう一度お聞かせください。","respondent":"渋谷指導課長、本城企画財政課長","answer":"すみません、小学校は、多分、おそらく大方一緒にお弁当を食べるような取り組みをしているというふうに認識しています。一貫校におきましても、例えば１年生から９年生までまとめて運動会をやっているのは、現在は伊藤学園と八潮学園。平成２０年ごろが一番のピークだったんですが、その間、いろいろ改築等の関係で、この間取り崩しているものを含めて、現在の水準になっているんですが、今後につきましても、これから改築需要を見極めまして。","voiceIndex":128,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"これ、いいんでしょうか、ということで、強く私はここは改善していただきたいと思います。それと、行事に関しても、やはり深く考えてほしいんですね。ただ、やはり親子の絆であるとかということになったときに、いじめ対策にしても非常に大切な部分でありますので、もう少し深く、学校の一つ一つの行事を効果があるように見直しを図りながら推進をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-058"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、成果報告書の１７６ページの学校保健費から２点、１６９ページのマナーキッズ教室委託について、それと時間が余れば、１６８ページのプール指導に関してお尋ねいたします。成果報告書の１７６ページの学校保健費に関連して２点お尋ねいたします。この新しい登校停止基準は、昨年学校現場において順調に運営されたのか、何かトラブルはあったでしょうか、まずお伺いしたいと思います。","respondent":"和氣学務課長","answer":"これにより、出席停止解除の判断がより厳格になったというふうに私どもは捉えてあります。ただ、今回の運用方法の変更によって、区民の皆様や保護者の皆様からご不満の声はこれまで特段いただいてございません。おおむねご理解いただいているというふうに考えてあります。","voiceIndex":134,"id":"exchange-059"},{"speaker":"鈴木（博）委員","kind":"意見","question":"私の経験でも、熱が出てクリニックを受診され、インフルエンザの検査が陽性で投薬し、次回５日後ぐらいに再診を指示しても、受診されない方もいらっしゃいます。最後に、今シーズンのインフルエンザ、もう流行が目前に迫っておりますが、現在の学校側のインフルエンザの流行に対する対策、取り組みについて簡単にご説明をお願いしたいと思います。","respondent":"和氣学務課長","answer":"インフルエンザはあくまでも予防が大事というふうに考えておりますので、予防の指示をしています。","voiceIndex":136,"id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次、第２点、感染症、感染性胃腸炎の取り扱いについてお伺いします。保護者の方から間接的な伝聞なので正確な内容はわかりませんが、現在学校ではウイルス性胃腸炎という診断書を保護者に要求されている、ないしはウイルス性胃腸炎の診断書を持参した児童は欠席扱いしないというような対応がなされているのでしょうか。お聞きいたします。","respondent":"和氣学務課長","answer":"ウイルス性の胃腸炎は、感染性の胃腸炎というのは、学校保健法で第３種の感染症とされておりまして、品川区立の小学校では、おおむね保護者からの相談や申し出で妥当と判断されれば出席停止というふうにしています。","voiceIndex":138,"id":"exchange-061"},{"speaker":"鈴木（博）委員","kind":"質問","question":"したがいまして、特に個発的、特にそれほど症状が重くないようなお子様に関しては、登園許可証ないしは出席停止という措置は必要ないと考えられますので、その辺は弾力的な運用をお願いしたいと思います。しかし、症状がなくなりましても、便からは１週間そのウイルスが排出されますので、治癒証明というのはありません。次に、１６９ページのマナーキッズの教室委託についてお伺いいたします。","respondent":"渋谷指導課長","answer":"マナーキッズについてですが、平成２１年度６校導入したのを皮切りに、平成２４年度、昨年度は２３校、今年度は１７校で導入する予定です。実際の授業ですが、今お話がありましたように、小笠原流の礼法師範の方が最初１０分ほど全体に礼法、挨拶の指導をしていただく。","voiceIndex":140,"id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ご説明ありがとうございました。すばらしい取り組みのように見えるんですが、何か具体的な成果などが上がっているというような判断できる点はあるのでしょうか。このような点に効果があったという具体的な事例があったらお示しいただきたいのと、今後このマナーキッズ教室を増やす予定とかはあるんでしょうか。","respondent":"渋谷指導課長","answer":"成果については、なかなかご説明が難しいんですけれども、委員が学校に行って、子どもの挨拶の仕方を見て、次のような挨拶をしている子がいたら、マナーキッズの成果だというふうにご判断いただければと思います。","voiceIndex":142,"id":"exchange-063"},{"speaker":"塚本委員","kind":"質問","question":"私からは１７０ページの特別支援教育、それから１７３ページの学校管理費で、最初に１７３ページの学校管理費から、通学路の安全対策ということでお伺いをしたいと思います。一定の点検の報告書等ができて、それから随時対応していくというようなことでお話を伺っておりますけれども、現在の進捗状況についてお伺いをしたいと思います。","respondent":"稲田道路課長、齋藤庶務課長","answer":"それの対策についてです。本年１０月末で９８％ほど道路管理者が行う対策というのが進捗する状況です。１２月末には１００％全部完了していきたいという予定で今進めております。それは物理的にガードパイプを置けないとか、信号を設置できないといったことで、子どもたちが気をつけなければならないところ、見通しの悪いところが７カ所、交通量が多いところ１５カ所、道路が狭いといったところが４カ所あります。","voiceIndex":145,"id":"exchange-064"},{"speaker":"塚本委員","kind":"質問","question":"人の行き来ができるようになっていたために、小さなお子さんがそこを横断しようとして交通事故に遭ったということがありました。こういった警察との協力を得るための方策というか、やり方というのは、今後どういったことが考えられるのか、お考えをお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"警察の方の見る交通安全の視点と、ＰＴＡや私どもが見る危険な箇所が違うこともわかりました。そういったことで、意見を議論する場がございました。そういった関係も築きながら、交通安全担当課長もおりますので、より一層、４署の交通安全課と協力してまいりたいと思います。","voiceIndex":148,"id":"exchange-065"},{"speaker":"塚本委員","kind":"質問","question":"今品川区におきましては、特別支援教育の中で通級制度というものが実施されていて、言語障害の通級指導としては戸越小学校１校、難聴通級指導として台場小学校、情緒障害等通級指導ということで、浅間台小学校、宮前小学校、源氏前小学校、そして中学校が大崎中学校と浜川中学校ということで実施をされておりますけれども、この通級に通っていらっしゃる生徒が。","respondent":"渋谷指導課長","answer":"それぞれそのお子さんの障害特性に応じて、その抜ける時間というのは月に３時間、４時間というケースもありますし、最大でも週に８時間程度、その個別の計画に基づいて指導しているというのが実態です。","voiceIndex":150,"id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"保護者の方からは、例えば通級を放課後に実施してもらえないだろうかとかという要望もあるかというふうに聞いておりますけれども、こういった普通授業に参加できないという課題、その解消に向けて、どのようなことを今考えられるか、ご意見をお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"そういった部分におきまして、品川区におきましては、特に通級指導が必要なお子さん、特に通常学級に在籍をする発達障害のあるお子様については、学習支援員というような制度を設けておりまして、そういう学習支援員を活用して個別の対応をしたりとか。","voiceIndex":152,"id":"exchange-067"},{"speaker":"塚本委員","kind":"質問","question":"かなり今多くの方に協力をいただいているというふうに思いますけれども、学習支援員の方がいわゆるいろんなことで教員の方とは直接話ができないというような状況になっているという話がありますけれども、そういったところで、学習支援員の方が通級のフォローとかをする場合に、そういった権限の強化というのもちょっと変なんですけれども、できることの範囲の広がりみたいなことというのは必要ないかどうか。","respondent":"渋谷指導課長","answer":"その個別指導計画を共有することによって、学習支援員の方にその子にとって適切な指導をしていただくように徹底をしていると、そういう現状です。","voiceIndex":154,"id":"exchange-068"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。では次に、同じく特別支援教育絡みで、特別支援コーディネーターという方が各学校に１名ずつ任命をされていると思いますけれども、特別支援コーディネーターの役割と、また任命するに当たって、どういった点を、スキルといいますか、どういった方を適任として任命しているか、この辺についてお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"区といたしましては、そういう各学校の特別支援コーディネーターを集めた研修をして、障害についての専門性を高めたり、あるいは時間割の調整をしたりだとかする教務的なことについて、技量が高められるような取り組みをしています。","voiceIndex":156,"id":"exchange-069"},{"speaker":"塚本委員","kind":"質問","question":"たしかそんなことがあったんじゃないかというふうにあるんですけれども、都のそういった研修みたいなものにもしっかりと参加をされて、特別支援コーディネーターの方のスキル向上といいますか、そういうことに努められているようなことがあるかどうか、そこをお伺いします。","respondent":"渋谷指導課長","answer":"水道橋にあります東京都教職員研修センターで、コーディネーターを対象にした研修もありまして、そういったものについては区内の先生方も多く参加しています。","voiceIndex":158,"id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"なおかつ品川区の中で、この免許所有者というのはどれぐらいいらっしゃるのかお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"特別支援学校教諭免許についてのお尋ねですが、今ちょっと正確な人数は出ませんけれども、大変少ない、１割弱というのが実態です。通常学級に在籍する教員については、特別支援学校教諭免許そのものを持っている者が非常に少ないというのが実態です。","voiceIndex":160,"id":"exchange-071"},{"speaker":"塚本委員","kind":"質問","question":"品川区の教育委員会にお伺いするのはちょっと酷な話なのかもしれませんが、なぜ少ないのかというか、この辺の、資格者が増えてこない理由というのはどの辺にあるとお考えでしょうか。","respondent":"渋谷指導課長","answer":"東京都も、今後特別支援の専門家としての免許所持者を増やしていくと、そういうような方向性で今動いているというふうに聞いております。","voiceIndex":162,"id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"じゃあ、ちょっと時間が残りましたので、最後にちょっとだけお伺いしたいんですけれども、１６９ページで、理科指導力向上というところで、今回の補正においても、理数フロンティア校の取り組みということで、新たに理数系に力を入れていこうというようなことで、今力が入れられているのかなと思いますけれども、こういった事業をされている背景には。","respondent":"渋谷指導課長","answer":"子どもたちの理数離れも確かにそうなんですけれども、小学校においては、理科を上手に指導できない先生が増えてきているというような課題があります。","voiceIndex":164,"id":"exchange-073"},{"speaker":"渡辺委員","kind":"質問","question":"成果報告書１６９ページで、マナーキッズ教室委託とまちの人々に学ぶ授業に入るんですかね、伺いたいと思います。初めに、まちの人々に学ぶ授業に該当するか、あるいは連合体育大会のところにかかわってくるかと思うんですが、盆踊りというテーマで伺いたいと思います。今運動会シーズンで、いろいろな場所で盆踊りが実施されているかと思います。ちょっとイメージと違ったんですね。","respondent":"渋谷指導課長","answer":"昨今のダンスブーム等を反映して、そういったものについては、子どもも非常に興味、関心、意欲が高く、取り組んで、大きな成果が上がっているというふうに聞いております。","voiceIndex":167,"id":"exchange-074"},{"speaker":"渡辺委員","kind":"質問・要望","question":"次はマナーキッズについて伺います。平成２４年度の決算で８０万円ですか、ありますが、委託されている中で、ＮＰＯ法人のプロジェクトに、委託の内容、これは回数だとか、そんな目安があるのか、大まかで構いませんのでお知らせください。そういう意味では、今限られた中で申し込みというか、希望の状況なんかがどんな背景があるのかお知らせください。","respondent":"渋谷指導課長","answer":"その検証につきましては、学校等の声も聞きながら改めてしっかりと検証を行っていきたいというふうに考えているところです。","voiceIndex":169,"id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問","question":"マナーキッズ自体のパンフレットに、ものすごく仰々しいわけじゃないんですが、文部科学省の後援に始まり、大手企業がものすごくこのプログラムに協賛されていると。それとあと、プログラムをした学校での日常での生かし方というんですか。そういった意味での活用といったら失礼ですが、そういう形ですね。そんなことの可能性、それとあと子どもの日常生活、そこでの生かし方、その辺をお知らせください。","respondent":"渋谷指導課長","answer":"今後保護者等へのそういったものについても、ぜひ多くご紹介できるような、そんな機会を考えていきたいというふうに思っているところです。","voiceIndex":171,"id":"exchange-076"},{"speaker":"渡辺委員","kind":"意見","question":"やはり通常、集まられる機会、おそらく僕もお話を聞いている中で、こういう師範の方だったりは、５分だったら５分に集約できる、すごく臨機応変にされるケースがあると思いますので、大きなやはり人の集まる場所に活用されたらと思います。それとあと、そもそも論ですが、市民科の理念に本当に沿う点だと思っています。","respondent":"渋谷指導課長","answer":"幼稚園にも幾つか取り入れて実践をしていますので、発達段階に応じてそういった指導が充実するように、今後も取り組みを続けていきたいというふうに考えているところです。","voiceIndex":173,"id":"exchange-077"},{"speaker":"南委員","kind":"質問・要望","question":"もう一つ厚生労働省の資料で、子どもの虐待の推移を見てみると、１９９８年から虐待が急増していると、こういう資料がありまして、この１９９８年はどういう年かというと、自殺する数が３万人を超えた年なんですね。その辺からちょっと伺ってみたいと思います。そして、その状況ですね。平成２５年度もどうかということがもしわかれば、年度途中でありますけれども、教えていただきたいと思います。","respondent":"和氣学務課長","answer":"就学援助認定率ですが、今委員の指摘が平成２４年に増えたですが、平成２４年は減ってあります。平成２３年度は全体で２７.１％でございましたが、平成２４年度は２７％、平成２５年度につきましては、２５.７％という形で推移しています。","voiceIndex":176,"id":"exchange-078"},{"speaker":"南委員","kind":"質問","question":"貧困の状況もちょっと答えていただきたかったんですけれども、後でお願いします。減っていると言っても、２７.１％が平成２３年度で、平成２４年度は２７.０％ですよね。そして、もしまだまだ受ける対象にはあっても、受けていない方、ご希望で受けていないのかもしれないですけども、そういう方々への働きかけをする必要があると思うんですけど、その辺がどうなっているのか教えてください。","respondent":"和氣学務課長","answer":"就学援助が、そういう意味でなかなか家庭の経済状況で、学校生活に困難がないようにということでやっている制度ですので、これが一つの貧困の指標になるかというふうに考えてあります。","voiceIndex":178,"id":"exchange-079"},{"speaker":"南委員","kind":"質問・要望","question":"ということは、受ける対象であっても、受けていない人はいないということなんですか。","respondent":"和氣学務課長","answer":"絶対ないかといえば、いるかもしれませんが、基本的に勧奨して、受けたくないという方もいらっしゃいます。拒否をされる方もいらっしゃいます。もしくは無関心で全く反応していただけない、そういう保護者の方もいらっしゃいます。","voiceIndex":180,"id":"exchange-080"},{"speaker":"南委員","kind":"質問","question":"それで、受給者、認定率ですか、就学援助を、この制度を受けている方は横ばいと、そういう状況の中なんですけれども、一定の時期よりも若干増えてきつつあったのかなと、ちょっとそんなふうに思っているんですけども、今日に至っている小学校、中学校、あわせて２７％という状況は、私は社会的な、一人ひとりのご家庭を取り巻く裏に、どういう経済的な状況、困難な状況があるのか。","respondent":"和氣学務課長","answer":"個々のケース、どういう経済状況かというところまでは、私どもは申請書の範囲内でしかわかりませんので、その裏まではちょっと把握することはできません。","voiceIndex":182,"id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。あわせて、先ほど給食費の問題を伺いたいんですけれども、滞納傾向にある家庭には勧めていると、こういうお話でした。そして滞納しているご家庭には、先ほどの就学援助のことはありましたけれども、どういう働きかけ、なぜ滞納するような状況になっちゃったのかみたいな、そういう原因究明みたいな、そういうところがどの程度行われているのか、そこについても伺いたいと思います。","respondent":"和氣学務課長","answer":"未納についてのお尋ねですけれども、給食費は大体今９億３,０００万円ぐらい徴収しています。その中で、平成２２年度の滞納額は、６９万２,７４７円、未納率にしますと０.０８％、３６名。","voiceIndex":184,"id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点では、私はこの給食費のこういう状況を見たり、就学援助の実態を見たときに、ここに連動しないように、国が国庫補助金を一般財源へと切り替えてしまった、ここに一つの大きな品川区の財政的な負担の状況があるわけですけれども、しかし、教育権を守る、生存権を守るという点で、必要な財源措置はしていただきたい、こういうふうに思うわけですけど。","respondent":"和氣学務課長","answer":"現在、私どもとしまして、保護費が引き下がることに関しての影響のシミュレーションを今やってあります。これも十分シミュレーションしながら、今年度の予算編成に反映をさせていきたいというふうに考えているところです。","voiceIndex":186,"id":"exchange-083"},{"speaker":"南委員","kind":"質問・要望","question":"来年度の予算編成に反映させていきたい、どういうふうに反映させるか、そこが大事なんですけれども、先ほど申し上げたように、生活扶助を引き下げるわけですけれども、それに今までの状況を現状維持だけじゃなくて、もっと拡大する、そういう方向で捉えていただいて、予算化をしていただきたいということをちょっと強くお願いして、時間なので終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-084"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、１６８ページのクラブ・部活動指導費、１７１ページの図書館、それから１７３ページの学校トイレ、１７５ページの就学援助、１７８ページの幼稚園園庭について、可能であれば、指導費に関することを幾つかあわせてお伺いしたいと思います。今は事実上、ネット販売等でも割引が本でも存在するように見えるんですけれども、それについてどのようにお考えでしょうか。この背景について教えてください。","respondent":"和氣学務課長、中元品川図書館長、齋藤庶務課長、立川保育課長","answer":"反応がないというのは、ネグレクトではなくて無視をされてしまうということであって。そのような持ち込みの手間も含めたり、また１０館の図書館が実際買うとなりましたら、本の配送等の手間も含めた価格ですので、この価格で。当面の計画ですが、洋式トイレが５０％以下の学校が７校ありますが、そのうち、御殿山小学校は改築で改修いたしますので。保育者におきましては、そうした要素において、園庭というものを環境構成の一つというふうに考えておりますので。","voiceIndex":190,"id":"exchange-085"},{"speaker":"あべ委員","kind":"質問・要望","question":"公共の図書館については、今非常に全国的に動きが激しいところであると思いますので、今後もぜひそういった動きを捉えていっていただきたいと思います。７校、ぜひできるだけ早く実施をしていただきたいと思います。いつごろというのは時期としては出てこないんでしょうかね、この７校が５０％以下のところが改善されるのは。その辺のところはどのようにお考えでしょうか。","respondent":"齋藤庶務課長、今井制度改革・待機児童対策担当課長","answer":"学校トイレの改築の計画の年次です。平成２４年度浅間台小学校４,０００万円、京陽小学校５,８００万円とかなり多額の経費がかかります。計画的に進めてまいります。平成２７年に移転予定の御殿山幼稚園の園庭、幼稚園では運動場と申しますけれども、この運動場につきましては、学級数に応じた面積基準という形で、委員ご指摘のとおり設計をしております。","voiceIndex":195,"id":"exchange-086"},{"speaker":"あべ委員","kind":"質問","question":"幼稚園にこれから入ろうかと、入園を検討される方に不安のないようにぜひよろしくお願いいたします。それから、どの予算というわけではないんですけれども、土曜授業について、あるいは教育指導費全般についてお伺いしたいんですが、今小中学校の指導要領上の時数と、それから品川区での時数、それぞれ何時間になっているんでしょうか。","respondent":"渋谷指導課長","answer":"年間の時数についてのお問い合わせです。おおむね、今すみません、詳しい数字を出しますが、大体３５時間程度国の学習指導要領よりも多い時数で品川区は小中一貫教育要領をつくっているところです。","voiceIndex":198,"id":"exchange-087"},{"speaker":"あべ委員","kind":"質問","question":"すみません、一緒に聞けばよかったんですが、時間はかなり標準より多いんですけれども、その中で学力の向上はどれだけ図れたという、何か指標になるようなものはあるんでしょうか。ある程度時数が増えれば、テストの結果あるいはいわゆる学力というのがその分は向上するだろうと、それはある程度あるかなと思うんですけど、それ以上に質の向上というのはあるのか、簡単にでいいです。お願いします。","respondent":"渋谷指導課長","answer":"なかなか平均点が単純に上がるかというようなことでの比較は難しいかというふうには思うんですけれども、少なくとも東京都では真ん中程度、また全国の学力平均から上の数字はずっと残しているところであろうかというふうに思います。","voiceIndex":200,"id":"exchange-088"},{"speaker":"あべ委員","kind":"質問","question":"時数の関係上、多少中をはしょりますけれども、今指導向上策の一つとして反転授業というものが注目をされています。今月ですか、佐賀県の武雄市で初めて公教育でも導入すると、導入を決められました。ＩＴとセットではあると思いますが、品川区としてはこの反転授業、どのように捉えられていて、今後については何かお考えがあれば教えてください。","respondent":"渋谷指導課長","answer":"ですから、さまざまな今後の成果などを見ながら、品川区で導入すべきかどうかということについては研究をしてまいりたいというふう思っております。","voiceIndex":202,"id":"exchange-089"},{"speaker":"あべ委員","kind":"意見","question":"指導の放棄も可能なやり方だとは思うんですけれども、その仕組み自体が指導の放棄だとは私は捉えておりませんし、またさまざまな先行研究もそのようにはなっていないかと考えています。ぜひ前向きに検討していただいて、来年度から品川区でもタブレットの導入などを考えていらっしゃると思いますので、積極的に研究をしていただければと思います。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-090"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは１６８ページの教育センター運営費、１７０ページのマイスクール八潮運営費、この２点でお伺いいたします。その中で若干女子中学生が多いように見受けられますけれども、この中学生が多いという実態をどのように捉えていらっしゃいますでしょうか。このスクールに通う児童・生徒の傾向性、背景にある家庭の状況、これはどのように把握をされていますでしょうか。それぞれお答えください。","respondent":"渋谷指導課長","answer":"教育相談センターの心のフリーダイヤルについてお答えをいたします。基本的に夜間、休日というようなものの対応は、区のほうではしていないところです。これは東京都や国のほうの相談窓口等をご紹介しているというようなことです。","voiceIndex":206,"id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"フリーダイヤルのほうですけれども、今のお答えで、都の事業ということで、その相談窓口をご案内している件数が、ご案内があったんですけれども、いわゆる夜間、休日、祝日の対応というのは、平日は人が対応しておりますけれども、この夜間、休日対応は、留守番電話で対応しているというところでありますけれども、この対応もどうかなというふうに私は思っているところもありますし。","respondent":"渋谷指導課長","answer":"今年度新たに設けましたＨＥＡＲＴＳの相談窓口との関連ですが、これは基本的に連絡会等を設けて、ＨＥＡＲＴＳでの相談と、また教育相談センターの相談については連携をとっているところですが、相談窓口が何系統かに分かれているということで。","voiceIndex":208,"id":"exchange-092"},{"speaker":"こんの委員","kind":"質問・要望","question":"フリーダイヤルのほうは連携をして取り組んでくださるというお答えをいただきました。その件について、一言ございましたら、いただきたいと思いますが、お願いします。ですので、ここに行く前の対応としての分析は、そちらのほうの観点からもぜひお願いしたいと思いますが、いかがでしょうか。","respondent":"渋谷指導課長","answer":"そういった学校に対する不信感等々がないような指導をきちっとしていくように、私どもも今後も働きかけは続けてまいりたいというふうに思っております。","voiceIndex":210,"id":"exchange-093"},{"speaker":"藤原委員","kind":"質問・要望","question":"１６８ページ、プラン２１の推進事業だと思うんですが、中学生の海外派遣なんですけれども、総務費でも少しお伺いしましたが、教育委員会側としての考え方についてお伺いしますが、１校１人だと１７人だと思うんですけど、１校３人で５１人、大規模だとクラス１人も行けなくなるんではないかなというちょっと心配があるんですけれども、小規模校と大規模校でも同数がいいと思うんですけれども。","respondent":"齋藤庶務課長、伊崎子育て支援課長、渋谷指導課長","answer":"もう一つ、お金の問題でございまして、後付けで設置をいたしますと、やはり４,０００万円から５,０００万円の費用がかかりますので。ここで、それぞれの特徴と内容、または地域の方たちの連携の方法などをそれぞれどうしているかということが把握でき。来年度以降につきましては、また関係各課とぜひ相談させていただきたいというふうに考えているところです。","voiceIndex":213,"id":"exchange-094"},{"speaker":"藤原委員","kind":"質問・要望","question":"すまいるスクール、すばらしいですね。よくわかりました。だから、昨日、少子化担当大臣がいろいろ自治体がある中で、この区にいらっしゃったんですね。よくわかりました。それで、決算特別委員会に出ていたので、わからないので、どういう感じだったか教えていただけますか。その辺も含めて、答弁いただけますか。","respondent":"伊崎子育て支援課長、鈴木防災課長","answer":"感想をいただいたところですが、学校の中にあるということではあるが、行政と学校が一体的にやっていることへの非常に驚きを持たれていましたと同時に。ただし、災害時に避難所として活用する面から考えれば、委員ご指摘のように空調は入れられなくても、暑さや寒さへの対応等は必要になることは予測できますので、違った方法を用いまして。","voiceIndex":217,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"１６８ページの中学校進路指導費、１７０ページ、教育指導費の中の特別支援教育費、１７３ページ、学校管理費、あと教育全体のお話です。１７３ページの学校管理費の学校環境整備事業でよろしいんでしょうか。その点でこの状況と、そして今後回線を増やすなどの方策はとれないのでしょうか。何か基準があって、一つの学校は何回線とかというふうになっているんでしょうか。","respondent":"齋藤庶務課長","answer":"その際１校から、回線を増やしてほしいというご要望も頂戴いたしましたので、学校の事情を聞きながら、本当にそれだけ必要なのかということも踏まえて、今後対応したいと思います。どの学校に何回線という明確な基準はございません。","voiceIndex":221,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"保護者の方のそういったお電話の状況や学校のほうの事情を勘案して、ぜひ支障のないように、よろしくお願いいたします。では次に、１７０ページの特別支援教育費の介助員等委託費で、その中で、学習支援員のことについてお伺いいたします。そもそも学習支援員という仕組みの基本的な、根本的なというか、位置づけはどのようなものなんでしょうか。","respondent":"渋谷指導課長","answer":"学習支援員についてですが、介助員と学習支援員の違いでご説明さしあげますと、介助員はいわゆる肢体不自由等により、生活に困難のあるお子さんのフォローをするというのが介助員。","voiceIndex":223,"id":"exchange-097"},{"speaker":"高橋委員","kind":"質問・要望","question":"児童の授業参加や学習参加、それを支援していくというふうな基本的な事業だと思います。そこで、平成２４年度の決算ですが、予算とほぼ金額的には変わらないんですけれども、平成２３年度から５００万円近く増えております。この増えた状況の予算、決算、ほぼ同額ですので、そのような状況をご説明いただきたいと思います。","respondent":"渋谷指導課長","answer":"平成２３年度から平成２４年度にかけて予算が増えたのは、平成２３年度の震災の影響で移動教室が平成２４年度に実施されました。そのために、介助員等の委託費を移動教室延期分として上乗せ等々した部分が増えたです。","voiceIndex":225,"id":"exchange-098"},{"speaker":"高橋委員","kind":"質問","question":"実はずらしたということなんですけれども、その５００万円の中の全てがその増えた分というふうに考えてよろしいんでしょうか。それは、配置していただく児童の数との関連もあるのではないかなと思っているんですが、その点とはかかわりはないんでしょうか。","respondent":"渋谷指導課長","answer":"申しわけありません。正確には、今言った、そういった修学旅行とか移動教室、修学旅行は人数が増えたので増やしたんですが、移動教室を延期して増やした分が約２００万円弱で、児童・生徒等の需要が多くなって、純増として増やした分が約３００万円というような内訳です。","voiceIndex":227,"id":"exchange-099"},{"speaker":"高橋委員","kind":"質問・要望","question":"ただ、要望があっても、なかなか全部かなわない部分もあると思うんですが、先ほど根本的な考え方として、児童が授業参加、学習参加をするというところにあると思います。そういった配置を希望したところに認められない場合が出てしまった場合、本人はもちろん、一番本人のためなんですが、それがかなわない、そしてそれについてどのようにお考えでしょうか。","respondent":"渋谷指導課長","answer":"実際、それは学校の努力、指導の工夫でできる範疇なのか、実際支援員が必要なのかということをそれぞれ個別に判断をして、適正な配置をしています。","voiceIndex":229,"id":"exchange-100"},{"speaker":"高橋委員","kind":"確認","question":"個別に判断をされているということです。一つ確認したいんですが、年度途中で、やはり学校で努力してもなかなか厳しい場合に、年度途中から配置をしていただくということは可能なんでしょうか。","respondent":"渋谷指導課長","answer":"学習支援員、介助員の配置については、前期、後期というふうに年間２回の配置をしておりますので、そういう状況を見ながら必要なところに必要な資源を投入するというふうな考え方です。","voiceIndex":231,"id":"exchange-101"},{"speaker":"高橋委員","kind":"質問","question":"ぜひ見直しをしたり、年度途中でも配置をお願いしたいと思います。次に、教育全体なんですが、小学校、中学校の教員の平均年齢のことなんですが、管理職、主幹の先生を除いた先生方の教員の平均年齢は、小学校、中学校、それぞれお幾つで、それぞれ一番平均年齢の若い学校、小学校、中学校、お幾つぐらいかを伺います。","respondent":"渋谷指導課長","answer":"管理職、主幹を除いた平均年齢ですが、小学校は３６.３歳です。中学校が３９.６歳です。最も若いのは、小学校で３１.７歳、中学校で３４.９歳というのが一番若い学校です。","voiceIndex":233,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問","question":"これは３６歳前後の方が多いということではなくて、もっと下の方と、それから上の方で非常に乖離しているということだと思います。その点について、研修以外で学校の中でどのような対応をされて、そういった若いエネルギーがあって、やる気のある先生方の能力を生かす形をとられているのかお伺いします。","respondent":"渋谷指導課長","answer":"団塊の世代の大量退職に伴って、教員の年齢構成が二極化しているというのは非常に大きな問題で、品川区だけの問題じゃなくて、全都的な問題です。そこで、各学校で適切なＯＪＴを進めようというような取り組みをしています。","voiceIndex":235,"id":"exchange-103"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私は、今も質問が出た特別支援教育、就学相談関係、それからまちの人々に学ぶ授業、教育全般についてということでお聞きしたいと思います。教育委員会として品川のお子さんが支援学校に入られたときの、その辺の関係をちょっと確認させてください。殊に、今支援学校のバスが８台出ているというお話を伺っております。それだけに、相当の数のお子さんがいらっしゃる中で、教育委員会の対応を教えてください。","respondent":"渋谷指導課長","answer":"品川区に在住をしていて、特別支援学校に進学された小中学校のお子さんについては、各特別支援学校で副籍という制度の希望調査を行っているところです。","voiceIndex":239,"id":"exchange-104"},{"speaker":"鈴木（真）委員","kind":"質問","question":"交流している状況はわかりました。当然支援学校と副籍を持っている学校の間でもいろんな勉強会、その交流とか、それから先ほどお言葉があったんですけど、就学支援ファイルですか、そういうものを活用してやっていらっしゃると思いますが、副籍、二重に籍を持っているという意味の副籍ですよね。その支援学校から支援学級のほうに移るというようなケースは出てくるものなんでしょうか。","respondent":"渋谷指導課長","answer":"今ぱっと数字は出ないんですけれども、逆に支援学級から学校へというケースは何例かご報告を受けているところですが、支援学校から支援学級にというのはあまりケースとしてはないというふうに認識しております。","voiceIndex":241,"id":"exchange-105"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"よくその辺、やっぱり品川のお子さんの中で、教育委員会として、表現は悪いかもしれないけど、ノータッチになってしまうような形はとってほしくないし、また先ほどの質問の中にありますけれど、品川の中で学校を卒業したら、今度はまた障害者福祉課のほうの担当していただく流れになってくるので、ぜひそういう連携をこれからも保っていっていただきたいということで、それと同時に、支援学級の成果を。","respondent":"渋谷指導課長","answer":"教育センターで行っているんですけれども、その場にそういう業界団体の方においでいただいて、５分ないし１０分時間をとって、その内容等についてご説明いただいて、自分の学校の特色にぜひ生かしたいという校長先生は、そこで手を挙げて、業者とやりとりをして。","voiceIndex":243,"id":"exchange-106"},{"speaker":"鈴木（真）委員","kind":"意見","question":"いろんな大手企業がいっぱい載っていました。その指導課長を以前に３年ほど務めていただいたと思うんですが、教育長、この６日間ずっと座っていて一言もしゃべっていない状況の中で、品川の、昔、以前３年間やっていただいたときと今の状況、そして品川の教育改革、これからの課題、教育長、時間もありますので、一言いただければと思いますので、時間を残しましたので、よろしくお願いします。","respondent":"中島教育長","answer":"６月の第２回定例会でもお話しさせていただいたんですが、今本区では小中一貫教育をベースとした教育活動がそれぞれの学校の特色を踏まえて進められている状況があるなと考えています。","voiceIndex":245,"id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"初めに、このものづくり教育推進事業でありますけれども、初歩的で申しわけないんですが、この設置しようとした理由を教えていただきたいと同時に、このものづくり事業には、これから出ますが、八潮学園と地元の都立高専、また明電舎と小学校、ソニー財団と中学校というふうに聞いておりますけれども、その事業内容というんですか、その辺も教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"もともと八潮学園が八潮中学校と言っていたころから、都立産業技術高等専門学校とさまざまな連携をしていく中で、ものづくりの取り組みというものが始まり、年々それを強化して、しっかりとカリキュラムとして取り組んでやっていこうというふうなことでどんどん発展してきて。","voiceIndex":249,"id":"exchange-108"},{"speaker":"山元委員","kind":"質問・要望","question":"成果報告書のものづくり教育推進事業、そこに小中一貫校１校、６７万２,０００円、これは大体毎年成果報告書に、同じように一貫校と出てくるんですが、これはほとんど八潮学園になっているのでしょうか。それから今おっしゃっていた明電舎とかソニー財団、これは逆にいろんな学校が順繰りというか、ずっと１校じゃなくて順番で事業をやっているのかどうか、その辺も教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"明電舎の取り組みについては、これはお金はかかっておりません。希望する学校を順番に割り振りながら、希望校を調整しながら実施校を決めているというようなことです。ソニー財団については、平成２４年度までの事業で、本年度については実施をしていないところです。","voiceIndex":251,"id":"exchange-109"},{"speaker":"山元委員","kind":"質問","question":"本当に四、五年かかって、八潮学園が交流していて、実を結ぶというか、ある意味、あと３年、４年後ですかね、八潮学園に在学する生徒が特別推薦入試に応募できるということで、これはすごいことだなと思うんですけれども、実際、この入試をきっかけにものづくりに興味を持つ子どもが増えることを願っておりますけれども、今回まだ先の話なのでなかなかはっきりしたことは言えないかもしれませんが、でも。","respondent":"渋谷指導課長","answer":"そういう卒業生の実績等も踏まえて、産業技術高等専門学校のほうから、ぜひ八潮の子どもたちの枠を設けたいという申し入れを受けて実現した制度ですので、これはカリキュラムで連携している、またそういった実績があるということで。","voiceIndex":253,"id":"exchange-110"},{"speaker":"山元委員","kind":"質問・要望","question":"四、五年、今度八潮学園に人が増える、入学生が増えるんではないかなと思います。次に参ります。学習支援ボランティア事業についてお伺いをさせていただきたいと思います。小学校１校、中学校２校、一貫校２校ということでありますが、この事務事業評価には、ボランティアを活用し、児童・生徒の学習向上に努めるとありますけれども、具体的にどんな事業なのか教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"多くは、教育実習等でその学校にかかわった大学生が、ボランティアで引き続きその学校の子どもたちにかかわりたいというご希望のある人に講師をお願いして、ボランティアの謝礼として図書カードをお配りしていると、内容については今ご説明したとおり、国語、算数、数学、英語。","voiceIndex":255,"id":"exchange-111"},{"speaker":"山元委員","kind":"質問","question":"１週間にどのぐらいそういうボランティア活動というか、していただいているのか、その辺もお聞きしたかったんですが、実際やっていただいて、その成果は出ているんでしょうか。","respondent":"渋谷指導課長","answer":"特に教員志望の学生が来ていますので、そういった講師とともにうまく取り組むことによって、子どもの理解が進んだ、基礎・基本の定着を図ることができた等々、それぞれ成果を上げているところです。","voiceIndex":257,"id":"exchange-112"},{"speaker":"山元委員","kind":"質問","question":"１７６ページの健康診断用ＬＥＤ照明灯購入についてお伺いいたします。前年度は調べてみましたら、小学校６校、また中学校４校ということでありますけれども、合計すると小学校が２１校、中学校が７校ということでありますけれども、これで数的に全部なんでしょうか。まだその先に数があるんでしょうか。小学校は３３校ありますけれども、足して２１校。","respondent":"和氣学務課長","answer":"これは一貫校を２校分と数えまして、今５２校中３５校が整備を終わっています。これは来年度、再来年度、計画で全て設置をする計画になってあります。","voiceIndex":259,"id":"exchange-113"},{"speaker":"山元委員","kind":"質問・要望","question":"再来年度とおっしゃらずに、来年度ぜひやっていただきたいと思います。やはり、教室というか、保健室というか、歯科健診等はやっぱり普通の電気だと薄暗いというふうに聞いております。そういう意味では、やはり間違いが起きてはいけないので、ぜひ早い段階で全部の学校にＬＥＤを使っていただきたいと思います。いかがでしょう。","respondent":"和氣学務課長","answer":"歯科健診、委員おっしゃるように歯科健診用のＬＥＤで、最近歯の治療の状態がすごく見づらいということで入れているものですが、早急に入れたいと思いますが、予算のあることですので、順次やっていきたいというふうに考えてあります。","voiceIndex":261,"id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は１６９ページのいじめ問題についてお伺いしたいと思います。昨年９月、区立中学校の男子生徒がいじめを苦に自殺をした事件から１年が経ちました。事実であれば、なぜなのかを伺いたいと思います。私は子どもの命がいじめによって失われるというこの重大な事態となったわけですから、二度と繰り返さないために、全ての教員が教訓として学ぶことが最も大事だと思いますけれども、いかがでしょうか。","respondent":"渋谷指導課長","answer":"マスコミ等にも情報公開請求をいただいて、公開して、オープンになっているものですので、先生方にもそういったものを活用しながら、しっかりといじめ根絶に向けて取り組んでもらえるようなことを考えているところです。","voiceIndex":264,"id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この報告書が出されて既に１年近くが経つわけですから、私はこれをぜひとも、せめて学校現場では見られるようにしていただきたいということと、全教員がこれを教訓として学べるように、そういう取り組みをぜひしていただきたいと思いますけれども、いかがでしょうか。そして、私は大津の提言を改めて読ませていただきまして、学ぶことが多いなというふうに思いました。","respondent":"渋谷指導課長","answer":"それから２点目、学校への提言、逃げる、真正面から向かう、これも当たり前のことで、品川区全ての学校がそういう姿勢で取り組んでいるというふうに断言できると思います。","voiceIndex":266,"id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"取り組んで解決をぜひともここでもしていただきたいと思いますし、解決をした事例について、課題と教訓というのをまとめて明らかにして、私は教員がいじめの対応についてどう対応していったらいいのかということを学ぶ研修に生かす取り組みをぜひしていっていただきたいと思うんですけれども、いかがでしょうか。","respondent":"渋谷指導課長","answer":"解決事例に学ぶにつきましては、個別の事例でいじめられている子、いじめている子、個人情報への配慮ということは最大限に考えながらも、それぞれの事例について情報交換してというふうな取り組みは、生活指導主任会等を通じて既に取り組んでいるところです。","voiceIndex":268,"id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは養護教諭の先生が一人ひとりの子どもたちに配慮された対応をされているということも本当にあるんじゃないかと思うんですけど、そういうところで安心できる場をつくるというのは、子どもたちにとって本当に大事なことだと思うんですけど、そういうところで、養護教諭の先生も、私は生徒数の多いところは複数配置、こういうことで検討すべきではないかと思いますけども、いかがでしょうか。","respondent":"渋谷指導課長","answer":"学校の先生が忙しいからというふうな部分で、安易に人を増やすということは考えずに、まず自分たちで組織的に何ができるのか、何をやらなきゃいけないのか、何が優先順位で大切なのか、そんなことを考えながら取り組ませていきたいというふうに思います。","voiceIndex":270,"id":"exchange-118"},{"speaker":"原委員","kind":"意見","question":"初めに、１６７ページ、基金の積立金、この積立金について、区としてどういうようなお考えがあるかどうかということを簡単で結構なので、お話しいただければと思います。それから、その次が教職員の人材育成に関しましては、どんな人材教育をして研修をしているのかということをお教えいただければと思います。","respondent":"渋谷指導課長、本城企画財政課長、中元品川図書館長","answer":"必修研修としては、初任者研修、２年次、３年次研修、４年次研修といった若手研修、それから、１０年経験者研修。今後も将来の改築需要等を見据えまして、可能な限り計画的に基金を積み立て、今後の改築需要等に適切に対応していきたいと考えているところです。外国から編入学した小中学生で日常会話に不自由を感じるというレベルの子に３カ月程度指導するケースと。次のページですが、図書館の窓口業務委託等という項目があります、そちらはやはり４億３,７００万円余ということで。","voiceIndex":275,"id":"exchange-119"},{"speaker":"原委員","kind":"質問","question":"もう１点お聞きしたいのは、丁寧に説明していただいたんですけど、ちょっと校長先生の話がなかったものですから、校長研修、これが出席率、データがあるかないかわかりませんけど、出席率がどのぐらいなのかなというところのお話と、それからあと国際理解教育の中の、これも大体把握しました。２点というのは、先ほど言ったように校長先生の研修の件と、それから国際化の件です。よろしくお願いします。","respondent":"渋谷指導課長","answer":"積極的に使える英語が身につけるよう、コミュニケーションがとれる児童・生徒の育成を図っていきたいというふうに考えているところです。","voiceIndex":280,"id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、このようないわゆる長期間というんですかね、すぐに解決ができない、できていない、このような事例というのは過去にあったのかどうか、わかればお知らせいただきたいし、そのときはどのような対応が、特に学校、警察になると思うんですが、どうだったのかというのを、どのように解決できたのかというのを参考事例であれば教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"実際、警察の対応はどうなのかですが、パトロールをお願いするのはもちろんなんですけれども、今年度よりＨＥＡＲＴＳに警察ＯＢの方に配置していただいております。","voiceIndex":286,"id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"それで、先生と話しましたら、まもるっちのひとつ使い方について、もう一回、再徹底というんですかね、したほうがいいのかなというふうに感じたところがありましたので、ちょっとお話をします。その次に、今のご様子ですと、そうすると、家に帰ってから親に話すというパターンがすごく多いんです、というお話も先生からお聞きしました。そういうことも含めて、お願いいたします。","respondent":"渋谷指導課長、上垣外生活安全担当課長","answer":"まもるっちを導入したときに、どういうような処置のさせ方をするのかという議論があって、やはり今委員がご指摘になったとおり瞬時に引けるようにということで、かばんにつけるのではなく、首からぶら下げて即座に引くと。この点につきましては、セーフティー教室等に集まっていただいた保護者等を中心に、こういう事案についてはすぐ引くように、あるいはこういうところに注意してふだん持つようにという形で指導しているところであります。","voiceIndex":288,"id":"exchange-122"},{"speaker":"若林委員","kind":"意見","question":"最後のところですけれども、協力者、それからいわゆる協力者になっていない、協力者というのは１万二、三千人いらっしゃいますね。大体親御さんが多い。そうじゃなくて、協力者になっていない地域の方々という意味ですので、もう一言お願いいたします。","respondent":"上垣外生活安全担当課長","answer":"このシステムの協力者のみならず、この地域にお住まいになっていらっしゃる方の協力者、例えば子ども１１０番の家だとか、８３運動の方にもご協力をいただいて、区全体で子どもたちに対する見守りをしているところであります。","voiceIndex":291,"id":"exchange-123"},{"speaker":"須藤委員","kind":"質問","question":"鈴木（真）委員の質問で、教育長のお考え、学校が元気でなければというお話を伺いました。子どもも元気でなければ。そして、先ほど来、学校が元気に、あるいは子どもが元気にということの中で、教員の心得というのは、どういう心得を指導しているんでしょうか。教育の中で一番大切なことというのは、どういうことを子どもたちに指導していくということをお考えでしょうか。","respondent":"渋谷指導課長","answer":"やらされたり、その場しのぎでというふうな意識ではなくて、品川の子どもを愛して、みずから積極的に教育に熱い熱意を持って取り組んでいく、そういう教員にしていくために、さまざまな制度の中に手をつけて、先生方がそうせざるを得ないような環境、仕組みをつくって。","voiceIndex":294,"id":"exchange-124"},{"speaker":"須藤委員","kind":"質問・要望","question":"今日の新聞で、日本人は成人力というのが世界で一番だというようなことだって、日本の教育というのは、本当に水準的にはすばらしいものがあると思うんだけど、その中で、品川区がやはりこれだけプラン２１という形で打ち出している、そうすると、そのお子さんたちがいじめもない、いわゆる徳性をしっかり涵養されたお子さんに育っているよというのが一番必要だろうと思うんですけれども。","respondent":"渋谷指導課長","answer":"国が今道徳の教科化等々に取り組んでおりますが、単なる理念だけではなくて、しっかりとした心根を、それを実際行動に移すことができる、実学としての市民科、そういったものに品川区は全区で取り組んで、品川区の子どもたちの徳性をますます磨き上げるように。","voiceIndex":296,"id":"exchange-125"},{"speaker":"須藤委員","kind":"質問・要望","question":"やはり子どもというのは親の背中を見て育つという話があるように、学校へ来て、先生方の行動を見ているだろう。それから、同じく、１６７ページで、区教員の給与費に関連して、区固有教員が１２名いらっしゃいますけども、区固有という方は、区内に在住されているんでしょうか。それとも、区外から来ていても、区固有の職員というような形になってきているんでしょうか。そのあたりを聞かせてください。","respondent":"渋谷指導課長","answer":"在住はちょっとわからないんですけど、私が知っている何人かは区内在住の人間はおりますが、ちょっと人数は後ほどまたご報告させていただきたいと思います。","voiceIndex":298,"id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"区外でも構わないんだけど、いわゆる品川区を本当によく知ってくれて、なお区に住んでいてくれれば、もっといろんな面で応対ができるなと思ったのでちょっとお聞きしました。前に、やっぱり採択のときに我々がこういう教科書というような形で応対をしたことがあったんだけど、なかなかそのとおりにならなかったんだけども、そのあたりをちょっと教えてください。","respondent":"渋谷指導課長","answer":"教科書採択につきまして、特別支援学級で使う教科書については、その子その子の特性に応じた教科書がその年度ごとに必要になってくるような関係がありますので、毎年採択をしているというようなことです。","voiceIndex":300,"id":"exchange-127"},{"speaker":"須藤委員","kind":"意見","question":"一般の教育のときには、何年に１回という仕組みになってくるんだけど、前回はちょっと急にいろんなことを我々教育委員会にお話をしたんだけども、これからそういうことも一つ考えておいてもらいたいなと思うんですが、一つ、日本の地図なんかで、今竹島とか尖閣とか北方領土、いろいろあるんだけど、そういう地図なんかはきちんと今の教科書はされているのかどうかということをちょっと聞かせてください。","respondent":"渋谷指導課長","answer":"基本的に教科書採択に供される教科書につきまして、小中学校で、今現在品川で使っている教科書については、領土の問題等について、きちっと検定を通って記述されているものを品川区では使っております。ちなみに、来年度に多分教科書、小学校の教科書採択が行われる予定です。","voiceIndex":302,"id":"exchange-128"},{"speaker":"須藤委員","kind":"質問・要望","question":"我々もまた政調会で整理をして、いろんなことをお話しさせていただきたいと思っていますけれども、やはりお子さんたちが自信を持ってこの国をそしてこの区をと誇れるような形で、指導できる仕組みをさらに研鑽していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-129"},{"speaker":"飯沼委員","kind":"質問","question":"成果報告書の１６９ページ、区学力定着度調査、全国学力・学習状況調査、学力テスト実施、この３点、約３,３４０万円程度、決算になっていますけれども、小中学校、児童・生徒が受けている学力テストの内容と学年全てを教えてください。","respondent":"渋谷指導課長","answer":"学力調査についてのご質問です。学力調査は大きく国、都、それから区、それから学校が独自で行っているもの、大きく分けると４種類実施しております。悉皆で行っているまず国の調査ですが、国の調査につきましては、小学校６年生と９年生がそれぞれ対象になっております。","voiceIndex":306,"id":"exchange-130"},{"speaker":"飯沼委員","kind":"質問・要望","question":"たくさんありがとうあります。学力テスト実施の１,５００万円余のところには、今５年生から９年生までの中間とか期末とか、その部分は含まれているのかいないのか、ちょっとその辺、後で教えていただきたいと思います。決算のところで、委託の部分があればどれなのか、どこに委託をしているのか教えていただきたいのと、独自テストを取り入れている理由をお聞かせください。","respondent":"渋谷指導課長","answer":"委託につきましては、全国学力調査の採点委託で４３０万５,４３０円、それから、区独自の学力定着度調査の問題作成等の委託経費として１,３７６万５,５００円を計上しています。","voiceIndex":308,"id":"exchange-131"},{"speaker":"飯沼委員","kind":"質問","question":"委託先はどこかとお伺いしたんで、わかったら教えてください。","respondent":"渋谷指導課長","answer":"委託先は、国の学力調査につきましては、東京書籍株式会社、区の学力調査につきましては、現在は学研教育みらいに委託をしています。","voiceIndex":310,"id":"exchange-132"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと時間がないので、全国一斉学力テストについてお伺いをしますけれども、テストが終わった後の公表、活用の仕方をお伺いしたいんですが、例えば学校に対して、児童・生徒に対して、保護者の皆さんに対してというところで、どういうふうな返し方をしているのかということと、テストの後、公表までどのくらい時間がかかっているのかも教えてください。","respondent":"渋谷指導課長","answer":"都については、自校採点ですので、すぐに回答が得られる。それから区の学力調査については、２月末に実施して、３月の中旬には結果をお返ししていると、そういう状況です。","voiceIndex":316,"id":"exchange-133"},{"speaker":"飯沼委員","kind":"質問","question":"特に全国一斉学力テストのところなんですが、要領によると、返ってきたものをその後に生かし、改善につなげるようにと書いてあるわけですけれども、実際的に子どもたちに言うと３カ月も４カ月も経っちゃうと、すっかり忘れていて、対策してもなかなか有効にできないということをお伺いしたんですけれども、２００４年に復活をしました全国一斉学力テストなんですが。","respondent":"渋谷指導課長","answer":"学力調査のそもそもの目的につきましては、他の自治体と比べたり、順位を競うものではないというふうな認識です。品川区の場合は、あくまでも区独自の学力定着度をベースに授業改善を図ったり、学校経営の改善を図ったりということで進めているところです。","voiceIndex":318,"id":"exchange-134"},{"speaker":"飯沼委員","kind":"質問・要望","question":"テストで点数がとれるお子さんはいいんですが、なかなか追いついていかないお子さんというのは大変つらいものがあると思っています。自己肯定感がなかなか築けない、傷ついてしまう、こういった意味では、テストではなくて、わかる授業をつくっていただきたい、これを願っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"私は１６７ページ、教育総務費とそれから教育指導費、全般にわたってお聞きしたいと思います。この理由ですが、これは教員管理職を育成する教育体制が品川区ではしっかりできていないからですか。それとも、区の教育は問題点や不安が相変わらず多いために、教員としてよい人材が来ないために、教員を指導する管理職が必要なんでしょうか、その辺についてちょっとご見解をお聞かせください。","respondent":"渋谷指導課長","answer":"再任用についてですが、再任用をお願いする校長先生については、教育的な識見に優れた方を面接して、１年ごとの更新をお願いしています。決して足りないだとか、力がないだとか、そういうようなご指摘には当たらないというふうに考えております。","voiceIndex":322,"id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"それが品川区は１年ごとに更新ということですが、何年もやっていますよね。これはおかしくないですか、普通に。ということは、品川区の管理職、校長先生も育たないということですか。その辺についてちょっとご見解をお聞かせください。","respondent":"渋谷指導課長","answer":"委員の言う一般的な認識とか常識とかということ自体が違っているんだというふうに思っております。今学校の教育現場、特に小学校は管理職が非常に足りません。","voiceIndex":324,"id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"今そう言われましたが、本当でしょうかね。それは何ですか、今全国的にというお話も確かにありました。みんな違うでしょう。それが品川区の場合は、そういう古い体制の方がいつまでも残っていて、古い体制の仕組みで改革、改革とプラン２１を１３年間もやっています。ほとんど改革できないから、いつまでも、だから、ずっと改革、改革と続けるんですか、その辺についてご見解をお聞かせください。","respondent":"渋谷指導課長","answer":"毎年１３年間も教育改革をしているというふうにおっしゃいますが、どういう取り組みでも、常により良くしようとして改善を図っていくのは、これはどんな一般企業でも、どんな社会でもそういうふうに常に改善、改善を図っていくのは当然のことだというふうに考えます。","voiceIndex":326,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"品川区の改革ということでね。それとあと、再任用については、１年、または長くても２年というのはわかります。でも、それ以上続くというのは、やはり品川区に何か教育、全都的にとおっしゃいますけど、その辺はしっかり反省すべき点じゃないですか。これは何を意味するんですか。そして、何のために実施しようとしているのか、もしご見解がわかればお聞かせください。","respondent":"渋谷指導課長","answer":"他の自治体の学力公表の意図については、申しわけないですけども、コメントすることはできません。","voiceIndex":328,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"何で公表しないのか、学力が追いつかない子が多いからじゃないですか。私は先だって、区内の公立中学校、中学３年生にちょっとお話を聞きました。中学３年生、受験ですよね。単願推薦はもうすぐ始まります。１年生の数学でした。どうしたの、先生に聞けばいいじゃない。現実学校というのは、学力を子どもたちに身につけさせるためにあるんじゃないですか。こういうことに対して、どのようにお考えですか。","respondent":"渋谷指導課長","answer":"そういった子どもに対して必要最低限、本会議でもご答弁申し上げましたとおり、学習指導要領、小中一貫教育要領で示された指導事項について、いかにしっかり身につけさせるのか、それが大きな問題で、そのことに教育委員会としては全力で取り組んでいる。","voiceIndex":330,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"改革をやって１３年ですよね、１３年やって、子どもは毎年卒業していくんですよ。ご自分のもしお子さんなら、やっぱり気がつきたいですよね、家族でも、本人も。ところが、じゃあ本人の成績に対して、あなた、このままいったら大変よ、高校受験もできない、高校も入れないよという仕組みは学校にあるんですか。もしあったら教えてください。そういう指導をやっているんですか。","respondent":"渋谷指導課長","answer":"そういったそれぞれの特性に応じて、人間は学力だけではありませんので、どういうような生き方をしていくのが大事なのか、その子に適しているのか。そういうことを見つけていく指導が、進路指導ということだというふうに考えております。","voiceIndex":332,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"それじゃあ何を指導していると思えばいいんですか。ところが、その前に、芽を摘まれちゃうんじゃないですか。これは情けないことじゃないんですか、教育行政として。いつまでたっても３割の子は公立中学校に来ない。一生懸命やっても、実績はどうなんですか。そういうことを考えたら、親が何で離れていっちゃうか、そういうことも考えなきゃいけないんじゃないですか。ちょっとご見解をお聞かせください。","respondent":"渋谷指導課長","answer":"そういう子どもたちを１人でも少なくするように、公教育の部分でどうにかきちっとした学力が身につけさせられるように、例えば習熟度別学習を取り入れたりだとか、さまざまな工夫をしたり、また区として非常勤講師を配置して。","voiceIndex":334,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"お金が毎年１００万円ですよ。１００万円かけて行かせる、これは大変ですよ。その辺は考えてほしい。今違いますよ。習熟度に行って、じゃあこちら習熟度で１０人、２０人でやっていました。補習をやっているということはどういうことですか。そんな中で、私は教育委員会として、やはり少なくても教育、学習指導だけはしっかりやってほしいんですが、その辺についてもしご見解があればお聞かせください。","respondent":"渋谷指導課長","answer":"委員の習熟度別学習のご理解が全く違っているので確認をさせていただきたいと思います。習熟度別学習と少人数指導は全く別物です。品川区で取り組んでいる習熟度別学習は、基本的には２学級を三つのグループに分けて、それぞれの学びの状況に応じて実施しています。","voiceIndex":336,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"でも、私は現実を見てほしい。現実、それで成績が上がっている、どうなのか。この子たちはできているのか。そういうのを僕はしっかり見てほしい。現実に中学３年生になったら、ほとんど大半の子が民間の塾に行っているんですよ。だけど、何でこういうことを調べないんですか。私はちゃんと実態を、教育の実態を公表すべきだと思うんですが、それについて、お時間ありますからご見解をお聞かせください。","respondent":"渋谷指導課長","answer":"必ずしも公立学校の否定で塾に行っているというふうな捉え方はしておりません。それぞれ必要に応じて、英会話を勉強したり、習字を勉強したりするのと同様に、必要な子が学習塾に行くということはしごく当然な行動だというふうに認識しております。","voiceIndex":338,"id":"exchange-144"},{"speaker":"井上委員","kind":"質問・要望","question":"私からは、１６７ページの教育指導費、１７１ページの介助員等委託費、１７４ページの学校管理費からお伺いをいたします。プラン２１の検証についてお伺いをしたいと思います。ですから、そういった意味でも、学校が最適である、こんなに努力をしているんだという大人の発想と、そこで学んだ子どもたちとどんなふうに違うのかということをまず理解する必要があるというふうに思います。","respondent":"渋谷指導課長","answer":"教育改革の評価については、今さまざま検討しています。","voiceIndex":341,"id":"exchange-145"},{"speaker":"井上委員","kind":"質問・要望","question":"こういったプラン２１が始まるときに、一貫校では体格差のある子どもたちが一緒で大丈夫かということとか、小規模で周りの学校と格差を感じることはないのかと、そういった疑問とか不安とか、今でも課題はあると思いますけれども、そこを卒業した子どもたち自身がどういうふうに感じたのかということをまずは検証した上でこれからに生かしていただきたいということは、お金の問題ではなく。","respondent":"渋谷指導課長","answer":"平成２４年度のまず通常級の配置している介助員ですが、平成２４年度、前期と後期と数字が異なりますが、まず平成２４年度の前期、小学校へ介助員として配置している人数は３９名です、学習支援員として配置したのが６０名。","voiceIndex":343,"id":"exchange-146"},{"speaker":"井上委員","kind":"質問","question":"それで、品川区のインクルーシブ教育の考え方をお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"発達障害を含む障害のある児童・生徒一人ひとりの能力を最大限に伸長するために、多様な教育を展開して、社会的自立を図ることのできる力を地域の一員として生きていける力をつけて、共生社会の実現、そういったものに寄与するような教育を図っていく。","voiceIndex":345,"id":"exchange-147"},{"speaker":"井上委員","kind":"質問","question":"私は障害のあるなしにかかわらず、在籍しているクラスがその子の居場所だというふうに思っています。その子の存在がクラスで認められた教育が行われているのかどうか。例えば、普通学級のほうで学んでいるお子さんがそろそろクラス替えしたらどうですかとか、お子さんにはここよりあちらのほうがいいですよとか、そういったことを言っていないでしょうか。現状をお聞かせください。","respondent":"渋谷指導課長","answer":"細かな指導が実際行われたどうかという個別の事例については認識をしていないですが、基本的にはその子どもの発育状況に応じて、最も適した教育環境がいいだろうということで、その子どもにとって何が一番重要なのかという視点で教員はかかわっているというふうに考えております。","voiceIndex":347,"id":"exchange-148"},{"speaker":"井上委員","kind":"質問","question":"学習支援とか、その子どもがそこのクラスにいるということに対して、周りのお子さんとの関係、それからサポート、そういったことが介助員制度だとか学習支援員とか、そういった方たちでサポートされるということが基本だというふうに思うんですが、そこで基本的に教育を受けることについて本人と保護者の意思が尊重されるということについて、どのように区教委はお考えでしょうか。","respondent":"渋谷指導課長","answer":"教育を受けることについて、本人、保護者の意向が最大限尊重されるということは、間違いのないことだというふうに思っております。","voiceIndex":349,"id":"exchange-149"},{"speaker":"井上委員","kind":"質問・要望","question":"障害というキーワードではなくて、全ての子どもに対しても教師の言動は影響力があるということがそこから見えてくると思いますが、そういった研修のお考えはいかがでしょうか。","respondent":"渋谷指導課長","answer":"したがいまして、そういった一人ひとりの子どもを大切にするような人権研修だったり、そういう障害者理解を進めるような研修等々については、今後も今以上に充実させてまいりたいというふうに思っております。","voiceIndex":351,"id":"exchange-150"},{"speaker":"井上委員","kind":"質問・要望","question":"学校の防犯カメラについてお伺いをいたします。学校の防犯カメラの運営経費がちょっとどこに計上されているのかわからないので、そのことで、あとは品川区全体ではどのくらいの支出があるのかお伺いをいたします。防犯カメラの耐用年数、２００６年に設置が始まっているかと思うんですけれども、耐用年数はどのくらいなのでしょうか。","respondent":"齋藤庶務課長","answer":"設置台数ですけれども、必ず１校５台から６台、一貫校の大規模なものになりますと、死角、デッドスペースが増えてまいりますので、２０台、２１台ございまして、全て職員室で集中管理ができるようになっております。","voiceIndex":353,"id":"exchange-151"},{"speaker":"井上委員","kind":"質問","question":"今そこで、品川区の学校で各校５、６台、小中一貫校では２０台ということでしたけれども、全体で言うと、品川区の学校の設置台数は何台なのでしょうか。それから、今５年から１０年ということで、７年ぐらい経ちました。それで、小中一貫校、デッドスペース、そういったエリアがあるということで、全ての小中一貫校が２０台ぐらいなのか、その辺も詳しく教えてください。","respondent":"齋藤庶務課長","answer":"各学校で何台というのは、今から全部申し上げられますけども、全体でというのは、ごめんなさい、合計、後ろで今足し上げさせていますので、少々お待ちください。それで、全校で２０台ということ……。","voiceIndex":355,"id":"exchange-152"},{"speaker":"井上委員","kind":"質問","question":"どうして一貫校で２０台もつけなくちゃいけないのかというところで、「学校防犯カメラシステムの管理および運用に関する要綱」ということで、第４条に「防犯カメラは学校の敷地内で犯罪被害防止の効果が高いと思われる場所に設置するものとする」と。そういった中で、そんなに危険なところがいっぱい一貫校にはあるということですか。","respondent":"齋藤庶務課長","answer":"一貫校は大規模な施設ですので、死角、そして子どもたちの安全を守るということで設置しておりまして、校則違反を監視するということでは一切使ってございませんので、子どもの安全のためだということをご認識いただきたいと思います。","voiceIndex":359,"id":"exchange-153"},{"speaker":"井上委員","kind":"質問","question":"画像の扱いは慎重にしなければならないということも要綱では定められておりまして、そのとおりだと思います。設置以降、画像を視聴したことが何回かありましたでしょうか。その実績、幼稚園でも防犯カメラをつけていると思いますけれども、その辺はいかがでしょうか。","respondent":"齋藤庶務課長、立川保育課長","answer":"外部にお出しする場合は、公文書で警察からご要望があった場合に限定されております。昨年度も２件ほどございました。幼稚園ではそうした防犯カメラによる映像が必要で、確認が必要であるというようなことは１件もありませんでした。先ほど答弁漏れがございました。小学校、中学校、一貫校、全部で３２６台です。","voiceIndex":361,"id":"exchange-154"},{"speaker":"井上委員","kind":"質問","question":"設置のときには、都の補助金がありましたけれども、設置以降の維持管理費について、その補助金があるのかということと、耐用年数１０年、あともう少しで、徐々にだとは思いますけれども、換わってきます。全部の３２６台を区費で換えていくのか、それとも何らかの形の方針が出されているのか、そのことについて教えてください。","respondent":"齋藤庶務課長","answer":"更新についての補助金はございません。子どもの安全を守る設備ですので、計画的に必要なものを改修してまいります。","voiceIndex":365,"id":"exchange-155"},{"speaker":"井上委員","kind":"質問・要望","question":"防犯カメラについて、幸いにして品川区は外部からの犯罪という事態で画像を２件聴取したということではないというふうに思いますので、子どもたちにとって、中のそういったところで、防犯カメラが視聴されているという事例だったというふうに思いますけれども、ぜひそういったものも抑止力としてはなるかというふうに思いますけれども、子どもたちがともに学べる環境整備というところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":367,"id":"exchange-156"},{"speaker":"浅野委員","kind":"確認","question":"最初に、パソコン等借料、教材教具ですけれども、これも総務費で質問させていただきましたけれども、WindowsXP、Office2003の更新時期が来年の４月ということですが、今現在きっちりやられていると思いますが、進捗状況、これを確認しておきたいと思います。","respondent":"和氣学務課長","answer":"Windowsの対応ですが、平成２３年度に半分、今年度に半分終わりましたので、全てが対応できてあります。","voiceIndex":369,"id":"exchange-157"},{"speaker":"浅野委員","kind":"質問","question":"９時からということになりますと、もっと早くしてほしいと、こういう意見も私のところにも多々届いておりまして、同じ働いている事情ということであれば、やはりもうちょっと前から行えないのかというところを一つお伺いしたいと思います。学童のときも早目に始まっていたというふうにも聞いておりますので、この対応の方法等についても教えていただければと思います。","respondent":"伊崎子育て支援課長","answer":"すまいるスクールの開設時間です。すまいるスクールは、学校の中にある施設ということがありますので、開設時間のほうは９時からということで、学童保育のときとは違う考えでやらせていただいております。","voiceIndex":371,"id":"exchange-158"},{"speaker":"浅野委員","kind":"質問","question":"各学校でも小中学校特別支援学級、こちらの防災行動マニュアル、こちらのほうに展開をしていくというふうにも伺っておりますので、こちらのほうの展開状況、またこれに基づいて学校ごとに防災訓練が一度でも行われたのかどうか等について教えていただければと思います。","respondent":"齋藤庶務課長、渋谷指導課長","answer":"具体的に申し上げますと、今学校避難所運営マニュアルにつきましても、今年度末中には策定する方向で防災課が主体的に働きかけておりまして、幾つかＰＴもできておりますので、そのＰＴの進行状況に合わせながら、学校にも情報提供し。例えば、具体的には小学校で２０校が津波等の高所避難をするとか、中学校９校中５校が自校の屋上にきちっと避難をするとか、小学校１７校で合同避難訓練を実施する、また津波の想定をした避難訓練を実施する等。","voiceIndex":373,"id":"exchange-159"},{"speaker":"浅野委員","kind":"質問・要望","question":"子どもの学校生活での安全ということも踏まえまして、しっかりと、答弁はなかったんですけれども、防災訓練、学校でのそれぞれの防災訓練ですか、そちらのほうもしっかりと行うことを前提として、これからも取り組んでいっていただきたいと思います。このサイバー補導という、これを試行している、試しに行っているということですが、これについて教育委員会としてはどのように認識をされているんでしょうか。","respondent":"渋谷指導課長","answer":"昨年度の実績で言いますと、不適切な書き込み等１万１,０５７件を確認していて、そのうち品川区の学校に関係するものが２件ございまして、東京都から連絡を受けて、該当する学校に伝え、それぞれの学校で適切に指導していただいたと、そういう取り組みを続けております。","voiceIndex":376,"id":"exchange-160"},{"speaker":"浅野委員","kind":"質問","question":"サイバー補導という観点からいいますと、ネット上の掲示板に下着の買い取りを持ちかけるようなことなんかを監視して、書き込んだ児童と報道ではなっておりますけれども、小学生ということなんでしょうか、私もちょっと信じられなかったんですけれども、下着を販売しますみたいな、お小遣い稼ぎの感覚でやっているというのがあって、そういうのを早目に発見して、そして被害に遭うのを防ぐと。","respondent":"渋谷指導課長","answer":"積極的な情報提供をしてまいりたいというふうに思っております。","voiceIndex":378,"id":"exchange-161"},{"speaker":"本多委員","kind":"質問","question":"１６９ページの特色ある教育活動について、二つ目は１６７ページの教育指導費、１７５ページの学校給食費について、三つ目が１６９ページ、１７１ページの教材教具購入について、三つほどお聞きします。これはやっぱり性質があるのかなと思うんですが、その辺についていかがお考えでしょうか。","respondent":"渋谷指導課長","answer":"今現在全校で実施している小学校英語につきましても、城南小学校、小山台小学校を国際理解教育推進校というような形のモデル校として指定して、今現在は全区展開をしているというようなことです。","voiceIndex":381,"id":"exchange-162"},{"speaker":"本多委員","kind":"質問・要望","question":"特に何か垣根がないんだなというのがわかりました。いいことはいいことで、広めていっていただきたい。ちょっと素朴に聞かせていただきました。２点目なんですけれども、学校と家庭の連携推進事業ですね。この特色ある活動の中の一つで、学校と家庭の連携推進事業、小中一貫校となっているんですけれども、この辺の成果ですとか、ならびに課題について、どのように捉えているか教えてください。","respondent":"渋谷指導課長","answer":"八潮学園に配置している都費のスクールカウンセラーをスーパーバイザーとして、どのような対応をしていったらいいのかということをその都度アドバイスを受けながら、学校復帰を目指していくというような、そういった事業で一定の成果が上がっているというふうに考えております。","voiceIndex":383,"id":"exchange-163"},{"speaker":"本多委員","kind":"質問","question":"教育委員会の基本方針で打ち出されているのは、学校、家庭、地域が責任と役割を持って連携していくというのが基本方針で打ち出されているんですけれども、毎月第１日曜日は家庭の日というふうに区は位置づけがあると思うんですが、こういうのというのは何か生かされているんでしょうか。難しいことを聞いてすみません。","respondent":"福島青少年育成課長","answer":"家庭の日のことですけれども、毎月第１日曜日は家庭の日ということで、家族で時間を過ごしていただくということで、啓発活動を行っているところです。この家庭の日自体は、今から３９年前に制定されたもので、広く品川区内に広めているところです。","voiceIndex":385,"id":"exchange-164"},{"speaker":"本多委員","kind":"質問・要望","question":"次の質問にいきます。それが、１,３００年も続いている。古いようで新しいエコロジーとリサイクルというようなことがやはり日本人の心の中にありますので、そういった環境教育の、昔から取り組んでいるというんでしょうか、歴史的なものもあわせて環境教育のお知らせとか指導をしていただければと思うんですが、まずその環境教育への成果をお聞かせください。","respondent":"渋谷指導課長、野呂瀬環境課長","answer":"平成２１年度は小学校のみの取り組みでございましたが、平成２２年度からは中学校まで拡大して、品川区全ての小中学校で、６月５日の環境の日を中心にして、６月中の１週間。あわせまして、昨年度、品川区環境計画というのを策定いたしました。その中で、これから環境教育、いわゆる学校とも連携をとっていくとうたってありますので、今後充実させていきたいと思っているところです。","voiceIndex":387,"id":"exchange-165"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に一つ聞きたいのが、教材教具の購入のところで、教科書以外の教材、生徒一人ひとりが自分のものになっていないものがあると思うんですけれども、そういったものへの次年度への予算編成ですとか、あと教育費の不用額が６億５,０００万円以上あるんですけれども、こういったものの流用とかができないのか、すみません、時間がなくて、お願いします。","respondent":"和氣学務課長","answer":"基本的に今教材教具について学校から不足しているという声は聞いてございませんので、それなりに潤沢に整備できているというふうに考えているところです。","voiceIndex":390,"id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1382#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":118224,"voices":392}},{"id":"h25-20131016-4","meetingId":"h25-c-settlement","date":"2013年10月16日","dateIso":"2013-10-16","committee":"決算特別委員会","time":"午後 １時００分～午後 ６時４４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を100件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"私は、自民党を代表いたしまして、総括質疑を、本多委員とともに取り上げします。テーマは、都市型観光についてをメインに、各施策を伺ってまいります。そういった中で、品川区が観光施策に取り組む、その施策の意義、そして期待される効果、これをまず伺いたいと思います。","respondent":"中川原地域振興事業部長","answer":"もう一つは、我がまちの持つ魅力を再発見し、外からの観光客に評価されることで、まちのポテンシャルが上がる、住んでいる住民の住民意識が向上するという、その点が大きくあると考えております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"今、施策の意義と効果をいろいろ伺いました。そういった意味で、品川区は大変広いという観点から、エリア分けの取り組み、あるいは、企業で働いている方を含めた昼間人口、あるいは、居住者の地域の特性がいろいろあるかと思いますが、そういったエリア分けの取り組みについて、伺いたいと思います。","respondent":"中川原地域振興事業部長","answer":"品川の観光についてですが、今、私どもが品川の観光客として、お客様として把握といいますか、考えている方たちですけれども、関東近県の日帰りまち歩きの方、それから、国内外のビジネス客の方が大変多うあります。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"今まさに、今年９月にオリンピック・パラリンピックの東京開催が決まり、また、それと同時に、品川区とともに東京都の取り組みが大変注目されているかと思います。こんな背景の中で、今言われたように、品川区を売るプロモーションの観点、それとともに、情報発信について、現状もさることながら、これからやはり東京都の取り組みとともに、かなりの拡充が必要と思われますが、この２点、いかがでしょうか。","respondent":"中川原地域振興事業部長","answer":"東京都が、東京都に外国のお客様を呼び込んで、そして東京都が呼び込んだお客様を品川区が呼び込んで、品川区にたくさんのお客様に来ていただけるような連携をしていきたいと考えています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これから３年後、５年後を見据えたとき、この辺の力の入れどころは大変必要かと考えています。それからもう１点は、誰がこれから取り組みを拡充していくかというときに、人材の育成と活用について、伺いたいと思います。ただ、よくも悪くもボランティアの限界もあるかと思います。これは行政の職員しかり、観光協会への人的な支援しかりで、この辺の人材活用の点のお考えを伺いたいと思います。","respondent":"中川原地域振興事業部長","answer":"そしてもう一つ、ビジネス客が多いと申し上げましたが、これは、交通の利便性が高いということで、欠点といえば通り過ぎてしまう、活動の拠点として活用されるまちですけれども、これも、私たちの努力次第によっては、もうちょっとこのまちで過ごしたいとか。","voiceIndex":10,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"提案","question":"１点提案としては、やはり国際化という中で、どう見ても、羽田空港国際化の流れ、あるいは、品川駅というターミナルの中で、眺めているだけではもったいない、仕掛けが必要かと思います。１店舗で商売を営むより、集合体、今で言うフードパーク的な要素があることで、消費者の関心が寄せられるという点から、一つ、国際化の流れでの提案と思いますが、いかがでしょうか。","respondent":"中川原地域振興事業部長","answer":"そのときに、大使館の方ともよくお話をするのですけれども、一つの自治体とだけおつき合いすることは、仕事の関係上できないということで、先ほど、ご提案の、大使館として日本との、地域とのつき合いで、そういった料理の認定とか。","voiceIndex":12,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"提案","question":"区として、そういった古きよきものを残すようなどのような支援策をお考えかを、１点伺いたいと思います。方法論になるかと思います。今後を考えたときに、やはり単独では厳しい中で、方法で、他の事例、他の水族館等では、運営事業者の大胆な提案というようなものも興味があるところだと思います。この辺、水族館の今後という点で、いかがか伺いたいと思います。","respondent":"中川原地域振興事業部長、松代防災まちづくり事業部長","answer":"私からは、日本食というか、日本の食を楽しんでいただくために、どう残していくかという支援について、お答えいたします。委員会も含めて、いろいろとご提案等をいただいております。そういったものもしっかりと受けとめながら、今後のあり方というものを検討してまいりたいと考えているところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"都市型観光という明確な定義というのは、大変難しいかと思います。かいつまんで言いますと、やはり品川にふさわしい観光という中で、水族館は、認知度から、あるいは夢のある娯楽施設であり、教育施設であるという観点から、大きく未来に広がっていけばいいという思いで伺いました。この点で、先日の花火大会開催における評価ですとか、これまでの経緯、準備段階でのご苦労なども伺えればと思います。","respondent":"中川原地域振興事業部長","answer":"ですが、花火については、皆様方も夢をということでご意見をいただいておりますので、さまざま検討は、観光協会の中でもしていくということで聞いておりますが、非常にハードルが高くて、今年の担当者も、胃がおかしくなるほど大変苦労したということを聞いておりますので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"大変準備段階からの苦労、この場だけでも伝わるものがあるかと思います。これは運営者の苦労として伺います。これからの点で、花火単独というのは難しいというのはよくわかります。観光により人がにぎわうこと、あるいは伝統文化、そもそも日本の伝統文化だという観点があるかと思いますし、チャリティの要素だとか、いろいろな含みがありますので、その点、最後にご見解を伺えればと思います。","respondent":"中川原地域振興事業部長","answer":"実施する側、準備する側と、参加する側が必ずしも、いつも準備する側は準備する側で、見る楽しみを味わう方は、そういったところに協力してくれないという、そういう悩みも、一方、品川区のコミュニティでは抱えておりますので、花火につきましては、観光協会と品川区のほか。","voiceIndex":19,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"以上で、私の質問は終わりますが、前向きな施策というのは、大変な時代だからこそ必要かと考えていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"本多委員","kind":"質問","question":"渡辺委員に引き続き、品川区議会自民党の総括質疑を続けます。２０２０年オリンピック・パラリンピック東京大会に向け、質問をいたしますが、桃栗三年柿八年、８年ではなく、７年のスパンで、あえて頭でっかちに聞いていきます。長期的な視点、短期的な視点になるかと思います。はじめに、オリンピック・パラリンピック開催決定にあたっての品川区の意気込みをお聞かせください。","respondent":"濱野区長","answer":"一つは、今の６年生から９年生にかけての子どもたちにとって、このオリンピック・パラリンピックが、海外の人たちとの交流の場になる絶好のチャンスだということを申し上げてまいりました。外国からさまざまな人がやってくる。","voiceIndex":23,"id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"シティプロモーション、本当に大切なことだと思います、よろしくお願いいたします。品川区の地域振興事業部、文化スポーツ振興課の文化振興、生涯学習、スポーツ、文化センター、品川歴史館、どれも重要視されておりますけれども、スポーツ振興の単独にする考え方などないでしょうか、その辺をお聞かせいただきたいと思います。","respondent":"中川原地域振興事業部長","answer":"品川区としましても、これまでは、参加するスポーツという側面に着目して仕事をしてきましたが、これからは参加する、観戦する、そして支えるというスポーツの係わり方が出てまいりますので、今後、オリンピック・パラリンピックに向けて、どういうことを品川区として行う。","voiceIndex":25,"id":"exchange-011"},{"speaker":"本多委員","kind":"質問","question":"ちょっと別の角度から質問しますが、アスリートの声から、トライアスロン日本代表の上田藍選手らの問題提起の一つに、スポーツ選手のセカンドキャリアが取り上げられ、特に男子アスリートは３０歳を過ぎると、就職困難になるので、早めに転身してしまうケースがあるので、再就職の環境づくりをとの意見に、国会議員レベルでは、オリンピック・パラリンピック選手など。","respondent":"中川原地域振興事業部長","answer":"職員にうまく動いてもらって、地域の方にそういった分野でどう活動していただいたり、そういった充実感を持っていただくかという職ですので、そういったスポーツの専門性を持った方が、果たして課長という職になじむかどうかというのは。","voiceIndex":27,"id":"exchange-012"},{"speaker":"本多委員","kind":"質問・要望","question":"適材適所から、専門職、こちらもよりよい方法を選んでいっていただきたいと思います。いろいろと進めていく中で、讃える、応援するという点で聞きたいのですけれども、オリンピック１３大会連続応援に行かれている、名物の「オリンピックおじさん」こと山田直稔さんのお話を伺う機会がありました。","respondent":"中川原地域振興事業部長","answer":"こういった応援する、支えるということについても、今後、区民の皆様に、運動があまり得意でない方も、自分がこういう形でスポーツにかかわれるというようなことを、今までちょっと区としては、あまり取り組んでこなかった面もありますので、そういった面についても。","voiceIndex":29,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"全部７年後とか、長期的とか、短期的とかの視点で関連的に質問してまいりますが、款別審査でも質問がありました、船舶中継所跡の東品川清掃作業所粗大ごみ中継所、都区制度改革で、平成１２年４月１日より東京都から区に移管され、清掃という用途制限で、２０年間の縛りがあります。東京都に要請をしていくのか、しないのか、それから、その跡利用について、その辺について２点、お願いいたします。","respondent":"桑村企画部長","answer":"正直言いまして、東京都のほうでは、それが今までのルールということで、なかなか困難というのが、今のところの回答です。そういう意味では、２３区の中でも、こういうことについては、温度差があるのも事実です。","voiceIndex":31,"id":"exchange-014"},{"speaker":"本多委員","kind":"質問・要望","question":"それ以外では、補助２９号線の計画上の既存建物で、耐震工事への東京都の助成を受けて、２０年間の用途制限があるもの、そういったものは、道路計画上なので、そうした２０年間の縛りが緩和されるのではないかというようなことがあるそうで、東京都の２０年間の縛りは、言葉のとおりに本当に縛られていると思うのですが、時と場合によっては、その緩和があるのかというふうに思いますので、当然。","respondent":"桑村企画部長","answer":"そういう意味では、７年後を見据えて精力的に折衝してまいりたいと、そういうように考えているところです。","voiceIndex":33,"id":"exchange-015"},{"speaker":"本多委員","kind":"質問・要望","question":"ポートランド市と、おおむね５年置きに行っていますスポーツ交流事業、平成２４年度は野球とバスケットボール、品川区では、天王洲と品川区立総合体育館を活用しての交流試合、アメリカでの野球は、レッドソックス傘下２Ａのシードックスのホームグラウンド、ハドロックフィールド球場での交流試合を経験できる、次回の交流試合はおおむね４年後くらいでしょうか、品川区内の中学生に、次回のときに。","respondent":"中川原地域振興事業部長","answer":"ですので、今後も、経費の上手な使い方を工夫しながら、交流事業の継続に努めてまいります。スポーツ交流の先ほどのご提案ですが、スポーツ交流は、子どもたちの夏休み期間に実施しております。","voiceIndex":35,"id":"exchange-016"},{"speaker":"本多委員","kind":"質問・要望","question":"向上心ですけれども、こんなにいい機会があるのですから、ぜひ現地の品川友の会の人たちに折衝していただければと思います。あわせまして、４年後でなくても、９年後、シードックスの選手が、シーズンオフなどに品川区に来日されるような働きかけを、長期的に希望を言っていただいたり、また、そういうこともお願いしたいと思います。要望で、次に移ります。","respondent":"片田都市環境事業部長","answer":"そういう意味では、現在、１３号埋立地を含む東京ベイゾーンにコンパクトな大会の開催が予定されておりますし、ベイゾーンへのアクセスというということでは、今委員からお話しいただきましたように、りんかい線が主な交通手段になると考えております。","voiceIndex":37,"id":"exchange-017"},{"speaker":"本多委員","kind":"質問・要望","question":"行政が費用負担するばかりではなく、一体となって取り組んでいただきたいと思います。次に、オリンピック・パラリンピック開催時の警備や運営上の管理については、東京都がボランティアを拡大展開したり、警察、消防との連携強化で取り組まれることだと思いますが、それより先は今後の課題だと思いますが、現時点での、品川区のかかわりについて、どのようにお考えかお聞かせください。","respondent":"桑村企画部長","answer":"今後、いわゆる東京都の組織委員会と十分に協議して、私どものほうで協力できるものは十分協力してまいりますし、またボランティア等につきましても情報を提供し、いいオリンピック・パラリンピックが開催されるように努力してまいりたいと考えているものです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"本多委員","kind":"質問","question":"さまざま質問させていただきましたが、全て充実されることを望みまして、品川区議会自民党の総括質疑を終了いたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"品川区議会公明党を代表いたしまして、若林委員とともに総括質疑を行います。はじめに、在宅での子育て支援について、質問をいたします。品川区は、今後、乳幼児人口の推移をどのように予測しているのでしょうか。親子の広場など、スペース不足になりつつある子育て支援事業について、どのように考えているか、お伺いします。","respondent":"金子子ども未来事業部長","answer":"今後とも、各地域の人口動向についても注視して対応してまいる考えです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"スペース不足の解消を一歩進めるという意味で、現在、品川区内で２カ所開設をされております子育て支援センターの中に設置されている、自由に来館して憩える場、通称子育て広場の増設や、さらにはシルバーセンターなどの高齢者施設や学校、保健センターなどの区有施設を、所管を超えて有効利用すべきではないでしょうか。","respondent":"金子子ども未来事業部長","answer":"実際に区有施設を使うようになりますと、おのおのの施設の設置目的、あるいは利用対象、あるいは利用率から難しい点があります。したがいまして、これに関しては区有施設の有効活用の観点から、幅広く多角的に検討してまいりたいと考えております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"ぜひ、よろしくご検討のほうをお願いしたいと思います。次に、児童センターの運営体制につきまして、お伺いをいたします。品川区の児童センター全２５館は、区の直営館と、業務委託で運営をされております。直営館と業務委託館の数、そして、これまでの業務委託に対する評価ならびに今後のあり方について、お伺いをいたします。","respondent":"金子子ども未来事業部長","answer":"今後のあり方ですけれども、当面、館長館は直営を維持しつつ、委託館については、キッズ館の利点を伸ばし、児童センターの目的や役割意識の徹底を図っていくというふうに考えております。このことを基本としまして、時代の状況等も見据えて、絶えざる検討をしてまいる考えです。","voiceIndex":49,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"昭和４１年に中延児童センターが開設されて以来、全国の模範となるべく運営されてきた品川区の児童センターには、保護者のニーズのキャッチの仕方、こういった長年の努力で蓄積してきたさまざまな経験やノウハウ、これがあるはずであります。この貴重な財産が直営館はもとより、業務委託している各館にもれなく継承されていくことが大切であると思います。それぞれ区のご見解をお伺いします。","respondent":"金子子ども未来事業部長","answer":"この課題を解決するための一つとして、館長館と委託館との連携につきましては、現在、合同事業の実施や、事業の連絡相談を通じて図っているところですけれども、さらに委託館との相乗効果による事業の質のアップを含めまして、この連絡会は有効な手法と考えているところです。","voiceIndex":51,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"児童センターが依拠する児童福祉法第４０条には、児童に健全な遊びを与えて、その健康を増進し、または情操を豊かにすることと書かれております。続きまして、次に品川区の特別支援教育について、お伺いをいたします。そこで、まずはじめに第三次実施計画において、区教育委員会と区内小・中学校が担う役割とはそれぞれ何か、お伺いをいたします。","respondent":"田村教育次長","answer":"私から、東京都の特別支援教育推進計画第三次実施計画について、お答えいたします。区の役割と小・中学校のそれぞれの役割ということですが、区の役割の大きなところは、行政として、制度全般、実際の環境整備、あるいは、全体調整ということが大きな役割だろうと考えております。","voiceIndex":53,"id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"この特別支援教室モデル地区につきましては、現在、北区や狛江市など四つの自治体が参加をしておりますけれども、通級に通う児童・生徒、そして保護者の負担についての品川区のご認識、ならびに平成２８年度を待たずに早期の特別支援教室設置の必要性と可能性について、区のお考えをお伺いいたします。","respondent":"田村教育次長","answer":"ですから、真っ先に今、手を挙げて、モデル事業を実施するという考え方もありますが、やはりもうしばらく他区の状況等、あるいは、２３区の中で、そういう財源の措置がどういうふうな方向性にいくのかを注視しながら見ていく必要があるのではないかと、そのように考えております。","voiceIndex":55,"id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"発達障害の特性は、個人によって千差万別でありまして、適切な対応には、専門的な知識やスキルが必要とされております。特別支援教育研究の内容と、事業の成果、課題についてお伺いをします。そして、特別支援教室を各小・中学校に展開する際に、研究の成果をどのように活かしていくのか、お考えをお聞きいたします。","respondent":"田村教育次長","answer":"モデル事業の内容、成果、課題等ですが、まず内容ですが、平成２４年度、平成２５年度と２カ年にわたって発達障害のある児童・生徒の指導内容、方法に関する検討開発モデル校ということで、現実には源氏前小学校を指定して。","voiceIndex":57,"id":"exchange-026"},{"speaker":"塚本委員","kind":"提案","question":"特別支援教育コーディネーターは、専門的知見のみならず、個別指導計画作成のための関係者の意見調整など、マネジメント面の仕事も要求されるので、学校教員から任命することに限らず、外部から人材を求めてもよいのではないかと考えますが、それぞれ品川区の見解をお伺いいたします。","respondent":"田村教育次長","answer":"特別支援のコーディネーターは、外部人材を活用できないか、ということで、現在は、各校複数名、教員を指定していますが、やはり国のモデル事業でも、特別支援ケアアドバイザーをモデル校に配置する等を考えておりますので。","voiceIndex":59,"id":"exchange-027"},{"speaker":"塚本委員","kind":"質問","question":"ぜひ、よろしくお願いしたいと思います。第三次実施計画には、乳幼児期から学齢期への連続性のある支援体制の構築に関するモデル事業を実施するとありますけれども、モデル事業の内容についてと、発達障害のある子どもを早期発見、早期支援するため、教育、福祉、医療、保健等の連携について、どのように考えているのか、品川区の見解をお伺いいたします。","respondent":"田村教育次長","answer":"区教育委員会は、就学予定時の就学支援シートの配布だとか、必要によって情報を引き継ぐ積み重ねもしていますので、引き続き今後も都の早期連携モデル事業、立川市でやっているようですが、情報収集にも注力していきたいと考えています。","voiceIndex":61,"id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"はじめに中小企業支援策について質問いたします。税収や雇用の面など、中小企業の業績が区政に与える影響をお聞きいたします。６人の中小企業診断士による、経営相談事業で行われている経営相談、経営診断について、成果と課題、今後の取り組みなどをお聞きいたします。３点目に、中小企業等支援事業では、東京都から１事業に１,１００万円の補助金が出ているだけで、国からの補助金はありませんでした。","respondent":"中川原地域振興事業部長","answer":"それによりますと、業況は水面下ながら改善傾向、ただし製造業は原材料高、小売業、サービス業は利幅の減少等、業種業態によって注視すべき経営上の課題はあると認識しています。これは本会議でもお答えしたとおりです。","voiceIndex":65,"id":"exchange-029"},{"speaker":"若林委員","kind":"質問","question":"まず明確な漏れは、条例、要綱の根拠、ここは漏れておりますので、ご答弁願います。それから、監査委員から指摘のあった予算措置、これは別にあっ旋事業がいいとか、悪いとか、その話の段階ではなくて、半分しか執行率がありませんねと、それは監査委員の指摘があったので、これからどういう改善をしていくのかという角度の、前向きなお考えをお聞きしたいと思います。","respondent":"中川原地域振興事業部長","answer":"融資あっ旋の事業の成果と、今後の課題ですが、こういった形で実施しておりますので、さらに経済状況に合わせて、企業の方々のお役に立つような融資としてやっていきたいと考えています。","voiceIndex":67,"id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"監査委員のご指摘、また款別の審査でも、こういうお話が出ました。今後の予算の立て方については、重々また検討していただきたいと指摘をします。ほぼ国などの補助金に頼らず、一般財源等を使う中小企業支援は、区民の理解も求められると思います。政策の着実な策定から実施に向け、スキームの構築や条例といった根拠となる柱を立てることなど、中小企業振興の展開について、お考えをお聞きします。","respondent":"中川原地域振興事業部長","answer":"条例というようなご提案もありましたが、品川区の場合、長期基本計画で１０年、そして、中期の実施計画の見直しで３年ごとに見直しをしながら、またそこに緊急対策をあわせてやっておりますので、そういった中で柔軟に対応していくということでは。","voiceIndex":69,"id":"exchange-031"},{"speaker":"若林委員","kind":"質問・要望","question":"既存の９０人のカタリストと、大変に充実した内容ということを強調されましたので、またその拡充もしっかりと行っていただきたいと思います。重ねて、経営改善支援に対する品川区の積極的な姿勢を打ち出すこと、また、具体策として、コーディネーターの配置や専門家のさらなる充実、また、金融機関との連携強化について、お考えをお聞きしたいと思います。","respondent":"中川原地域振興事業部長","answer":"さらに中小企業の活性化のために、さまざまな方のお力、自治体、金融機関と連携してまいりたいという考えです。","voiceIndex":71,"id":"exchange-032"},{"speaker":"若林委員","kind":"提案","question":"来年でしょうか、大崎ものづくり産業支援施設が開設される予定となっております。条例の提案もさせていただきましたけれども、これを機にスキームの構築、また、振興策の拡充を検討していただきたいと考えています。次に、中小企業支援策の最後、公共事業についてお伺いしたいと思います。区内企業への発注の配慮は、どのようにされているのかもお聞きいたします。","respondent":"中山総務部長","answer":"発注の適性化という観点ですけれども、基本的には、特定の事業者に偏らないような発注ですけれども、その際に規模に応じての支援というものも考えているものです。","voiceIndex":73,"id":"exchange-033"},{"speaker":"若林委員","kind":"質問・要望","question":"私は、ここでは入札に参加できない企業へちょっと焦点を絞っていきたいと思います。いわゆる配慮から実行性を持たせた施策の実施が必要と考えています。区内企業活性化の有効な支援策の一つと、私は感じてまいりました。そこで、総合評価方式にあって、入札参加者の、下請け業者の発注に区内企業を活用した場合、評価点加算する方策も検討していただきたいと思いますが、お考えをお聞きします。","respondent":"中山総務部長","answer":"こういうものについて、さまざま検討する中で、こういう下請けに関する一定の配慮ができるかどうかについても、情報を十分に収集しながら、課題も含めて分析して検討してまいりたいと思います。","voiceIndex":75,"id":"exchange-034"},{"speaker":"若林委員","kind":"質問","question":"検討のほど、よろしくお願いいたします。次に、民間住宅ストックの活用策と、老朽危険空き家対策について伺います。空き家を含めた民間住宅ストックについて、戸建てや共同住宅、築年数別の戸数など、概要をお知らせください。実態把握のための調査を実施されたのかを伺います。窓口体制や対応内容、実績などをまずはお知らせください。協力や連携の現状と成果、課題などがありましたらお聞きいたします。","respondent":"片田都市環境事業部長、早津健康福祉事業部長","answer":"不動産業界との連携については、事例として、業界との意見交換によって、オーナーの不安を払拭するために、各種の緊急時の連絡先を取りまとめたパンフレットを作成して、不動産業者とか、あるいはオーナーのほうに配付するなどして。実績ですが、平成２２年度では、２４件の申請で１３件の契約、平成２３年度は、２６件の申請で１３件の成立、平成２４年度は、１５件の申請で４件が成立という状況です。","voiceIndex":77,"id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"こういった支援策を活用するなど、実態調査を今後しっかり実施していただきたいと思いますが、お考えをお聞きいたします。そこで、公共的、また公益的な活用策についてのお考えをお聞きしておきます。もう１点、不動産業界との連携についてですが、世田谷区でこの施策を進めているということで、お話を担当者から伺う機会がありました。","respondent":"片田都市環境事業部長、早津健康福祉事業部長","answer":"ただ、所有者との合意がやはり一番大きなハードルということで認識していますので、地域のニーズや、あるいは関係者の意見を聞いて慎重に考えていく必要があると考えています。こうした経済的な支援のほかに、例えば緊急通報システムなどの福祉サービスの紹介を適切に行うことで、入居者やオーナーの安心を確保しようと、そのような工夫をしてまいりたいと考えております。","voiceIndex":80,"id":"exchange-036"},{"speaker":"若林委員","kind":"質問","question":"住宅困窮者支援としては、今、さまざまな見守りサービス、また身元引受の件、取り組んでおられるということですけれども、結局、１３件、１３件、４件がこの３年間の実績だということでなかなかつながりにくいという実態はあると思います。そこで、現在、公助と共助による助け合い、支え合いのさまざまな見守りのサービスが行われております。お考えをお聞きいたします。","respondent":"片田都市環境事業部長","answer":"そういう意味では、各所管が十分な連携を取る必要があると考えていますし、横断的な連携、あるいは情報の共有の中で、きちっと地域のニーズを捉えて、先ほどのような地元の不動産業者との連携、あるいは、オーナーとの問題。","voiceIndex":83,"id":"exchange-037"},{"speaker":"若林委員","kind":"質問","question":"最後に、老朽危険空き家について、伺います。１点目に、住民の声をどのように捉え、認識しているのか伺います。２点目に、除却工事支援制度について、対象となる物件や区域、支援の内容、実績などをお聞きいたします。３点目に、住宅地区改良法では、空き家ではなくても不良住宅と認定されれば除去事業対象となる、となっておりますけれども、この認識と対応をお伺いいたします。","respondent":"片田都市環境事業部長","answer":"住宅地区改良法についてですけれども、不良住宅が密集する地域の改良について、環境の整備改善を図るですので、国土交通大臣が指定して、事業を進めるということで、不安、衛生上の問題に対しての対応を行う事業として認識しています。","voiceIndex":85,"id":"exchange-038"},{"speaker":"若林委員","kind":"質問・要望","question":"除去工事については、実績もあわせてお知らせいただきたいと思います。住宅地区改良法では、住んでいる方でも除去対象になるという認識と、今伺いましたので、私も、そういう相談等がありますので、またしっかりとご検討、研究していただきたいと思います。老朽化対策の根本は、老朽化を予防することです。条例化など、今後の老朽危険空き家対策の取り組みへのお考えをお聞きいたします。","respondent":"片田都市環境事業部長","answer":"老朽空き家の除却に対しての条例等々のお考え、ほかの区でもいろいろ条例化をされた区もありますので、そういう状況をよく注視しながら、区としてもその必要性についても検討してまいりたいと考えております。","voiceIndex":87,"id":"exchange-039"},{"speaker":"若林委員","kind":"質問","question":"住宅ストックと老朽空き家の問題、また中小企業支援、２点にわたってお聞きさせていただきました。今後とも、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-040"},{"speaker":"向委員","kind":"質問","question":"安心して、健やかに子どもを生み育てられる環境づくりについて、本区の施策全般についてお尋ねしていきたいと思います。妊婦健康診査についてお尋ねしたいと思います。これまでにも、私はお尋ねしてまいりましたが、この妊婦健康診査の助成について、現状とかけ離れているのではないかということで問題提起を、これまでにもしています。その結果をもとにした改善の検討も含めて、区のご見解を教えてください。","respondent":"早津健康福祉事業部長","answer":"ＨＴＬＶ－１ウイルスにつきましては、検査を受けて陽性と判明した場合に与える心理的な反応が母体に与える影響が大きいのではないか、むしろ初回で受けるよりも、安定した段階で検査をしたほうがいいのではないかというのが。","voiceIndex":92,"id":"exchange-041"},{"speaker":"向委員","kind":"質問・要望","question":"反対に、両親学級、二人で子育てクラスは土日の開校になっております。働いている妊娠中の女性はなかなか休みが取りづらく、何とか都合をつけて、妊婦健診に月に１回もしくは２回ほど通っているような状態ですけれども、改めてお尋ねしますが、マタニティクラス、土日の開校について、必要とお考えでない理由、今後、検討していただけるのかどうか、そのあたりを再度お尋ねします、よろしくお願いします。","respondent":"矢野品川区保健所長","answer":"母親学級、両親学級とも、どちらも参加できない方についても、ご希望に応じて訪問等により個別に相談支援もしております。母親学級につきましては、平日を基本としつつ、今後、引き続き妊婦への支援体制をどのように充実していくのがよいのか検討してまいります。","voiceIndex":94,"id":"exchange-042"},{"speaker":"向委員","kind":"質問","question":"ちなみに、平成２３年度の受講者数は５５６人、出生届出数が、例年大体３,５００人程度と考えると、やはり受講者の数は少ないと思います。続きまして、予防接種助成、感染症予防啓発など全般についてということで、その中からＢ型肝炎の予防接種助成について、区の考えをお伺いしたいと思います。もし半額助成する場合は、対象人数、どれくらい必要になるのか教えていただければと思います。","respondent":"矢野品川区保健所長","answer":"ただ、任意接種を一部助成するという場合には、区の財政負担を考慮しつつ、事業実施の効果と比較して検討してまいりたいと考えています。対象の人数ですが、１歳未満を対象とするということで、新たに生まれる乳児が約３,６００名です。","voiceIndex":96,"id":"exchange-043"},{"speaker":"向委員","kind":"質問・要望","question":"海外から見ると、先進国であるのに、ここまでさまざまな感染症が蔓延しているといいますか、予防接種対策などがまだまだ必要な国というのは珍しいと思います。７年後、オリンピック・パラリンピックの開催も決まりましたので、このあたりは重要な課題ということで、今後の対策を期待したいと思います。改めまして、調査に取り組む姿勢といいますか、今後、調査をしていただけるのか教えてください。","respondent":"桑村企画部長","answer":"基本的には、税制度の中で解決すべき課題だとは考えてありますけれども、２３区の中でみなし適用を始めた区がある、あるいはこれから始めようとしている区があるという状況ですので、影響額ですとか、あるいは、該当者数ですとか、あるいは事業数ですとか。","voiceIndex":98,"id":"exchange-044"},{"speaker":"向委員","kind":"質問","question":"前向きなご答弁、感謝します。そして、続けて東京オリンピック・パラリンピックを見据えた施策についてもお伺いいたします。品川区で、どんな人でも安心して住み続けられるまちとして、情報発信の体制の整備なども踏まえて、今後７年間、どういった舵取りをされていくのか、区のお考えを教えてください。","respondent":"桑村企画部長","answer":"今後、さらに工夫してサインをつくっていきたいと思ってあります。今、報道等でも、国や東京都でもいろいろな表記の方法を考えられていると思います。そういった方向も考えながら進めてまいりたいと思います。","voiceIndex":100,"id":"exchange-045"},{"speaker":"向委員","kind":"質問・要望","question":"はい、わかりました。今後、オリンピック・パラリンピックを見据えた施策ということで、そういった制度づくり、私も個人的にもすごく楽しみにしております。品川区として、もともとあるポテンシャルに加えて、新しく迎えるための制度づくり、頑張っていただきたいのですが、オリンピック・パラリンピックを見据えての関連といいますか、区内の分煙化促進についても、ちょっと今後のことをお尋ねしたいのです。","respondent":"中川原地域振興事業部長","answer":"喫煙と禁煙のあり方と、マナーアップについての区の取り組みですが、今、分煙が進んでいるのは、平成１５年にいわゆる受動喫煙防止法ができまして、多くの人が集まる場所の管理者に、管理について必要な措置を講じるように努めなければいけないと定められたことと。","voiceIndex":102,"id":"exchange-046"},{"speaker":"向委員","kind":"質問・要望","question":"オリンピック・パラリンピックということで、大分長いといいますか、７年後ということで、漠然としたイメージという部分もあるかもしれませんが、日本人のマナーというのは、本当に世界に誇れる部分があると思います。おもてなしの部分も踏まえて頑張っていただきたいと思います。以上で、私の質疑を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-047"},{"speaker":"木村委員","kind":"質問・要望","question":"平成２４年度日本経済、前年比１.２％の増、そのような状況の中で、本区は、特別区民税が前年比１０億円のプラス、そして２.６％、４年ぶりの増ということです。非構造部材の耐震化については、平成２４年度から引き続き平成２５年度においても行われている事業ですけれども、現在までの状況と、全ての工事が完了する予定はいつごろになっているのでしょうか。","respondent":"田村教育次長","answer":"私のほうから、学校耐震化等についてお答えいたします。学校の耐震化は、平成１７年度より順次計画的に進めてまいりまして、現在のところ、４０校実施済みです。","voiceIndex":106,"id":"exchange-048"},{"speaker":"木村委員","kind":"質問","question":"しかし、１２万人はあくまでも想定でありますけれども、現時点では、１２万人の収容は可能になったけれども、仮定でお聞きしますけれども、もし平成２４年度中に直下型地震が起きていたら、避難所の状況はどのようになっていたとお思いでしょうか。もしくは、１２万人収容の対応が完了した後でも、１３万人、１４万人という想定外の避難者が詰めかけていたら、避難所はどうなっていたとお思いでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"収容人員を超える避難者が発生した場合ですけれども、避難所に指定していない区の施設や民間の災害時協力協定施設等、あらゆる資源を活用して対応することになると考えているところです。","voiceIndex":108,"id":"exchange-049"},{"speaker":"木村委員","kind":"質問","question":"平成２４年度には、小学校７校、中学校３校、下水道耐震化工事が行われていたと思います。目に見えない巨大な力に対し、一刻も猶予を許されない状況である現在、早急に簡易トイレを備蓄すべきと考えていますけれども、お考えをお聞かせください。今後、区民に対し、行政としてどのように指導すれば、食糧や水の備蓄だけではなく、同時に簡易トイレの備蓄は進むとお考えでしょうか、あわせてお聞かせください。","respondent":"松代防災まちづくり事業部長","answer":"あらゆる機会を、さまざまな方法を用いて、粘り強く継続して啓発していくことが必要であろうと考えているところです。","voiceIndex":110,"id":"exchange-050"},{"speaker":"木村委員","kind":"質問・要望","question":"それはよろしくお願いしたいと思います。次に、災害時での区民への情報発信の取り組みについて、区はどのように考えているのでしょうかとの質問に、災害時の被害状況や避難所に関する情報は、適切な避難行動や区民の生命を守るために非常に重要であると考えている、混乱を防ぐためにも、被災者が求める情報を伝えることの必要性を強く認識している。以上をもちまして終わりです。","respondent":"松代防災まちづくり事業部長","answer":"防災タブレットの配備状況等についてのご質問です。防災タブレットは、現在、町会長・自治会長などのお宅に配備を進めているところです。配備完了は１１月中旬を目途としています。","voiceIndex":112,"id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"どうぞよろしくお願いいたします。防災対策について質問いたします。改定内容としては、計画の策定、情報伝達機能の強化、津波・高潮対策、避難の整備、不燃化・耐震化の促進など、多岐にわたる対策に従事してまいりましたが、平成１９年度と比べて、このように事業を見直しした背景、それと修正ポイント、まず２点をお伺いしたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"東京都が公表した、首都直下型地震等の被害想定を踏まえた対策の強化、東京都地域防災計画の修正に合わせた都区の役割分担、連携の整合性と担保等々、状況の対応のために区の地域防災計画を見直したところです。","voiceIndex":115,"id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"品川区としては、品川防災力の高度化をしてきたわけですけれども、今、お伺いしました中に災害対策の拡充の内容等がたくさん関連しておりました。平成２０年２月に、東京都が公表いたしました地域危険度測定調査のうちの火災危険度、上位の１００町丁目のリストの結果に注目しますと、品川区内の町丁目のうち、１位、３位、５位、６位と上位ランクに入っております。そこで２点ご質問します。","respondent":"片田都市環境事業部長","answer":"ランクが下がった理由ですけれども、３.１１を含めて、地盤の再検証とか、地震の増幅率といったものを検証した中で、評価としてこのような数値になったというものです。","voiceIndex":117,"id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"これをお伺いした理由は、やはり、数年でさまざまな事業で防災力のアップで、また地盤の調査などのランクの内容が変わっていったのはわかるのですけれども、ここで区民の皆様からのよくある質問ですけれども、ご心配の種といいますか、今までの取り組みの対象が変わるのではないか、または対象が後に回るということがあるのではないか、また私がちょっと見落としたのかもしれませんが。","respondent":"片田都市環境事業部長","answer":"周知についても、これまでも、ランクについて、わが家の防災ハンドブックに記載していますし、そういうものを通して会見の機会等を捉えて、きちっと区民のほうにも周知してまいりたいと、このように考えております。","voiceIndex":119,"id":"exchange-054"},{"speaker":"吉田委員","kind":"提案","question":"防災についてですけれども、関連いたしまして、密集住宅市街地整備について、お伺いいたします。そこで、容積率アップや３種の斜線制限についての建築基準法を条例により見直すこと、これにより、狭小住宅が移転をすることなく幅員４ｍ道路を広げる場所にできるのではないかと、私は提案いたします。条例の提案をしますが、ご見解をお聞きしたいと思います。","respondent":"片田都市環境事業部長","answer":"建築基準法の独自の条例については、委任条例ということで、東京都安全条例なんかはその対象になりますけれども、区でそのような条例をつくることは、法律違反になるということで慎重な検討が必要かと考えています。","voiceIndex":121,"id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません、十分に難しいということは、ご答弁でわかったのですけれども、これはひとつのアイデアですけれども、新たなアイデアを打ち出して検討していただいて、また上に上げていくことを考えていく時期ではないかと、これはもう要望させていただきたいと思います。続きまして、今度は食糧の備蓄について、お尋ねします。この２点を、お伺いいたします。","respondent":"松代防災まちづくり事業部長","answer":"在宅避難者への供給も考慮しまして、区内関係団体等の協定等により、食糧の供給体制を整備しているものです。消費期限に近づいた備蓄食糧は、廃棄することなく、区民防災組織等が実施する訓練や啓発事業の際に活用し、防災啓発に役立てているです。","voiceIndex":123,"id":"exchange-056"},{"speaker":"吉田委員","kind":"質問","question":"先ほど、ご答弁もありましたが、理由としては、首都直下型地震の場合、エリアが小さくとも人口密度が高いため、救援がすぐに来ないという可能性が高く、せめて１週間自力で生き延びる必要があるという見解でした。ここで、ローリングストックという方法をご存じでしょうか。ちょっとご紹介します。復興は、日常を取り戻すのが目的です。このローリングストックに対する区のご見解をお教えください。","respondent":"松代防災まちづくり事業部長","answer":"循環備蓄とも言っていると承知しています。","voiceIndex":125,"id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"年中無休で、お正月も１日から買い物ができ、夜中でも、コンビニで買い物ができます。それにより、買い置きという考え方がなくなってきつつあります。だから、今こそ、自助ストックについての考えは重要と思いますので、これからも必要性をしっかりと周知していっていただきたいと思います。本区における教育改革プラン２１のカリキュラムマネジメントについて、お伺いいたします。２点、お伺いいたします。","respondent":"田村教育次長","answer":"各校のテーマですが、さまざま各校のテーマがありますので、幾つか例をご紹介しますと、荏原平塚学園ですと、選んでよかったと思える学校にするための組織運営、それから、東海中グループですと、分離型、連携型としての小中一貫校のあり方ということで、取り組みについては。","voiceIndex":127,"id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"この事業は、子どもたちの学習意欲の向上、学習習慣の確立に向けて教職員全員が自由なテーマを設けて学習指導を展開しようとしていき、それに対して、研究や工夫をしていることのようですが、このカリキュラムマネジメントと、今までの教育改革プラン２１の取り組みと、どのように関連しているのでしょうか、導入の狙い、この二つを教えてください、よろしくお願いします。","respondent":"田村教育次長","answer":"品川区の教育改革プラン２１では、第一ステージでは、学校選択制の導入、第二ステージでは、学力定着度調査や外部評価制度の導入、第３ステージでは小中一貫教育要領の実施ということで、第４ステージにおきましては、そういう状況を全部踏まえて。","voiceIndex":129,"id":"exchange-059"},{"speaker":"吉田委員","kind":"質問","question":"計画がＰで、全体計画と年間指導計画の策定ですね。実施がＤで、単元づくりと授業、そして評価がＣ、改善がＡで、ＰからＤ、ＤからＣ、ＣからＡ。このスパンは、大きなものは年間の考えがあれば、またはそれぞれの単元の短期のスパン、または１時間の授業においても考える短期スパンのサイクルがあると思いますが、短期と長期の関係は、どのようにお考えでしょうか。この３点、ご質問します。","respondent":"田村教育次長","answer":"実際の効果の検証ですけれども、まだ最短の２年の期間が、平成２６年１月が一つの区切りで研究発表を予定していますので、中間報告は受けてありますが、まだ、検証して、効果という点までご報告できる段階では今はないです。","voiceIndex":131,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"重ねまして、これは学校内のことだけなのでしょうか。この試みは、家庭や地域社会など、学校外への働きも重要だと思います。これは学力向上以外にも地域に貢献する方向性も試みてほしいと思いますので、最後にご答弁お願いいたします。","respondent":"田村教育次長","answer":"研究発表もありますし、冊子等をつくった暁には、やはり校長連絡会だとか、発表会だけに終わらせず、ほかの学校にもその効果を反映させて、底上げを図れるような取り組みをしてまいりたいと、そのように考えております。","voiceIndex":133,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"子どもたちの未来のために、ぜひよろしくお願いいたします。続きまして、小・中学校における土曜日の授業について、質問します。先日の新聞に、全国の公立小・中・高等学校で、土曜日授業の実施については１割以下にとどまることが文部科学省の調査でわかりました。区市町村の教育委員会の１割は必要としたのに対し、必要がないというのは３割という記事が載っておりました。","respondent":"田村教育次長","answer":"品川区では、時数の確保というのをメインで進めてまいりましたが、現実には、土曜日授業をやらないと、平日の月曜日から金曜日にどうしても厳しい、５時間、６時間の授業で、すし詰め状況ということなので、第１、第３土曜日を広げることによりまして、平日のときに補習したり。","voiceIndex":135,"id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は、長いスパンでの教育として、土曜日の授業を考えて、イベント的要素ではなくて、学力向上、また一番お願いしたいのは、教職員の方々が子どもと向き合う時間、これを確保していただきたいと思います。私の質問は以上です、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回、風しん流行の中心になった２０歳代から４０歳代の男性へのさらなる強力な啓発も必要ですが、妊娠を希望される女性に対して、その施策を、今回はお伺いいたします。国の動きにもよると思いますが、これらの女性に対する風しん抗体検査の費用、そして抗体がないことがわかった妊娠を望む女性へのワクチン接種費用の助成は極めて大切な施策だと思いますが、区の対応はいかがでしょうか。","respondent":"矢野品川区保健所長","answer":"抗体検査の助成および十分な抗体を持っていない女性に対してのワクチン助成等については、国の対応も見据えて、今後検討していきたいと考えております。","voiceIndex":139,"id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ぜひ、先天性風しん症候群の赤ちゃんの誕生が少しでも減少するように、実効性のある施策を要望して、次の質問に移りたいと思います。今回はＢ型肝炎の治療について伺います。Ｂ型肝炎を発病した場合、どのような治療が行われているのでしょうか。その医療費は、高額療養費制度の対象になるようですが、おおむねどのくらいかかっていると考えたらよろしいのでしょうか。","respondent":"矢野品川区保健所長","answer":"Ｂ型肝炎にかかった場合の治療および費用ですが、治療に関しては、インターフェロンや坑ウイルス薬などによる治療が行われます。年間におよそ８０万円以上かかると言われております。","voiceIndex":141,"id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"Ｂ型肝炎ワクチンについてお尋ねいたします。このワクチンはどのようなワクチンで、接種方法、副反応、現在の予防接種システムの中で位置づけられているのでしょうか。既に今年４月に定期接種化された小児に対するインフルエンザ菌Ｂ型Ｈｉｂワクチン、小児用肺炎球菌ワクチンと、価格、接種回数、ワクチンの安全性についての比較はいかがでしょうか、ご答弁をお願いいたします。","respondent":"矢野品川区保健所長","answer":"Ｂ型肝炎ワクチンは、国の検討会において第二次提言で定期接種化すべきということで、区としても重く受けとめているワクチンです。ワクチンの単価がおよそ５,０００円くらいで、３回の接種が必要とされております。","voiceIndex":143,"id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問","question":"Ｂ型肝炎ワクチンは、Ｂ型肝炎ウイルスの遺伝子を酵母菌に組み込んで製造された不活化ワクチンで、３回皮下接種で行います。３歳までならほぼ１００％、４０歳でも９５％の方に免疫ができます。ここでお尋ねします。この七つのワクチンが、定期接種化として取り上げられた理由と、なぜ、三つのワクチンのみしか定期接種にならなかったのか、区のご見解をお伺いいたします。","respondent":"矢野品川区保健所長","answer":"七つのワクチンのうち、三つのワクチンが先に定期接種化されましたのは、先ほど一部お答え申し上げましたが、国のほうが任意接種であるが、一部助成をして接種を勧めていくという状況であったです。","voiceIndex":145,"id":"exchange-067"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"３歳前に感染すると慢性化する可能性が高く、慢性肝炎から肝硬変、肝臓がんに進行していきます。品川区では、定期接種が見送られた四つのワクチンのうち、水疱瘡ワクチン、おたふく風邪ワクチン、成人用肺炎球菌ワクチン、ニューモバックスには、他区に先駆けて先進的に３,０００円の一部助成が始まり、現在も行われております。ぜひ、区のご英断を求めたいと思いますが、区のお考えはいかがでしょうか。","respondent":"矢野品川区保健所長","answer":"Ｂ型肝炎ワクチンの一部助成という件につきましては、区の財政上の負担を考慮しつつ、事業実施の効果等を比較して検討してまいりたいと思います。","voiceIndex":148,"id":"exchange-068"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ぜひ、前向きなご検討をお願いして、次にまいりたいと思います。最後に、品川区の食物アレルギー対策について、お尋ねいたします。調布市の事故を踏まえて、品川区の対応についてお尋ねいたします。品川区の小・中学校で、現在、どのように食物アレルギーの研修が行われているのでしょうか。研修内容、研修回数、出席者についてお示しいただきたいと思います。","respondent":"田村教育次長","answer":"出席者は、対象はあくまで全教職員ということで実施しているものでございまして、東京都の研修を含めまして、１回ないし多いところで３回ということで研修を実施しています。","voiceIndex":150,"id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"担任は、養護教諭が来た時点で、エピペンを注射することの同意を養護教諭に求めることなく、初期対応を誤った。再度、お尋ねします。現在の研修で、アナフィラキシーが発症したときの場合の、緊急時の対応として、エピペンに関する研修も行われているのでしょうか。エピペンの使用に関して、消防署、医師会などとの連携は行われているのでしょうか。緊急時の学校の体制はいかがでしょうか。","respondent":"田村教育次長","answer":"実際に自分の太ももを使って練習することで、正しい打ち方と、打った感覚を身につけることができるというものです。消防署、医師会との連携ですが、今のところ特に連携はしておりませんが、現在進めております食物アレルギーの対応マニュアルの改定作業の中で検討してまいります。","voiceIndex":152,"id":"exchange-070"},{"speaker":"南委員","kind":"質問","question":"日本共産党品川区議団を代表して総括質疑を行います。私は、特別養護老人ホームや保育園、障害者福祉施設などの増設計画を一刻も早くつくってほしい、区民の皆様のこの願いを受けとめて、質問をいたします。はじめは、国が売却を予定している土地、区が用途を終了して現在暫定活用中の学校跡地、また、建替え予定の区営住宅について、どこにあるのか、何m2あるのか伺います。","respondent":"桑村企画部長","answer":"国有地ですけれども、今、国家公務員宿舎の廃止予定が５カ所、品川区内ということになってあります。それについて順次、提示されていくわけですが、今現在、南品川にあります品川寮が提示をされておりまして、これにつきましては、保育園で活用ということで、国に返答しています。","voiceIndex":157,"id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"ようやく材料が出揃いました。特別養護老人ホームや認可保育園などをつくるには、土地がある、このことがわかりました。これだけの土地をどのような区民要望に使うのか、ここが大事なところだと思います。区長の姿勢が問われるのではないかと思います。そこで次に、区の財政状況について伺います。区民税と特別交付金の決算額は、当初予算額より増えています。どのくらい増えたのか、増えた理由を伺います。","respondent":"本城企画財政課長","answer":"特別区財政調整交付金の予算との比較ですが、当初予算に比べて３８億２,５００万円余の増です。増加の理由につきましては、主に普通交付金につきまして、交付金の原資であります調整３税が増えたことに伴って、基準財政需要額を再算定した結果が主な理由です。","voiceIndex":162,"id":"exchange-072"},{"speaker":"南委員","kind":"質問","question":"平成２４年度の基金残高は６９９億６,７００万円になったことが、決算審議でわかりました。平成２４年度当初予算の見込み額は５４３億円としてありましたけれども、これが１５６億円も増えています。なぜこんなに増えたのか伺います。","respondent":"本城企画財政課長","answer":"平成２４年度に生じた理由としましては、年度の最終段階で３３億円ほど追加で基金を積み立てたこと、そして一番最後の段階で、歳出面の不用額と、あるいは、財政の収入面の増があった関係で、７０億円ほど基金を取り崩さなくて済んだ分、それらを合わせて１５０億円余の差です。","voiceIndex":164,"id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"最初の質問で、土地もある、そして今の質問では財政力もある、あと切実な区民要望をかなえようとする区長の姿勢があれば実現できます。そこで、私は切実な区民要望の実現を求めて、待機児解消を求めて保育園の増設と、特別養護老人ホームと老人保健施設の増設、この質問をさせていただきたいと思います。なぜ将来の財政負担を理由に区立の認可保育園をつくらないのか、改めて伺います。","respondent":"金子子ども未来事業部長","answer":"その後、乳幼児人口につきましては減少に転じるものの、保育園の申込み率が上がると見込まれますので、しばらくは保育ニーズは高どまりになると、このような流れの中で、保育ニーズというのが、かなりの期間続くだろうと、そうなりますと、当然。","voiceIndex":166,"id":"exchange-074"},{"speaker":"南委員","kind":"質問","question":"将来の財政負担を理由に保育園をつくらない、そういうことを、私は聞いたのですけれども、今のご答弁では、なぜ保育園をつくらないのかということ、お金がかかるからつくらない、こういうことでいいわけですか。もう一度、そこのところをはっきり伺いたいと思います。","respondent":"金子子ども未来事業部長","answer":"私は、保育園をつくらないという答弁をした覚えはございません。あくまでも総合的な待機児童対策として、認可保育園、認証保育所、そして保育ママ、こういったものを総合的に積極的に取り組んでいくというふうに申し上げているところです。","voiceIndex":168,"id":"exchange-075"},{"speaker":"南委員","kind":"質問","question":"区民の皆様は、認可保育園をつくってくれと、こういう要求です。保育ママではないのです。認可保育園をつくらないのを、財政負担がかかるからとおっしゃいますけれども、区民は、そういうことはとんでもないというふうに思うのではないでしょうか。では、財政負担とは何ですか。人件費ですか、土地購入費でしょうか、それとも日常的な運営費ですか、どこなのでしょうか、伺います。","respondent":"金子子ども未来事業部長","answer":"認可保育園に係わるお尋ねですけれども、先ほどから申し上げているとおり、民間事業者の開設支援をしているわけですけれども、認可保育園を品川区でつくらせないというようなことは、一切申し上げておりませんので、その点だけはしっかりと確認していただきたいと思います。","voiceIndex":170,"id":"exchange-076"},{"speaker":"南委員","kind":"質問","question":"区立の認可保育園、ここをつくらない、財政負担だと、ここがわからないと言っているのです、理解できないと。もう一度ちょっと質問したいと思いますけれども、お願いします。","respondent":"金子子ども未来事業部長","answer":"平成２７年の７月前後に開設予定の御殿山幼稚園の移転に伴う２カ所の施設についても、幼保一体施設、あるいは、今のところ、保育所型認定子ども園として開設するというふうに、委員会でご報告してきたところです。","voiceIndex":172,"id":"exchange-077"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、私はやはり、多くの区民の皆様の切実な願いである認可保育園、とりわけ長期基本計画に一言も触れてない区立認可保育園、ここをしっかり計画に組み入れてやるべきだと、しかも土地はあります、財政力もあるのです、このことを強く求めておきたいと思います。区は、特別養護老人ホーム増設を３カ所計画しましたが、いつ、どこにできるのか、入所可能数は何人なのか、教えてください。","respondent":"早津健康福祉事業部長","answer":"平成２８年５月開設は、平塚橋会館跡です。こちらは特別養護老人ホームは１００人の予定です。それから、今計画中ですが、旧みやこ荘跡地、こちらは平成２９年度の開設予定でございまして、特別養護老人ホームは１００人程度という予定です。","voiceIndex":174,"id":"exchange-078"},{"speaker":"南委員","kind":"質問","question":"３カ所合わせて２２９床ということでいいのかどうか、後でいいですから、答弁をお願いします。そして、平成２４年度第２回の特別養護老人ホームの申込み状況について、伺います。介護度別と、年齢ごとの申請数、そして入れなかった数、何人でしょうか。","respondent":"早津健康福祉事業部長","answer":"要介護５が３５人、要介護４が８３人、要介護３が１０２人、要介護２が２０人、要介護１が３人です。年齢別は、１００歳以上が７人、９０歳代が８２人、８０歳代が１２７人、７０歳代が２４人、６０歳代が３人という状況です。","voiceIndex":176,"id":"exchange-079"},{"speaker":"南委員","kind":"質問","question":"第２回のこのときの募集数というのは、かえで荘の改修が終わったので、その分いつもより多かったのではないでしょうか。それでも４５２人が入れませんでした。区はこれから３カ所つくり、２２９床プラスアルファかもしれないと、先ほど、答弁されましたけれども、今回入れなかった数の半分に相当する方しか、受入れ枠がないということですよね。これで足りていると言えるのかどうか、見解を伺います。","respondent":"早津健康福祉事業部長","answer":"現在は６５３のベッド数ですが、これに２２９床が加わります。１.３５倍ということで、かなりのベッド数が増えることになっておりますので、それに応じてかなりの方が入所できるようになると考えているところです。","voiceIndex":180,"id":"exchange-080"},{"speaker":"南委員","kind":"質問","question":"聞いたことにまともに答えていただけてない、そういうふうに思います。今回の入れなかった数、そこから見て、これからつくろうとしている数を比較してみると、もう半分の方しか入れないという、こういう現状をどういうふうに見るかという質問をしました。もう一度、大事なところなのでご答弁ください。","respondent":"早津健康福祉事業部長","answer":"そういう意味では、たくさんの方がいろいろな希望を抱えておられますので、４５０人の方が一律の考え方をとっているというふうには、私は思っておりません。","voiceIndex":182,"id":"exchange-081"},{"speaker":"南委員","kind":"質問","question":"今、部長がご答弁された、断るという方は、この４５２人のうちの何人でしょうか。そういうふうにご答弁されるのなら、改めて伺いたいと思います。毎朝４時に起こされる。こういう現実をしっかり直視すべきだと思います。必要な方は入っている、足りているとおっしゃるけれども、こういう現状を見たときに、本当にそういうふうに言えるのか、改めて伺いたいと思います。","respondent":"早津健康福祉事業部長","answer":"例に挙げられた方は、具体的にどういう方か承知できませんので、なかなかお答えが難しいわけですが、特別養護老人ホームという福祉施設の場合、医療介護には一定の限界があります。","voiceIndex":184,"id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"今の現状をちょっと紹介して、必要な人が入れていると認識しているかというふうに伺ったのですが、その答弁がありません。これについて、区は増設をしていく計画は持っておられますけれども、私は、旧荏原第四中学校跡の暫定活用が来年の９月で終わるので、ここに一刻も早く特別養護老人ホームと老人保健施設をつくっていただきたい、こういうふうに思いますが、この点についても、いかがでしょうか。","respondent":"早津健康福祉事業部長","answer":"老人保健施設につきましては、適地があれば１カ所はつくっていきたいという考えに変わりはございません。","voiceIndex":186,"id":"exchange-083"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどから繰り返し申し上げてますが、区民の深刻な事態、ここをもっと知るべきです。調査をするなり、意見を聞くなり、やはりきちんとつかむべきです。特別養護老人ホームの増設、それから老人保健施設の増設、これをしっかりと計画に盛り込んでいただきたいということを重ねてお願いしたいと思います。最後に、障害者の就労施設の増設も求めたいと思います。この点を伺います。","respondent":"早津健康福祉事業部長","answer":"平成２６年度、来年４月の卒業生等の状況を見ますと、受入れは大丈夫という状況です。","voiceIndex":188,"id":"exchange-084"},{"speaker":"南委員","kind":"質問・要望","question":"ここも実態はかなり深刻です。障害者の皆様が楽しく通っていける、そして一人ひとりの処遇をほんとうに適切にしていただく、このことが大事なので、きちんと実態を見ていただき、現場の声も聞いていただき、保護者の声も聞いて対応していただきたいとお願いをしておきたいと思います。増設計画をつくり、区民の期待に応えるよう強く求めて、私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-085"},{"speaker":"石田（ち）委員","kind":"質問","question":"共産党区議団の総括質疑を続けます。補助２９号線がどこを通るのか、ルート、幅、長さ、立ち退きを迫られる道路上の世帯数、沿道の世帯数を伺います。そして、この補助２９号線がなぜ防災の役に立つのか、どのような効果があるのか、効果があると説明する根拠は何か伺います。","respondent":"片田都市環境事業部長","answer":"道路内の建築物、これは前にもご答弁させていただいていますけれども、５５０棟ということで、これは机上の数値ですけれども、沿道３０ｍの範囲の中では、１,９９０棟というような認識を持ってあります。","voiceIndex":192,"id":"exchange-086"},{"speaker":"石田（ち）委員","kind":"質問","question":"棟数は前にお聞きしているのです、道路上の世帯数を聞いているのです。そして、東京都が補助２９号線は防災に役立つと、根拠を示すのが、東京都の延焼シミュレーションです。そこでシミュレーションの前提条件をお聞きします。風速、風向き、車両の有無、火の粉の有無、沿道建築物の状況など、条件を伺います。西大井四丁目、ナンバーＲ０３０、延焼棟数９５０棟が何棟に改善するのか、それぞれ伺います。","respondent":"片田都市環境事業部長","answer":"道路を入れたときに、これについては変わらなくて、２０９棟という状況です。Ｒ００９というところについては、１,４９１棟が１,２１８棟に改善される、Ｒ０３０については、９５０棟が８５８棟に改善されると、そのようなシミュレーションの状況と確認しております。","voiceIndex":194,"id":"exchange-087"},{"speaker":"石田（ち）委員","kind":"質問","question":"１番、大崎四丁目です。補助２９号線の入口、整備前の延焼棟数は２０９棟、今、お答えいただきましたけれども、道路ができても２０９棟と。ここでは１棟も延焼を防げていないのです。そして、最後、西大井四丁目、整備前９５０棟の延焼が、道路ができても８５８棟も燃えてしまいます。これで、道路が防災対策になるとなぜ言えるのか伺います。こんなに広大に燃えてしまうのに、防災となぜ言えるのか伺います。","respondent":"片田都市環境事業部長","answer":"道路もしかり、河川もそうですし、鉄道敷き、これについても延焼遮断効果があるといったような考え方が言えるかと思っています。したがいまして、防災対策として、行政としては進めていくという考え方に変わりありません。","voiceIndex":196,"id":"exchange-088"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、道路ではないものも延焼を防ぐというところでは、この道路は、特にそこまで延焼を防いでいないのかというふうにも聞こえました。品川区は、東京都が行ったシミュレーションで、防災上効果ありという結果が出た、この都市計画道路を特定路線として選定したと、説明してきているのです。こんなに燃えてしまうのに、なぜ効果があるのか、なぜ選定したのか伺います。","respondent":"片田都市環境事業部長","answer":"ですので、私どものほうとしては、道路の整備と周辺の不燃化を進めることによって、十分な効果が期待できるということで考えております。","voiceIndex":198,"id":"exchange-089"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その一つは風向きです。安全性も検証されていないのに、なぜ安全と言えるのかと、検証も求めてきました。三つ目に火の粉です。震災時は、瓦や壁の表面が崩れ落ち、下地が露呈し、燃えやすくなる、火の粉などの飛び火をなぜ想定しないのでしょうか、伺います。実態と全く合っていない現実離れしたこの条件で行われたシミュレーション、なぜ効果ありと言えるのか、改めて伺いたいと思います。","respondent":"片田都市環境事業部長","answer":"それから火の粉についても、確かに燃え上がれば火の粉が飛ぶということはありますけれども、これは前にもご紹介いただきました墨田区のほうの内容についても、そういうことの中で不燃化を進めることによって効果があるということが言えておりますので、区のほうとしては。","voiceIndex":200,"id":"exchange-090"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なぜ効果があると言えるのか、というところを、改めて伺いたいのです。そこを伺いたいと思います。道路だけでも４,１８６世帯もの住民を追い出し、商店街やまちを分断し、長年築き上げたコミュニティを壊す、命の道と言いながら炎の道となる可能性のある、車両火災の検証もない、こんな補助２９号線はやめるべきと強く求めます、いかがでしょうか。","respondent":"片田都市環境事業部長","answer":"それ以外の６７件見ると、すごくよくなっております。そういう意味では、効果があるということで認識しております。それから、車両の関係です。もし首都直下型が来れば、環状７号線以内には車は入らないようにという制限を、当然、警視庁のほうでかけるといったような状況です。","voiceIndex":202,"id":"exchange-091"},{"speaker":"石田（ち）委員","kind":"質問","question":"いろいろ同時に進めていくと言われていますけれども、私は、補助２９号線の防災効果についてを聞いているのです。そして、いろいろ焼けどまっているということもおっしゃいますけれども、このシミュレーションを見て、私は本当に驚いたのです、こんなに燃え広がるのかと。こんなに燃えて、補助２９号線のどこに防災効果があるのかということ、ここをもう一度伺いたいと思います。","respondent":"片田都市環境事業部長","answer":"先ほどのシミュレーションでありましたように、全ての点で効果があるということで、焼けどまったということが、何よりの証拠かと考えております。","voiceIndex":204,"id":"exchange-092"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もうそのようにしか言えないのかと思います。ここで具体的な対策を求めたいと思います。戸越一、二丁目の街並み誘導型地区計画、国土交通省も評価しているこの手法、これを区内全域に広げるべきと考えますが、いかがでしょうか。そして、スタンドパイプは増配備をし、スタンドパイプが災害時きちんと使えるように上水道管の耐震化１００％を東京都に求めていただきたいと思いますが、いかがでしょうか。","respondent":"片田都市環境事業部長、松代防災まちづくり事業部長","answer":"戸越一丁目の街並み誘導ですけれども、地元の協議会ときちっとルールを決めた中で進めなければいけない事業ですので。これに対する区の考え方としましては、個人財産、住居の設備に関するものであり、自由の範囲であること、ガスのマイコンメーターと同様に。墨田区がやっているような耐火パネル等々については、昨年の７月から。","voiceIndex":206,"id":"exchange-093"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"スタンドパイプを災害時にきちんと使えるように、上水道管の耐震化は東京都が責任があるというところですけれども、これを１００％まで強力に求めていただきたいのです。こういった地域で住民参加の防災のまちづくりを進めていくためにも、自治体が支援をしていくことを進めていただきたいと思います、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"感震ブレーカーに対する区の考えは、先ほど申し上げたとおりです。","voiceIndex":210,"id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"水道管は、東京都は５４％の耐震目標しか持っていないのです。ですので、これを１００％にしなければ、まちの火は消せないということになりますので、お願いしたいと思います。補助２９号線を防災として必要としたシミュレーションの根拠は、もはやありません。住民追い出し、逆に危険を呼び込む道路ではなく、家を壊さない、燃やさない、燃えたらすぐに消す対策を強く求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-095"},{"speaker":"本多委員","kind":"質問・要望","question":"平成２４年度各決算審議にあたり、品川区議会自民党の意見表明を行います。品川区を取り巻くさまざまな諸課題に対応するべく、積極的な施策の展開と、教育改革プラン２１における学力向上と道徳の心をより一層強化を図り、誇りある品川、誇りある東京、誇りある日本構築を望み、あわせまして、我が会派の提言、意見、武道館の建設をはじめ前向きにお酌み取りいただきますよう要望し、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-096"},{"speaker":"浅野委員","kind":"提案","question":"以下、その理由について要望を含めて申し上げます。最後に、本決算特別委員会にて、我が会派の委員が提案、要望した中で、木造住宅密集地域の不燃化促進や空き家対策などの防災対策、防犯対策、中小企業支援、子育て支援、高齢者・障害者の福祉施策、環境、経済、人権、教育などに対する意見を、来年度の予算編成をはじめ区の各実施事業に十分に反映されますよう要望いたしまして、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":217,"id":"exchange-097"},{"speaker":"いながわ委員","kind":"提案","question":"施策の情報が、障害者を含め必要とする区民に確実に届くよう、広報や説明のあり方について、一層の工夫を求めます。本委員会における我が会派の指摘や提案が次年度予算のみならず、今後の本区施策に反映されるよう強く要望するとともに、７年後のオリンピック・パラリンピックに向け安心・安全、誰もが住みやすいまちづくりの総合的な推進を要望し、民主・改革ネットの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":219,"id":"exchange-098"},{"speaker":"須貝委員","kind":"質問・要望","question":"みんな・無所属品川は、平成２４年度の品川区一般会計、国民健康保険事業会計、後期高齢者医療特別会計と介護保険特別会計の各歳入歳出決算を認定いたします。首都直下型大地震に備え、防災や減災対策をより拡充させるとともに、学校の教員にゆとりを与え、一人ひとりの子どもと向き合える時間をつくることを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"就学援助金などに連動しないよう対策を求めます。その他、歯科検診の啓発と年齢拡大、コミュニティバスを病院や公共施設、商店街や駅などを結んで運行させること、生鮮三品店などへの支援と商店街装飾灯の電気料金値上げ分の補助金増額など、商店街支援の強化、南品川と東大井など、公衆浴場のない地域に、お風呂に入れるための支援など、区民の切実な要望に応えるよう求めて、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-100"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":91613,"voices":228}},{"id":"h25-20131031-8","meetingId":"h25-cm10","date":"2013年10月31日","dateIso":"2013-10-31","committee":"建設委員会","time":"午前１１時００分～午後 ３時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"これはこの大会、目的のところ、書いてありますけど、リニア中央新幹線の位置づけがあるのかどうか、ちょっとそれを一点お伺いしたいのと、あと都市計画道路、都内全体で何本事業が進められているか、その進められている本数と、あと品川区は特定整備路線、申請をしていますけれども、この辺、どことどことどこが含まれているのか、具体的に教えてください。","respondent":"藤田都市計画課長","answer":"これらの事業と、それから特定整備路線については、ちょっと今回の中でどこまで記述、あるいは項目が入ってくるかというのはちょっとはっきりはしておりませんが、道路整備事業全体で考えれば、特定整備路線でありましても、それから今行っている第３次の優先整備路線であり。","voiceIndex":9,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"意見","question":"区内では特定整備路線、この間進められようとしていますけれども、防災、木密１０年プロジェクトとセットになっていて、防災の効果というところも前面に押し出されていますけれども、区内においてもうこれ以上の道路は要らないと主張していらっしゃる方々、そして、防災の効果がはっきりしない、疑われている中での、この道路計画は必要ないといった運動もされている方が多い中で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-002"},{"speaker":"あべ委員長","kind":"質問・要望","question":"委員長としては、あくまでも申し合わせ確認事項に従って建設委員会として参加するものですので、ご協力をいただきたいと考えております。これについては、様々な議論がありましたけれども、改めて平成２２年の議会運営委員会の中で申し合わせは変えないという合意がありましたので、それを尊重していただきたいという思いはございました。それだけはお伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"}]},{"id":"topic-02","title":"ウォームビズキャンペーンの実施について","agenda":"ウォームビズキャンペーンの実施について","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"庁舎は１９度の設定でということなんですけれども、区役所の庁舎の場所によって、下から上までですごく温度差があると思うんですよね。暑いというのはないかもしれない、寒いところの職場の方が、体を、体調を壊されては困るので、その辺細やかにチェックして１９度が保たれればいいんですけど、工夫をしていただきたいと思います。いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"例年やってまして、そういう声は聞いておりますので、経理課等と相談しながら工夫してまいりたい、そのように考えております。","voiceIndex":20,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"それから同じように、クールビズもありますから、うまく言えないんですけど、これだけを進めていくと夏暑くなっちゃうわけじゃないですか。逆にクールビズを進めていくと冬が寒くなるという話なんだけど、今飯沼委員がおっしゃったように職員の方がこれで影響があってはいけないので、そういう窓の対策とかそういうものについてはどうお考えなんでしょうかということをお聞かせください。","respondent":"野呂瀬環境課長","answer":"これを必ず遵守するというものでもないんですけど、体調を壊したら元も子もありませんので、先ほどの飯沼委員と一緒なんですけれども、庁舎管理等と連携を取りながら工夫して事業を進めてまいりたい、このように考えております。","voiceIndex":23,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"例えば、扇風機とか、何ていうんだろう、そういうことで循環させればいいとかといいますよね。そういうのも少し加えることによって、区民の方が使われる施設ですから、そういう工夫ができるんじゃないかなというのが一つ。だけど、結局はどうだったんですか、達成されたんですか。","respondent":"野呂瀬環境課長","answer":"これは、冬場においても同じでございまして、東京電力の余剰電力もまた冬の報告とか来るでしょうけれども、その電力が余剰があったとしても意識としてはやっていくという形で今までどおり継続してクールビズキャンペーンを行っていきたいと、このように考えているところです。","voiceIndex":25,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ対応というのはサイトを使ってとかいろいろな形でぜひ。去年、おととしも震災があったというのもあるのでしょうけれども、非常に我慢される方が多かったという現状があるので、そこもある程度、何でしょうか、あまり緩くしても困るし、きつくても困るしという、非常にキャンペーンの仕方は難しいと思うんですが、工夫して配慮していただきたいということで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"福島県は、原発の問題があるので１年というスパンじゃないと思うんですよね。それはどうされるのですか、考え方として。再建してもらったほうがいいので進めていただきたいと思うんですが、そうじゃない地域があって、区内の中でどれだけいらっしゃるかわからないんです。ただ、そこはまだまだ現状として復帰なんか、再建ができるわけないので、その考えはいかがですか。","respondent":"大串住宅担当課長","answer":"私どもは、あくまでも被災県からの要請に基づいて行っているものです。福島県側から福島県の避難者の方々については２７年３月３１日まで伸ばしてほしいという要請が来ましたので、それに基づいて動いているだけです。","voiceIndex":31,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"すみません、そうすると、福島県から２７年の３月というふうに言われているので、それに従ってやっていますよということなんですね。ということは、そういう現状じゃないところについては、福島県のほうに言わないと難しいですよ。それは２７年の３月に出ていってくださいと言うのか、区はどういうふうに対応されるんですか。","respondent":"大串住宅担当課長","answer":"この入居期間の関係等々につきましては、基本的に被災県と、その被災県から避難している方々との間でやりとりをされるものです。私ども区のほうで何かそれについて関与するというところはございません。","voiceIndex":33,"id":"exchange-009"},{"speaker":"西本委員","kind":"確認","question":"最後に確認だけ。これ、ご存じだったらでいいんですけど、例えば避難区域という、まだ原発の問題、放射能問題で区内の中に該当する方が何人いるかという、ご存じであれば。存じ上げないまでも、それはあれなんですけど、存じていられるのであればちょっと教えてほしい、数。","respondent":"大串住宅担当課長","answer":"あくまでも福島県のほうから被災ということでこちらに避難しているということで、福島県のほうから情報はいただいているところですけれども。それ以上のものというのは特には把握しているものではございません。","voiceIndex":35,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一点なんですけれども、解体工事等新築の建物の中身についても一緒に説明をするということですよね。特に商店街ですよね。道路幅が狭いところの工事ということでは影響が大きい。後で知りましたというのが多いんです。なので、やっぱり最初のところできちんとお伝えする必要があるので、もうちょっとご周知の範囲を検討していただきたいと思いますがいかがでしょうか。","respondent":"品川木密整備担当課長","answer":"その辺の、重要拠点といいますかポイントになる部分につきましては、やはり気を使った対応をしているです。","voiceIndex":40,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"個別にというところで、ここの主催が建築の事業主体ですよね。で、区のほうで別途に指導するということなんでしょうか。ちょっとその辺を。","respondent":"品川木密整備担当課長","answer":"これはあくまで工事説明会ですので、区のほうで、説明に行くというよりは、これも大成建設さん、それから松田平田設計さんのほうで説明は持っているです。","voiceIndex":42,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後です。ぜひ事業者さんにやはり広範のところの理解を得るという意味で、丁寧な周知をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"確認です。多分昔からあったとすれば、便宜を図ってくれよとかいろいろやって、お礼をという形なんでしょうけど、そこら辺も含めて職員の方たちにはこういう状況があるのでしっかりと、昔と今は違うんだよみたいな感じでご指導していただきたいと思うんですが、その辺はいかがなんでしょうか。そこら辺は詰められているんでしょうか。報道のとおりなのかというか。","respondent":"小林品川区清掃事務所長","answer":"ただ、一つは、特段何かをやってほしいからという趣旨はなかった、またもちろん職員のほうからそれを求めたものでは決してないということで、基本的に事件性にまでは至ってないけれども、とにかく不適切な行為ということで申しわけなく思い、是正を図っていきたいと考えています。","voiceIndex":48,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問・要望","question":"簡単に聞きますけれども、まず便宜を図っていなかったんですかというような確認を１点と、それから報告をもう少し具体的に教えてほしいと思うんですよ。この二つです。","respondent":"小林品川区清掃事務所長","answer":"大変不十分な対応と反省してますが、そのときに相わかったということですので、それでその後ご本人あるいは組合とのやりとりというのは大きいものはございませんでした。","voiceIndex":50,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4088#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":11909,"voices":53}}]);
